window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gineco-gin-2"]={"block":"medcurso:medcurso-gineco-gin-2","label":"Medcurso · GIN 2","count":451,"questions":[{"id":"medcurso-gineco-gin-2-343756","number":"343756","sourceNumber":"343756","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, com histórico de dismenorreia intensa, há cerca de cinco anos,\nque a impede de realizar suas atividades\nhabituais, relata que o motivo principal de sua consulta é\na dificuldade em engravidar. Relata ciclos menstruais regulares, de 28 dias. Relata que o parceiro\nfez espermograma, e que o exame não mostrou alterações. Está sem uso de método contraceptivo\nhá 4 anos, e mantendo relações sexuais cerca de 4x por semana. A abordagem mais adequada a\nesse caso é:","options":{"A":"Iniciar contraceptivos hormonais orais, visando bloquear o ciclo menstrual e melhorar o quadro\nde dor da paciente.","B":"Orientar a paciente que use analgésicos e anti-inflamatórios no período menstrual, e realizar\nreprodução assistida, com vistas à maior probabilidade de gestar.","C":"Tranquilizar a paciente, já que ela tem menos de 35 anos, que ela deve seguir tentando\nengravidar até os 35 anos, para então, prosseguir com alguma intervenção clínica.","D":"Usar o DIU hormonal, pois assim melhora a dor, e após 5 anos, iniciar as tentativas de gestar."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343763","number":"343763","sourceNumber":"343763","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 49 anos, referindo irregularidade menstrual há aproximadamente 6 meses, com\naumento do volume sanguíneo e diminuição do intervalo entre um sangramento e outro (6 dias de\nsangramento/ 25 dias de intervalo). Nega dor em baixo ventre, leucorreia, ou sintomas gerais.\n\nExame físico geral e ginecológico normais. Nega antecedentes patológicos pessoais e familiares.\nG4/3PN 1A. Apresentou na ocasião mamografia\nBR1, colpocitologia oncótica negativa para células\nneoplásicas e ultrassonografia transvaginal evidenciando útero com volume de 106 cm3 endométrio\n(14 mm), ovários com volumes normais. Presença de imagem hipoecogênica com 2,5 cm intramural\ncom componente subseroso. Diante do caso, qual o diagnóstico mais provável para o sangramento\nanormal e tratamento?","options":{"A":"Mioma uterino - histerectomia.","B":"Adenomiose - Progesterona contínuo.","C":"Neoplasia de colo uterino - Amputação de colo.","D":"Climatério - TRH."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343768","number":"343768","sourceNumber":"343768","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 15 anos, comparece ao ambulatório de ginecologia com queixa de\nsangramento irregular nos últimos 6 meses, com\nciclos variando entre 40 e 25 dias e fluxo pouco\naumentado. Na história prévia ela informa menarca aos 14 anos e ainda não iniciou vida sexual. Ao\nexame físico você verificou que ela apresenta os caracteres sexuais secundários. Diante do quadro\nqual a hipótese diagnóstica mais adequada para essa faixa etária?","options":{"A":"Atrofia endometrial.","B":"Imaturidade do eixo hipotálamo-hipófise-ovários.","C":"Câncer de colo uterino.","D":"Endometriose."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343769","number":"343769","sourceNumber":"343769","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"De acordo com o sistema de classificação das causas de sangramento uterino anormal\nproposto pela Federação Internacional de Ginecologistas e Obstetras (FIGO). São consideradas\ncausas estruturais, exceto:","options":{"A":"Pólipo endometrial.","B":"Mioma submucoso.","C":"Síndrome dos Ovários policísticos.","D":"Hiperplasia endometrial atípica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343772","number":"343772","sourceNumber":"343772","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre a endometriose, é correto afirmar:","options":{"A":"Caracteriza-se pela presença de glândulas endometriais e estroma fora da cavidade uterina,\nexclusivamente na pelve feminina.","B":"A endometriose profunda é quando a foco de endometriose tem invasão tecidual maior que\n5mm. Essas lesões geralmente estão localizadas\nno ligamento útero-sacro e no fundo de saco de\nDouglas.","C":"O foco endometrial ectópico não apresenta resistência à ação da progesterona.","D":"O marcador tumoral CA-125 é muito útil no diagnóstico da endometriose, sendo excluída a\npossibilidade da doença quando o marcador é negativo."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-345486","number":"345486","sourceNumber":"345486","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 36 anos, nulípara portadora de mioma uterino de 4cm, com deformidade da\ncavidade endometrial, foi investigada por infertilidade, não sendo encontrada outra causa\netiológica.\nAssinale a alternativa que apresenta a conduta a ser seguida:","options":{"A":"Tratamento com análogos de GnRH.","B":"Miomectomia histeroscópica.","C":"Miomectomia laparoscópica.","D":"Expectante."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-291785","number":"291785","sourceNumber":"291785","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal jovem, ambos com de 33 anos, vem ao consultório porque desejam ter um filho.\nEla é tercigesta, nulípara. Há três anos\nvem tentando engravidar sem sucesso. Paciente referiu que\nantes ela conseguia engravidar, porém sofreu 3 abortamentos precoces, sendo o último há 4 anos.\nEm todas as gestações os embriões paravam de apresentar batimento cardíaco fetal antes de 9\nsemanas de idade gestacional. Todos os exames hormonais realizados não evidenciaram\nalterações. Cariótipo da paciente e do esposo: normais. Exame de imagem na época do último\nabortamento não evidenciou malformações uterinas. Realizou curetagem uterina no primeiro e no\nterceiro abortamentos. Ciclo menstrual costuma ser regular, porém há 5 meses não menstrua.\n\nSobre o estado clínico do casal, é correto afirmar:","options":{"A":"O casal não apresenta diagnóstico de infertilidade, pois já gestaram 3 vezes.","B":"O casal apresenta diagnóstico de infertilidade conjugal e uma possível causa da dificuldade atual\npode ser a Síndrome de Asherman.","C":"O casal ainda não apresenta diagnóstico de infertilidade e uma possível causa da dificuldade em\nengravidar atualmente pode ser a Síndrome de Asherman.","D":"O casal apresenta diagnóstico de infertilidade conjugal e uma possível causa da dificuldade\natual pode ser a Síndrome de Rokitansky."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-281135","number":"281135","sourceNumber":"281135","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A conduta no sangramento pós-menopausa com ultrassonografia pélvica normal é:","options":{"A":"Administração de estrogênio e progestogênio.","B":"Administração de progestogênio.","C":"Administração de estrogênio.","D":"Histeroscopia.","E":"Histerectomia total."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-283344","number":"283344","sourceNumber":"283344","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 60 anos de idade apresentando sangramento uterino. A conduta é:","options":{"A":"Ultrassom endovaginal.","B":"Terapêutica com reposição hormonal.","C":"Dosagem de CA-125.","D":"Teste de progesterona."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-283346","number":"283346","sourceNumber":"283346","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos de idade, com dismenorréia progressiva desde os 25 anos. Suas\ndores estendem-se, inclusive, fora do período\nmenstrual, causando-lhe incapacidade física.\n\nNecessita de medicamentos anti-inflamatórios rotineiramente e acha que o seu efeito tem diminuído\ncom o passar do tempo. Para a elucidação\ndiagnóstica, qual seria o exame subsidiário a ser\nsolicitado?","options":{"A":"Ultrassonografia pélvica.","B":"Laparoscopia pélvica.","C":"Dosagem dos marcadores tumorais.","D":"Tomografia pélvica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-283347","number":"283347","sourceNumber":"283347","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 39 anos de idade, com hipermenorréia, nuligesta e tentando engravidar há\ndois anos. A ultrassonografia transvaginal mostra três nódulos miomatosos, o maior medindo 5 cm\nde diâmetro. A conduta adequada nesse caso é:","options":{"A":"Miomectomia múltipla.","B":"Histerectomia subtotal.","C":"Histerectomia total.","D":"Histerectomia total com anexectomia bilateral."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-283348","number":"283348","sourceNumber":"283348","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente com 32 anos de idade queixa-se de dispareunia profunda e dor retal que piora\nno período menstrual. No toque notam-se nodulações em fundo de saco posterior e na região do\nsepto retovaginal. Qual a opção terapêutica?","options":{"A":"Uso de análogo de GnRH.","B":"Cirurgia com dissecção e exérese dos nódulos.","C":"Pílula anticoncepcional contínua.","D":"Gestrinona."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-251891","number":"251891","sourceNumber":"251891","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 54 anos, menopausa há 17 meses, tem queixa de corrimento vaginal\nserossanguinolento há um mês. O exame ginecológico revela atrofia genital, com petéquias na\nvagina. O laudo citopatologico de esfregaço cervical é: \"Inflamatório acentuado com atrofia;\npresença de células endometriais\". Está indicado:","options":{"A":"Cultura de secreção vaginal para tratar processo inflamatório.","B":"Reavaliar atrofia genital e processo inflamatório após tratamento.","C":"Investigar cavidade uterina.","D":"Avaliar menopausa com desogens hormonais."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-251893","number":"251893","sourceNumber":"251893","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Pacientes portadores de miomatose uterina apresentam, em geral, associação de\nvários tipos de leiomiomas. Desses, o que\nmais induz a sangramento uterino aumentado é o tipo:","options":{"A":"Subseroso.","B":"Submucoso.","C":"Intramural.","D":"Intraligamentar."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-251895","number":"251895","sourceNumber":"251895","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos, branca, nuligesta, com vida sexual ativa há 10 anos. Há quatro\nanos não faz uso de meio anticoncepcional.\nQueixa-se de dismenorréia, e o exame físico revela\nútero retrovertido, fixo, anexos aumentados de volume, císticos, dolorosos com pouca mobilidade.\nO CA-125 encontra-se elevado. A hipótese diagnóstica mais provável é:","options":{"A":"Doença inflamatória pélvica.","B":"Endometriose.","C":"Neoplasia maligna dos ovários.","D":"Tuberculose genital."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-247195","number":"247195","sourceNumber":"247195","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente com mioma uterino apresenta hematócrito de 24%. A ultrassonografia\ntransvaginal indica a presença de um mioma\npedunculado de 14cm no fundo do útero, com\nnumerosos miomas menores submucosos. A conduta inicial deve ser","options":{"A":"Miomectomia histeroscópica.","B":"Embolização das artérias uterinas.","C":"Transfusão de sangue.","D":"Histerectomia total abdominal e salpingooforectomia bilateral.","E":"Agonista do GnRH por 3 meses associado a sulfato ferroso."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-217657","number":"217657","sourceNumber":"217657","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 30 anos, G1 P1c A0, menarca aos 13 anos, queixa de dismenorreia\nprogressiva há 4 anos. Refere que a cólica,\npor vezes, é tão intensa, que precisa procurar\nassistência médica no pronto atendimento e não consegue ir para o trabalho. Nega uso de método\ncontraceptivo há 3 anos, pois está tentando engravidar. Sobre o caso clínico, podemos afirmar:","options":{"A":"A teoria que melhor explica a endometriose é a da menstruação retrógrada.","B":"O CA-125 é um marcador altamente específico para diagnóstico da endometriose.","C":"Devido ao desejo de concepção, pode-se indicar a videolaparoscopia para avaliar anatomia\npélvica e profundidade da doença.","D":"A sintomatologia da endometriose está relacionada ao grau de profundidade da lesão."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-217660","number":"217660","sourceNumber":"217660","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 60 anos, menopausa há 8 anos, sem uso de terapia hormonal, procura seu\nginecologista por apresentar sangramento uterino. Nega comorbidades. Ao exame físico: paciente\nem BEG, corada, hidratada, PA = 130 x 90 mmHg, IMC-26 kg/m². Exame ginecológico normal. USG\nendovaginal evidenciou lesão intrauterina hiperecogênica de 15 x 11 mm, contornos regulares, halo\nhiperecogênico ao redor, com vaso central ao Doppler. Qual a melhor conduta a ser adotada?","options":{"A":"Fazer dilatação do colo e curetagem uterina.","B":"Fazer biópsia endometrial ambulatorial com cureta de novak.","C":"Iniciar progesterona contínua.","D":"Realizar histeroscopia cirúrgica."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-183219","number":"183219","sourceNumber":"183219","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 40 anos, nuligesta, quer engravidar, há seis meses com relações sexuais\nsem uso de qualquer método contraceptivo.\nEstá preocupada porque acha que está muito próxima\nda menopausa e tem baixas chances de engravidar espontaneamente. Dentre outros exames, você\nrecomenda a dosagem de gonadotrofinas. Qual é o melhor dia do ciclo menstrual para realizar esse\nexame diante do atual cenário e com finalidade (avaliar reserva ovariana)?","options":{"A":"Dia 3.","B":"Dia 8.","C":"Dia 14.","D":"Dia 2.","E":"Dia 26."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-182717","number":"182717","sourceNumber":"182717","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Pacientes portadores de miomatose uterina apresentam, em geral, associação de\nvários tipos de leiomiomas. Desses, o que mais induz ao sangramento uterino aumentado é o:","options":{"A":"Subseroso.","B":"Submucoso.","C":"Intramural.","D":"Intraligamentar."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-182718","number":"182718","sourceNumber":"182718","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos, branca, nuligesta, com vida sexual ativa há 10 anos. Há quatro\nanos não faz uso de meio anticoncepcional.\nQueixa-se de dismenorréia, e o exame físico revela\nútero retrovertido, fixo, anexos aumentados de volume, císticos, dolorosos com pouca mobilidade.\nO CA-125 encontra-se elevado. A hipótese diagnóstica mais provável é:","options":{"A":"Doença inflamatória pélvica.","B":"Endometriose.","C":"Neoplasia maligna dos ovários.","D":"Tuberculose genital."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-159046","number":"159046","sourceNumber":"159046","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Dentre os abaixo, qual NÃO é considerado um fator de risco para endometriose?","options":{"A":"Maturação genética e polimorfismo.","B":"Toxinas ambientais.","C":"Multiparidade.","D":"Defeitos anatômicos."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-108712","number":"108712","sourceNumber":"108712","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em consulta de rotina na USF Mocinha Magalhães, uma adolescente de 13 anos vem\nacompanhada de sua mãe. A filha queixa-se\nde irregularidade menstrual e a mãe relata que sua\nfilha sempre tem um corrimento amarelado. Na anamnese, a adolescente relata à médica que teve\nmenarca há 1 ano e nega outras queixas geniturinárias, mesmo quando interrogada mais\nespecificamente em relação ao corrimento relatado pela mãe; também nega antecedentes pessoais\nrelevantes ou uso de medicações no momento. Ao exame físico, nada digno de nota. Qual a\nconduta que a médica de família e comunidade deverá adotar frente este caso?","options":{"A":"Explicar que pode ocorrer irregularidade menstrual até dois anos após a menarca, orientar sobre\na higiene, ressaltando que, nesta fase, é\nnormal o aumento da secreção vaginal (mucorreia) devido\na alterações locais.","B":"Solicitar EAS e cultura da secreção vaginal e esclarecer à mãe que a irregularidade menstrual é\nnormal nos primeiros anos após a primeira menstruação.","C":"Solicitar perfil hormonal devido à irregularidade menstrual apresentada, além de EAS e cultura\nda secreção vaginal.","D":"Investigar obrigatoriamente abuso sexual, conversando em separado com a mãe e a filha sobre\nas queixas trazidas e acionar o conselho\ntutelar."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-108759","number":"108759","sourceNumber":"108759","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 28 anos de idade, G3P2NA1. Vem apresentando hipermenorragia há 6\nmeses, associada à cólica uterina. Trouxe exame\nultrassonográfico que mostrou um nódulo\nmiomatoso intramural de 6 cm³ com leve abaulamento do endométrio e outro subseroso de 5 cm³.\nHemoglobina normal. Qual a conduta mais adequada?","options":{"A":"Indicar miólise;","B":"Indicar histerectomia por via vaginal;","C":"Indicar miomectomia via histeroscópica;","D":"Indicar miomectomia por laparatomia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-108773","number":"108773","sourceNumber":"108773","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 20 anos de idade vem à unidade básica de saúde com queixa de períodos\nmenstruais com sangramento abundante (menorragia). É virgem, o exame físico é normal, não há\nsinais de anemia e a ultrassonografia pélvica demonstrou útero de 60cm³ de volume e ovários ao\nredor de 5cm³. Miométrio homogêneo e endométrio normo-espessado. A melhor conduta a ser\ntomada é:","options":{"A":"Prescrever anticoncepcionais orais combinados cíclicos;","B":"Prescrever anticoncepcionais progestacionais de depósito;","C":"Prescrever anticoncepcionais orais combinados de uso contínuo;","D":"Prescrever antifibrinolíticos e AINES durante o período de sangramento."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-66970","number":"66970","sourceNumber":"66970","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 12 anos, menarca aos 11 anos, é atendida na emergência clínica por\nsangramento genital intenso. O nível de hemoglobina é de 8,5 g/dl. Todas as hipóteses\ndiagnósticas abaixo deverão ser consideradas, EXCETO:","options":{"A":"Sangramento disfuncional, anovulatório;","B":"Gravidez;","C":"Pólipo;","D":"Coagulopatia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-50089","number":"50089","sourceNumber":"50089","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Menina de 5 anos de idade é levada ao pronto-socorro após a mãe perceber que a\ncriança estava com sangramento vaginal de pequena quantidade, acompanhado por secreção\nfétida amarelada abundante. O exame ginecológico permitiu a visualização de hímen íntegro e\ncoloração da mucosa vaginal normal. Qual a sua primeira hipótese?","options":{"A":"Abuso sexual;","B":"Menarca precoce;","C":"Corpo estranho vaginal;","D":"Vulvovaginite por cândida;"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-50117","number":"50117","sourceNumber":"50117","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente portadora de síndrome dos ovários policísticos, frequentemente, vai\napresentar aumento na resistência à insulina. Isso vai resultar em um aumento de (o):","options":{"A":"Hormônio foliculoestimulante (FSH);","B":"Nível de estrogênio livre;","C":"Nível de testosterona livre;","D":"Produção hepática de globulina de ligação de hormônio sexual (SHBG);"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-50127","number":"50127","sourceNumber":"50127","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente queixa-se de hipermenorréia. Foram afastadas causas anatômicas para\na magnitude de seu fluxo. Qual dos itens a\nseguir demonstrou poder ser MAIS EFICAZ na redução\nde seu fluxo menstrual?","options":{"A":"Ácido tranexâmico;","B":"Dilatação e curetagem uterina;","C":"Acetato de medroxiprogesterona;","D":"Maleato de metilergometrina."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-37061","number":"37061","sourceNumber":"37061","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 35 anos, casada há 10 anos, nuligesta, sem uso de método contraceptivo,\ncom história de dismenorreia desde a menacme,\ntrata-se provavelmente de:","options":{"A":"Infertilidade primária.","B":"Adenomiose.","C":"Infertilidade primária secundária a endometriose.","D":"Dismenorreia primária associada a infertilidade primária.","E":"Infertilidade primária secundária a doença inflamatória pélvica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-37064","number":"37064","sourceNumber":"37064","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em países subdesenvolvidos, a principal causa da infertilidade é:","options":{"A":"Infertilidade secundária à endometriose.","B":"Infertilidade secundária à adenomiose.","C":"Infertilidade primária idiopática.","D":"Infertilidade secundária à doença inflamatória pélvica.","E":"Infertilidade secundária a aderências pós-cesarianas."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-37065","number":"37065","sourceNumber":"37065","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Os miomas terão indicação cirúrgica sempre que, exceto:","options":{"A":"Tiverem crescimento rápido.","B":"Causarem dor por compressão local.","C":"Causarem sangramento uterino anormal.","D":"Forem causa de infertilidade.","E":"Tiverem diâmetro maior a 5cm."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-37072","number":"37072","sourceNumber":"37072","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O sangramento uterino anormal poderá ter as seguintes condutas, exceto:","options":{"A":"Anti-inflamatórios não hormonais.","B":"Progestágenos.","C":"Estrogenioterapia em alta dose.","D":"Agentes antifibrinolíticos.","E":"Inserção de DIU medicado com cobre."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-29427","number":"29427","sourceNumber":"29427","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 40 anos de idade, vem à consulta para apresentar Ultrassonografia\nTransvaginal (USGTV) com imagem de mioma intramural\nmedindo 5 cm no maior diâmetro, ciclos\nmenstruais com padrão normal, leves dores em baixo-ventre, sua conduta será:","options":{"A":"miomectomia.","B":"histerectomia.","C":"progesterona para redução do mioma.","D":"análogos do GnRH para redução do mioma.","E":"orientações e seguimento anual com USGTV."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343204","number":"343204","sourceNumber":"343204","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente tem diagnóstico de sangramento uterino anormal por câncer de\nendométrio. Utilizando o método diagnóstico pelo anagrama PALM-COEIN, a referida patologia\nencontra-se na letra:","options":{"A":"M","B":"N","C":"L","D":"P"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343206","number":"343206","sourceNumber":"343206","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente com quadro de infertilidade realiza histerossalpingografia que evidencia\nimagem em ?contas de Rosário?. A mais provável causa envolvida é:","options":{"A":"DIPA.","B":"Tuberculose.","C":"Endometriose.","D":"Adenomiose."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343210","number":"343210","sourceNumber":"343210","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação à miomatose uterina, assinale a alternativa falsa.","options":{"A":"Os análogos do GnRH são aprovados par utilização por curtos períodos, de aproximadamente 4\na 6 meses.","B":"Os análogos de GnRH somente são utilizados de forma isolada, quando não é factível a cirurgia.","C":"Os análogos de GnRH tem a desvantagem de causar fogachos e aumentar o risco de\nosteoporose.","D":"Miomas assintomáticos não requerem tratamento cirúrgico."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-314222","number":"314222","sourceNumber":"314222","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal em união estável há 5 anos, sem utilizar qualquer tipo de contraceptivo, com\nqueixa de não conseguir engravidar. Na abordagem inicial, não faz parte da investigação:","options":{"A":"Espermograma.","B":"Biópsia testicular.","C":"Pesquisa hormonal de ovulação.","D":"Espermocultura."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-314226","number":"314226","sourceNumber":"314226","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação ao exame de histerossalpingografia, assinale a alternativa incorreta.","options":{"A":"É o exame mais utilizado para investigação da infertilidade de causa tubária.","B":"Permite a visualização dos ovários e detecta eventuais lesões nos mesmos.","C":"A ?prova de Cotte? positiva indica trompas pérveas","D":"Estudando a anatomia das tubas uterinas é possível identificar pontos de obstrução"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-315199","number":"315199","sourceNumber":"315199","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Para os casais com infertilidade conjugal, devemos seguir investigação nos seguintes\npontos, EXCETO:","options":{"A":"O espermograma avalia diversos parâmetros, entre eles a contagem e a motilidade dos\nespermatozóides.","B":"Avaliação da permeabilidade da tuba uterina com histerossalpingografia e a cromotubagem\natravés da laparoscopia.","C":"Não inclui investigação de patologias infecciosas na infância do homem, bem como atividade\nlaboral do mesmo.","D":"A ultrassonografia seriada transvaginal pode ser solicitada para investigação da reserva\novariana ou na suspeita de anovulação crônica associada.","E":"Endometriose e doença inflamatória pélvica são doenças causadoras da infertilidade conjugal\n(por causarem aderências pélvicas), sendo esta\núltima associada a infecções por Neisseria\ngonorrohoeae ou por Chlamydia trachomatis, podendo gerar aderências em forma de ?cordas de\nviolino? em uma fase crônica da infecção."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-276004","number":"276004","sourceNumber":"276004","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre leiomiomas, assinale a resposta INCORRETA.","options":{"A":"Pacientes com miomatose uterina volumosa e sangramento uterino anormal associado podem\nse beneficiar de análogos de GnRH no controle do\nsangramento.9","B":"Podem ser classificados conforme sua localização em submucoso, intramural e subseroso,\npodendo este último ser confundido. pela sua\nlocalização, com pólipos endometriais.","C":"Tendem a reduzir de volume após a menopausa dada sua resposta a estrogênios, em queda\nneste período da vida reprodutiva.","D":"O tratamento de escolha varia conforme a idade, paridade e sintomatologia associada.","E":"São tumores benignos da musculatura lisa e podem se associar a complicações gestacionais."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-280444","number":"280444","sourceNumber":"280444","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 32 anos, 2 filhos, assintomática, comparece a consulta ginecológica\napresentando laudo de ultrassom que evidenciou\nimagem nodular hipoecogênica de 3 cm\nlocalizada na espessura da parede uterina, sem comprometimento de endométrio. A hipótese\ndiagnóstica mais provável é","options":{"A":"mioma intramural.","B":"pólipo endometrial.","C":"adenomiose.","D":"mioma submucoso."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-278655","number":"278655","sourceNumber":"278655","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 76 anos, magra, tendo como antecedentes hipertensão arterial bem\ncontrolada, procura Ginecologista com queixa de sangramento discreto via vaginal de início há 5\ndias. Nega outros sintomas. A causa mais comum de sangramento nesse caso é","options":{"A":"atrofia endometrial.","B":"câncer de endométrio.","C":"pólipo cervical.","D":"hiperplasia atípica endometrial."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-280445","number":"280445","sourceNumber":"280445","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Não representa indicação de histeroscopia,","options":{"A":"pólipo endometrial.","B":"mioma subseroso.","C":"sangramento uterino anormal.","D":"hiperplasia endometrial."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-278658","number":"278658","sourceNumber":"278658","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Droga que não deve ser utilizada de forma isolada no tratamento de endometriose","options":{"A":"Anticoncepcional combinado oral.","B":"Dienogeste.","C":"Desogestrel.","D":"Estradiol."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-280450","number":"280450","sourceNumber":"280450","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Região intestinal mais acometida por endometriose.","options":{"A":"Retossigmoide.","B":"Cólon Transverso.","C":"Apêndice.","D":"Cólon Ascendente."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-279082","number":"279082","sourceNumber":"279082","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A videolaparoscopia já teve papel fundamental no diagnóstico de endometriose, porém,\natualmente, com o aprimoramento dos métodos de imagem, sua principal indicação é","options":{"A":"somente para estadiamento.","B":"para pacientes que tem exames radiológicos normais e falha no tratamento clínico.","C":"para pacientes com quadros leves.","D":"para pacientes em tratamento de infertilidade de causa ovariana."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252909","number":"252909","sourceNumber":"252909","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 34 anos de idade, nuligesta, casada, tenta engravidar há 1 ano e 6 meses sem\nsucesso. Nega comorbidades. Refere ciclos menstruais regulares, durando 5 dias com fluxo\nnormal, porém com dismenorreia leve. Também queixa de dispareunia de profundidade. Nega\noutros sintomas. Ao exame especular, conteúdo vaginal fisiológico e colo sem alterações. Ao toque\nvaginal, útero em anteroversoflexão, de volume normal, desconforto à mobilização do colo.\n\nAusência de dor à palpação de anexos. Diante do quadro descrito, indique a conduta a ser\nadotada.","options":{"A":"Investigar a causa da infertilidade e solicitar espermograma para o parceiro; caso o\nespermograma seja normal, realizar a histerossalpingografia.","B":"Tranquilizar o parceiro referindo que ele não necessita investigação no momento, visto que a\nmaioria das causas de infertilidade são femininas.","C":"Tranquilizar a paciente, informando da não necessidade, no momento, de investigação; visto ser\njovem e ainda não ter completado 2 anos de tentativas.","D":"Indicar a realização de laparoscopia para melhor investigação da infertilidade, diante da\nsuspeita\ndisgnóstica de endometriose."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252910","number":"252910","sourceNumber":"252910","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 34 anos de idade, nuligesta, casada, tenta engravidar há 1 ano e 6 meses sem\nsucesso. Nega comorbidades. Refere ciclos menstruais regulares, durando 5 dias com fluxo\nnormal, porém com dismenorreia leve. Também queixa de dispareunia de profundidade. Nega\noutros sintomas. Ao exame especular, conteúdo vaginal fisiológico e colo sem alterações. Ao toque\nvaginal, útero em anteroversoflexão, de volume normal, desconforto à mobilização do colo.\n\nAusência de dor à palpação de anexos. Em ultrassonografia transvaginal realizada pela paciente,\nfoi visualizada formação tecidual hipoecóica\nalongada e irregular, envolvendo o ligamento\nuterossacro esquerdo medindo 2,0cm x 1,2cm x 0,6cm. Ovário esquerdo apresentando formação\ncística e arredondada de contornos regulares e conteúdo espesso, homogêneo, em vidro fosco de\n1,5cm. Com base nesses achados, é correto o que se afirma em:","options":{"A":"O CA125 é um marcador tumoral específico para endometriose, tendo indicação de avaliação\nneste caso.","B":"Com tais achados ultrassonográficos, a paciente tem indicação de tratamento cirúrgico.","C":"A ultrassonografia transvaginal não é um exame eficaz na investigação inicial de infertilidade,\nsendo necessária a realização de ressonância pélvica\npara melhor elucidação dos achados.","D":"Os achados ultrassonográficos são compatíveis com endometriose e podem justificar a\ninfertilidade, porém não há indicação para tratamento cirúrgico no momento."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252911","number":"252911","sourceNumber":"252911","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 34 anos de idade, nuligesta, casada, tenta engravidar há 1 ano e 6 meses sem\nsucesso. Nega comorbidades. Refere ciclos menstruais regulares, durando 5 dias com fluxo\nnormal, porém com dismenorreia leve. Também queixa de dispareunia de profundidade. Nega\noutros sintomas. Ao exame especular, conteúdo vaginal fisiológico e colo sem alterações. Ao toque\nvaginal, útero em anteroversoflexão, de volume normal, desconforto à mobilização do colo.\n\nAusência de dor à palpação de anexos. Sobre endometriose em geral, é correto afirmar:","options":{"A":"Caracteriza-se pela presença de tecido endometrial fora da cavidade uterina e, portanto, está\nassociada ao fluxo menstrual intenso.","B":"Tem baixa taxa de recorrência após tratamento cirúrgico e hormonal.","C":"É uma causa relevante de obstrução tubária e de infertilidade.","D":"O exame especular costuma evidenciar nódulos em região retrouterina, principalmente se há\ndispareunia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-249436","number":"249436","sourceNumber":"249436","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No acompanhamento de um casal infértil, com exame de espermograma normal e\ndosagem hormonal adequada, compatível com ovulação, o próximo passo na propedêutica é:","options":{"A":"Teste pós-coito.","B":"Histerossalpingografia.","C":"Histeroscopia com biópsia de endométrio.","D":"Ultrassom seriado."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-201755","number":"201755","sourceNumber":"201755","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual das seguintes infecções está mais provavelmente associada com doença tubária?","options":{"A":"Trichomonas vaginalis.","B":"Bacteroides species.","C":"Chlamydia trachomatis.","D":"Proteus species.","E":"Treponema pallidum."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-201757","number":"201757","sourceNumber":"201757","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual das seguintes alternativas é a apresentação clínica mais comum da leiomiomatose\nuterina?","options":{"A":"Infertilidade.","B":"Menorragia.","C":"Obstrução ureteral.","D":"Dor pélvica.","E":"Aborto recorrente."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-219861","number":"219861","sourceNumber":"219861","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 38 anos, G3P3, relata aumento do fluxo menstrual e da duração da\nmenstruação há oito meses. Nega uso de contraceptivos há um ano porque seu marido é\nvasectomizado. Seu último preventivo foi realizado em 04/2018 com laudo de negativo para\nmalignidade. A MELHOR CONDUTA propedêutica inicial seria solicitar:","options":{"A":"Hemograma completo, prolactina, testosterona.","B":"Hemograma completo, teste de gravidez, ultrassonografia transvaginal.","C":"Hemograma completo, TSH, coagulograma.","D":"Hemograma completo, ultrassonografia transvaginal, biópsia endometrial."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-219872","number":"219872","sourceNumber":"219872","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 18 anos vem a Unidade Básica de Saúde, relatando ciclos menstruais\nirregulares desde a menarca e que há 6 meses não\nmenstrua. Informa que ainda não teve relação\nsexual. Durante a consulta estava acompanhada da mãe. Nega doenças prévias ou uso de\nmedicamentos. Ao exame clínico apresenta caracteres sexuais secundários normais e anatomia\npélvica normal. Assinale a hipótese diagnóstica menos provável:","options":{"A":"Gravidez.","B":"Hiperprolactinemia.","C":"Septo vaginal transverso.","D":"Síndrome do ovário policístico."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-212204","number":"212204","sourceNumber":"212204","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 65 anos, menopausada há 10 anos, procura o ambulatório de ginecologia\nqueixando-se de sangramento vaginal há um mês. É obesa, diabética e hipertensa não bem\ncontrolada. Ao exame colo uterino de aspecto normal, ausência de sangramentos, útero e anexos\nimpalpáveis ao toque. Qual a melhor conduta?","options":{"A":"Histerectomia subtotal.","B":"Histerectomia com anexectomia.","C":"Conização com pontos de Stumdorf.","D":"Histeroscopia com biópsia de endométrio.","E":"Histerossalpingografia com contraste iodado."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-215227","number":"215227","sourceNumber":"215227","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No acompanhamento do casal infértil, a pesquisa de fator ovulatório é realizada por:","options":{"A":"Dosagem hormonal na segunda fase do ciclo.","B":"Dosagem hormonal na primeira fase do ciclo.","C":"Histeroscopia.","D":"Histerossalpingografia."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-212236","number":"212236","sourceNumber":"212236","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 35 anos, nuligesta, tenta engravidar há 02 anos, sem sucesso. Mantém\nciclos menstruais regulares e não apresenta morbidades. O espermograma do companheiro é\nnormal. A ultrassonografia revela imagem intramiometrial de 03 cm, sugestiva de leiomioma. Na\nhisteroscopia diagnóstica, a lesão abaula a cavidade uterina. A conduta é","options":{"A":"aguardar gestação espontânea por mais 6 meses.","B":"embolização da artéria uterina.","C":"curetagem uterina.","D":"fertilização in vitro.","E":"miomectomia."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-212235","number":"212235","sourceNumber":"212235","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Endometriose é a presença de tecido endometrial (glândula e/ou estroma) fora da\ncavidade endometrial uterina, e que tem função\nsemelhante ao endométrio normalmente situado.\nSobre essa patologia, dadas as afirmativas, I. A endometriose pode ser sintomática ou\nassintomática, porém sempre está acompanhada de infertilidade. II. Os estudos sobre\nendometriose sugerem fortemente uma relação familiar de hereditariedade, mas ainda há\napresentam variáveis que podem afetar o resultado final, como fatores ambientais, idade, desejo\nreprodutivo, alimentação, entre outros. III. Os análogos de GnRH não estão incluídos no leque de\npossibilidades de tratamento para endometriose devido seus efeitos colaterais importantes\ndecorrentes do hipoestrogenismo. IV. A laparoscopia deve ser restringida para pacientes que\ntenham desejo de gestar, promovendo diagnóstico e tratamento de focos no mesmo procedimento,\nmelhorando as taxas de gravidez. verifica-se que está(ão) correta(s) apenas","options":{"A":"II.","B":"I e II.","C":"I e III.","D":"III e IV.","E":"I, III e IV."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-215248","number":"215248","sourceNumber":"215248","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Dos métodos citados abaixo, aquele que não serve para predição de período fértil é:","options":{"A":"Detecção de LH na urina.","B":"Curva de temperatura basal.","C":"Padrão de muco cervical.","D":"Dosagem de progesterona."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-215509","number":"215509","sourceNumber":"215509","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 60 anos, menopausada sem tratamento hormonal, com queixa de\nmetrorragia. Ao ultrassom endovaginal é\nobservado útero de 80 cm3, nódulo miomatoso de 1,5 cm\nde diâmetro, subseroso, e endométrio de 9 mm. A conduta mais adequada no momento é:","options":{"A":"Histerectomia.","B":"Histeroscopia.","C":"Repetir ultrassom em 12 meses.","D":"Miomectomia."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-215533","number":"215533","sourceNumber":"215533","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São passíveis de tratamento por histeroscopia, EXCETO:","options":{"A":"Pólipo endometrial.","B":"Hiperplasia endometrial.","C":"Mioma subseroso.","D":"Sinéquia uterina."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-215540","number":"215540","sourceNumber":"215540","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No exame de histerossalpingografia, uma prova de Cottè negativa significa:","options":{"A":"Boa dispersão do contraste através das trompas.","B":"Presença de mioma uterino distorcendo a cavidade endometrial.","C":"Obstrução tubária.","D":"Infertilidade de causa espermática."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-216223","number":"216223","sourceNumber":"216223","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal com queixa de infertilidade, sendo confirmada a ovulação e com o parceiro\napresentando espermograma normal, a próxima etapa da investigação é","options":{"A":"histerossalpingografia.","B":"histeroscopia.","C":"ultrassom seriado.","D":"tomografia pélvica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-180122","number":"180122","sourceNumber":"180122","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A conduta no sangramento pós-menopausa com ultrassonografia pélvica normal é:","options":{"A":"Administração de progestogênio.","B":"Administração de estrogênio.","C":"Administração de estrogênio e progestogênio","D":"Histerectomia total.","E":"Histeroscopia."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-181418","number":"181418","sourceNumber":"181418","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos, G0, casada há 3 anos, apresenta ciclos regulares e tenta obter\ngestação há mais de 2 anos. Dadas as\nafirmativas em relação ao casal infértil, I. A\nhisterossalpingografia é um exame importante na propedêutica do casal infértil e tem como objetivo\no estudo do canal cervical, cavidade uterina e trompas. II. A ressonância nuclear magnética pélvica\npara investigação de endometriose não faz parte da propedêutica básica do casal infértil. III. Caso\nrealizado videolaparoscopia e confirmada obstrução tubária bilateral, técnicas de reprodução\nassistida devem ser propostas, no caso em questão, fertilização in vitro. verifica-se que está(ão)\ncorreta(s)","options":{"A":"I, apenas.","B":"II, apenas.","C":"I e III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-183047","number":"183047","sourceNumber":"183047","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Assinale a alternativa CORRETA em relação aos Leiomiomas Uterinos:","options":{"A":"Em úteros com mais de 250 cm3 de volume, mesmo que assintomáticos, está indicada a\nhisterectomia.","B":"O potencial de transformação maligna dos miomas sugere que todas as pacientes sejam\nsubmetidas a exérese.","C":"O tratamento com a Gosserrelina só tem indicação quando há proposta de cirurgia subsequente,\nestando contraindicado como tratamento exclusivo.","D":"A principal finalidade da Gosserrelina é impedir a progressão do crescimento tumoral."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-183561","number":"183561","sourceNumber":"183561","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 57 anos, menopausa aos 49, procura ginecologista com queixa de\nsangramento vaginal há 1 mês. Não faz terapia\nde reposição hormonal. O ultrassom revela útero\nhomogêneo e endométrio de 4 mm de espessura. O mais provável diagnóstico, nesse caso, é","options":{"A":"hiperplasia endometrial típica.","B":"hiperplasia endometrial atípica.","C":"atrofia endometrial.","D":"discrasia sanguínea."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-181357","number":"181357","sourceNumber":"181357","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Dados as afirmativas sobre a endometriose, I. O padrão ouro para confirmação do\ndiagnóstico de endometriose é realizada pela videolaparoscopia e biópsia, com confirmação do\nhistopatológico.; II. Estima-se que 30-50% das mulheres inférteis sejam portadoras de\nendometriose.; III. Na presença de lesão de endometriose intestinal até muscular é mandatório\ntratamento cirúrgico com ressecção da parte do intestino acometida, para evitar futura obstrução\nintestinal.; IV. No tratamento da dismenorreia em pacientes com endometriose, podem-se utilizar\nanticoncepcionais combinados para controle da dor, mesmo com a presença do estrogênio na sua\nformulação.; V. O uso de progestágeno isolado é uma opção terapêutica para tratamento clínico da\nendometriose. verifica-se que estão corretas apenas","options":{"A":"I, II, IV e V.","B":"III, IV e V.","C":"II, III e V.","D":"I, II e IV.","E":"I e III."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-183600","number":"183600","sourceNumber":"183600","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O mioma parasita representa uma variedade do tipo","options":{"A":"submucoso.","B":"intramural.","C":"cervical.","D":"subseroso."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-158735","number":"158735","sourceNumber":"158735","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A histeroscopia permite o diagnóstico de:","options":{"A":"Mioma submucoso.","B":"Mioma subseroso.","C":"Obstrução tubária.","D":"Endometriose.","E":"Adenomiose."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-158738","number":"158738","sourceNumber":"158738","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"As hemorragias uterinas disfuncionais são mais frequentes em qual(is) fase(s) da vida?","options":{"A":"Menarca, apenas.","B":"Climatério, apenas.","C":"Senilidade, apenas.","D":"Senilidade e menarca.","E":"Pré-menopausa e puberdade."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-161328","number":"161328","sourceNumber":"161328","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação à Histerossalpingografia, assinale a INCORRETA.","options":{"A":"É utilizada para avaliar canal endocervical, cavidade endometrial e lúmen da tuba uterina.","B":"Deve ser realizado após a menstruação e antes da ovulação (aproximadamente do quinto ao\ndécimo dias do ciclo menstrual).","C":"O uso de anti-inflamatórios não esteroides está contraindicado no período de 12 horas que\nprecede o exame, pelo risco de perfuração uterina.","D":"Dentre as contraindicações estão a infecção pélvica aguda, sangramento uterino ativo, gravidez\nconfirmada ou suspeita e alergia ao Iodo."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-158746","number":"158746","sourceNumber":"158746","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A endometriose tem um importante fator predisponente na fertilidade da mulher. Dadas\nas afirmativas sobre a endometriose, I. A\nendometriose é uma doença ginecológica comum que é\nencontrada em 3 a 10% da população em geral e pode alcançar uma incidência de 30 a 40% na\ninfertilidade; II. A incidência da endometriose diminui com o avançar da idade; III. A endometriose\npode afetar a qualidade do oócito, diminuindo a taxa de fertilização, além de prejudicar a\nquantidade embrionária. Verifica-se que está(ão) correta(s):","options":{"A":"I, apenas.","B":"II, apenas.","C":"I e III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-158757","number":"158757","sourceNumber":"158757","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A idade da mulher é, sem dúvida alguma, o fator mais importante para o sucesso de\numa gravidez. Sobre a avaliação da reserva\novariana, é CORRETO afirmar:","options":{"A":"Quanto mais altos os níveis de LH, maior é a reserva ovariana.","B":"Quanto mais altos os níveis de FSH, maior é a reserva ovariana.","C":"Quanto mais baixos os níveis de inibina B, maior é a reserva ovariana.","D":"Quanto menor a contagem dos folículos antrais, maior é a reserva ovariana.","E":"Quanto mais baixos os níveis do hormônio antimulleriano-HAM, menor é a reserva ovariana."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-161371","number":"161371","sourceNumber":"161371","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação aos leiomiomas uterinos, aponte a INCORRETA.","options":{"A":"Após a menopausa, os leiomiomas geralmente regridem e o desenvolvimento de novos miomas\né raro.","B":"Cada mioma é derivado de um único miócito progenitor.","C":"O tratamento clínico com Agonistas do GnRH (gosserrelina) tem como inconveniente os\nfogachos, mas sem repercussão na taxa de reabsorção óssea.","D":"As mulheres assintomáticas, mesmo com leiomiomas volumosos, também podem ser tratadas\ncom conduta expectante."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-161260","number":"161260","sourceNumber":"161260","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre paciente com infertilidade de causa desconhecida, em consulta de retorno, você\nopta por solicitar biópsia endometrial para avaliar se há ovulação. O MELHOR dia do ciclo para\nessa biópsia seria o","options":{"A":"quarto.","B":"sétimo.","C":"décimo sexto.","D":"vigésimo sexto."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-158822","number":"158822","sourceNumber":"158822","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Na etiopatogenia da Dismenorreia Primária, há alteração na produção de:","options":{"A":"Prostaglandinas.","B":"Progestogênio.","C":"Testosterona.","D":"Estrogênios.","E":"Endorfinas."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-161168","number":"161168","sourceNumber":"161168","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A Histerossalpingografia é o exame que pode diagnosticar as seguintes patologias, com\nEXCEÇÃO de uma delas. Aponte-a.","options":{"A":"Endometrite.","B":"Pólipo endometrial.","C":"Sinéquias uterinas.","D":"Obstrução tubárea unilateral."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-158824","number":"158824","sourceNumber":"158824","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual o fator mais frequentemente associado à dispareunia progressiva?","options":{"A":"Peritonite.","B":"Endometriose.","C":"Varizes pélvicas.","D":"Miomatose uterina.","E":"Doença inflamatória pélvica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-140189","number":"140189","sourceNumber":"140189","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos apresenta menstruações irregulares e infertilidade. A biópsia do\nendométrio mostra hiperplasia complexa com atipia citológica mínima. O tratamento mais adequado\npara esta paciente é:","options":{"A":"observação","B":"indução da ovulação com GnRH","C":"tratamento cíclico com estrogênio","D":"tratamento contínuo com progestogênio","E":"histerectomia"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-131390","number":"131390","sourceNumber":"131390","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Constituem causa de dor pélvica crônica:","options":{"A":"Calculose urinária e diabetes mellito.","B":"Endometriose e sequela de doença inflamatória pélvica","C":"Gonococcia e vaginose bacteriana.","D":"Parasitose intestinal e hiperplasia endometrial.","E":"Infecção urinária baixa e bartolinite."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-131405","number":"131405","sourceNumber":"131405","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre a miomatose uterina, assinale a assertiva correta.","options":{"A":"A degeneração cística é mais comum no puerpério imediato.","B":"O exame de imagem preferencial para útero miomatoso com mais de 20 cm de eixo longitudinal\né ultrassonografia transvaginal.","C":"Abortamento de repetição, sangramento uterino anormal e oligoamenorréia são complicações da\ndoença.","D":"A torção de mioma pediculado é causa comum de abdômen agudo hemorrágico.","E":"A degeneração sarcomatosa é rara (0,1% a 0,5%)."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134085","number":"134085","sourceNumber":"134085","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 22 anos, nuligesta, tentando gravidez há1 ano e meio, sem sucesso, vem\nna primeira consulta para orientação e\ninvestigação de esterilidade, nega doenças e queixas.\n\nRefere ciclos regulares, relação sexual frequente, sem outras queixas. Qual é a MELHOR conduta?","options":{"A":"Investigação do casal por meio dos exames de infertilidade conjugal.","B":"Investigar apenas a parceira, pois é a principal causa de infertilidade.","C":"Investigar apenas o parceiro.","D":"Aguardar mais 12 meses e depois investigar"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134281","number":"134281","sourceNumber":"134281","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 25 anos, nuligesta, vida sexual ativa há 5 anos, usa anticoncepcional há 8\nanos com melhora de quadro de dismenorreia\ne menorragia, desejando parar anticoncepcional para\nengravidar. Fez exame de Papanicolau que deu normal e fez US endovaginal apresentando\nimagem nodular, hipoecoica em cavidade uterina, medindo 2,0 cm. Diante desse caso clínico, qual\né a melhor conduta?","options":{"A":"Videolaparoscopia.","B":"Ressonância nuclear magnética.","C":"Curetagem uterina.","D":"Histeroscopia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134828","number":"134828","sourceNumber":"134828","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, G2P0A2C0, ambos abortos espontâneos no 1º trimestre de\ngestação, sem curetagem, vem para consulta de rotina, nega morbidades e medicações, refere\nciclos regulares de 28 dias, porém com fluxo aumentado e coágulos, com duração de 10 dias.\nDiante de tal caso, podemos suspeitar de qual patologia?","options":{"A":"Pólipo endometrial.","B":"Mioma subseroso.","C":"Endometriose pélvica.","D":"Cisto de ovário roto."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134350","number":"134350","sourceNumber":"134350","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 20 anos começou a menstruar aos 14 anos, relação sexual desde os 17\nanos, com preservativo, passou por vários\nmédicos devido às dores intensas no período menstrual\ne pós-menstruação, refere dispareunia profundidade, sendo medicada com AINH apenas, com\nmelhora leve. Qual é o diagnóstico MAIS provável?","options":{"A":"Dismenorreia primária.","B":"Endometriose.","C":"Cisto de Ovário Roto.","D":"Apendicite."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134830","number":"134830","sourceNumber":"134830","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 60 anos, Hipertensa e Diabética em tratamento, nega terapia de reposição\nhormonal, nega outras patologias ou medicações, vem ao consultório com queixa de sangramento\nvaginal há 5 dias, vermelho vivo, tipo menstruação, cólicas e dor em baixo ventre. Diante de tal\ncaso, qual exame seria o padrão ouro da literatura para a investigação diagnóstica?","options":{"A":"Curetagem uterina de prova.","B":"Histeroscopia.","C":"Videolaparoscopia.","D":"Ultrassonografia endovaginal."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134124","number":"134124","sourceNumber":"134124","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 25 anos, desejando engravidar, nuligesta, casada há 3 anos, refere nos\núltimos 6 meses que o fluxo menstrual está aumentado na quantidade e duração, com cólicas\nintensas na menstruação. Fez exame de ultrassonografia endovaginal que mostra nodulação\nregular, hipoecóica, de 2 cm em fundo de cavidade uterina. Qual é a MELHOR conduta nesse\ncaso?","options":{"A":"Curetagem uterina.","B":"Videolaparoscopia.","C":"Histeroscopia.","D":"Histerectomia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-110572","number":"110572","sourceNumber":"110572","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São causas de dor pélvica crônica, EXCETO:","options":{"A":"Miomas.","B":"Varizes pélvicas.","C":"Hérnia de disco.","D":"Endometriose.","E":"Cisto hemorrágico."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-110586","number":"110586","sourceNumber":"110586","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São opções de tratamento para a hemorragia uterina disfuncional, exceto:","options":{"A":"Estrogênios conjugados.","B":"Anticoncepcionais orais combinados.","C":"Cabergolina.","D":"Inibidores de prostaglandinas.","E":"Acetato de medroxiprogesterona."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-110537","number":"110537","sourceNumber":"110537","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São opções de tratamento clínico da endometriose, exceto:","options":{"A":"Estradiol.","B":"Progestogênios.","C":"Análogos de GNRH.","D":"Anticoncepcionais orais combinados.","E":"Anti-inflamatório não hormonais."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-109786","number":"109786","sourceNumber":"109786","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, nuligesta, desejosa de engravidar, casada com parceiro\nvasectomizado há 5 anos. Nesse caso, qual é conduta ADEQUADA?","options":{"A":"Encaminhar caso para fertilização in vitru.","B":"Encaminhar caso para inseminação intrauterina.","C":"Encaminhar caso para barriga de aluguel.","D":"Encaminhar caso para indução de ovulação e coito programado."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-109970","number":"109970","sourceNumber":"109970","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Durante o exame de Histerossalpingografia, a imagem radiológica da Trompa em forma\nde ?rosário? é característica de","options":{"A":"Infecção Gonocóccica.","B":"Sífilis.","C":"Herpes.","D":"Tuberculose."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-86852","number":"86852","sourceNumber":"86852","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A indicação mais comum para tratamento de leiomioma uterino em uma mulher de 42\nanos é:","options":{"A":"Interferência com a função reprodutiva;","B":"Rápido aumento do volume uterino;","C":"Dor;","D":"Sangramento excessivo;","E":"Invasão de outro órgão ."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-108592","number":"108592","sourceNumber":"108592","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São sinais ultrassonográficos de adenomiose:","options":{"A":"Espessamento difuso da parede miometrial.","B":"Redução da ecogenicidade miometrial.","C":"Espessamento mais frequente na parede anterior.","D":"Cistos miometriais pequenos na periferia do útero.","E":"Todas as anteriores."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-49621","number":"49621","sourceNumber":"49621","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São opções para o tratamento da dismenorreia, EXCETO:","options":{"A":"Anti-inflamatórios não esteroidais (AINES).","B":"Contraceptivos orais combinados.","C":"Sistema intrauterino liberador de levonorgestrel.","D":"DIU T. Cobre.","E":"Progestínicos."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-49598","number":"49598","sourceNumber":"49598","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A causa mais provável de sangramento genital anormal em uma mulher de 22 anos é:","options":{"A":"Câncer uterino.","B":"Prenhez ectópica.","C":"Anovulação.","D":"Doenças hematológicas.","E":"Ameaça de aborto."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-327261","number":"327261","sourceNumber":"327261","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 18 anos, nuligesta, com queixa de dismenorreia crônica, foi diagnosticada\ncom endometriose. Qual melhor conduta para esse caso?","options":{"A":"Anti-inflamatórios não hormonais","B":"Cirurgia laparoscópica","C":"DIU de cobre","D":"Implante de etonogestrel"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-327269","number":"327269","sourceNumber":"327269","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 35 anos, tabagista, refere sangramento uterino anormal há 12 meses. Refere\naumento de fluxo menstrual. Exame ginecológico: útero discretamente aumentado. Ultrassonografia\ntransvaginal: nódulos compatíveis com miomas intramurais medindo 3,0 cm e 2,0 cm. Qual a\nconduta mais adequada?","options":{"A":"Miomectomia histeroscópica","B":"Análogo Gnrh","C":"Sistema intrauterino de levonogestrel","D":"Pilula anticoncepcional combinada"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-327270","number":"327270","sourceNumber":"327270","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação a tratamentos de reprodução assistida na população LGBTQIA+ conforme a\nresolução do CFM 2.294 de 27 de maio de 2021, é CORRETO afirmar:","options":{"A":"Os procedimentos de reprodução assistida são permitidas para pessoas transgênero masculino\ne feminino, após a aprovação do CFM.","B":"É permitida ao casal homoafetivo masculino, a fecundação de oócitos por um mix de\nespermatozoides de ambos, com transferência de embriões de origem aleatória.","C":"A cessão temporária de útero para casal homoafetivo masculino demanda autorização judicial\npara que seja realizado.","D":"A gestação compartilhada, em que se utiliza oocitos de uma parceira e útero da outra, é\npermitido para casais homoafetivo feminino."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298232","number":"298232","sourceNumber":"298232","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 24 anos, realizou ultrassonografia de rotina que evidenciou mioma subseroso\nde 18 mm, FIGO 6. Qual a conduta adequada?","options":{"A":"Retirada por histeroscopia","B":"Expectante","C":"Retirada por laparotomia","D":"Retirada por laparoscopia"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-286750","number":"286750","sourceNumber":"286750","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 16 anos foi ao ginecologista com queixa de dor pélvica crônica, alterações\nintestinais cíclicas (disquezia) e alterações urinárias cíclicas (disúria no período menstrual). O\nexame físico não evidenciou alterações significativas. Qual a conduta adequada?","options":{"A":"Solicitar ultrassonografia com preparo intestinal e, se o resultado for normal, orientar a\npaciente\na realizar seguimento anual.","B":"Solicitar Ressonância Magnética da pelve e, se o resultado for normal, orientar a paciente a\nrealizar seguimento anual.","C":"Solicitar Ressonância Magnética da pelve e, se o resultado for normal, indicar tratamento\ncirúrgico por vídeolaparoscopia.","D":"Solicitar Ultrassonografia com preparo intestinal e, mesmo que o resultado seja normal, iniciar\ntratamento Clínico"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252261","number":"252261","sourceNumber":"252261","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São causas de Sangramento anormal:","options":{"A":"Uso de ácido tranexamico","B":"Endometrite","C":"Ablação endometrial","D":"Uso de Carbapenemicos"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252298","number":"252298","sourceNumber":"252298","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Infertilidade é um problema de saúde pública, muitas vezes negligenciado. Afetando\nintimamente a vida do casal, podendo ocorrer desde distúrbios psíquicos até discriminação social.\nPor isso deve ser acompanhada apropriadamente na APS. Dessa forma, os diagnósticos das\ncausas principais são primordiais. Em relação às causas marque a CORRETA:","options":{"A":"Nos países desenvolvidos as principais causas são relacionadas a DST.","B":"Nos países em desenvolvimento as principais causas são distúrbios ovulatórios.","C":"Hábitos como estilismo e tabagismo são de risco para infertilidade.","D":"Endometriose, apesar de grave, não compreende causa de infertilidade."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-208358","number":"208358","sourceNumber":"208358","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 54 anos, menopausada há 5 anos, sem uso de reposição hormonal, refere\nsangramento vaginal. Trouxe na consulta uma ultrassonografia com diagnóstico de pólipo\nendometrial. Qual a conduta a ser adotada:","options":{"A":"Histerectomia","B":"Progestágeno contínuo","C":"Histeroscopia com biópsia","D":"Estrogenioterapia contínua"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-208402","number":"208402","sourceNumber":"208402","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 32 anos, foi ao consultório pois está tentando engravidar há 2 anos.\nAssintomática. No dia da consulta estava no\n24º dia do ciclo. O exame ginecológico estava normal.\nNo mesmo dia, o ginecologista realizou uma biópsia endometrial cujo diagnóstico foi: endométrio\nproliferativo. A hipótese diagnóstica é:","options":{"A":"Ciclo anovulatório","B":"Hiperplasia endometrial","C":"Infertilidade de origem masculina","D":"Sinéquia uterina"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-176078","number":"176078","sourceNumber":"176078","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Para o diagnóstico de endometriose, o padrão ouro é:","options":{"A":"Ressonância magnética.","B":"Laparoscopia com biópsia.","C":"Tomografia computadorizada.","D":"Ultrassonografia transvaginal com preparo intestinal."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-176027","number":"176027","sourceNumber":"176027","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação a dismenorreia, assinale a alternativa CORRETA:","options":{"A":"A dismenorreia primária pode estar associada, em boa parte dos casos, à patologia como\nendometriose ou adenomiose.","B":"Os Inibidores da Recaptação de Serotonina (ISRS) representam terapia de primeira linha no\ntratamento da dismenorreia primária.","C":"A dismenorreia primária é causada por isquemia miometrial em razão das contrações uterinas\nfrequentes e prolongadas.","D":"O diagnóstico de dismenorreia primária requer dosagem laboratorial do CA-125 sérico normal."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-129743","number":"129743","sourceNumber":"129743","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 28 anos procurou atendimento médico com queixa de dismenorreia, dor\npélvica crônica, dispareunia, hematoquesia no período menstrual, disúria e dor que irradia pela\ncoxa direita. Refere menarca aos 11 anos, Gesta 0 Para 0. Nega uso de anticoncepcionais.\n\nBaseado nas informações acima, assinale a afirmativa CORRETA.","options":{"A":"O diagnóstico é de doença inflamatória pélvica e tratamento com metronidazol deve ser iniciado\nimediatamente.","B":"O diagnóstico é de câncer de ovário e devemos realizar a cirurgia precocemente porque câncer\nem pessoas jovens costuma ser altamente\nagressivo.","C":"O diagnóstico provável é de endometriose e o padrão ouro para o diagnóstico é a cirurgia\nlaparoscópica.","D":"O diagnóstico é de síndrome do intestino irritável e retocolite ulcerativa e a paciente deve ser\nencaminhada ao gastroenterologista."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-129765","number":"129765","sourceNumber":"129765","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O sangramento uterino normal é aquele onde ocorrem menstruações cíclicas em um\nintervalo de 21 a 35 dias, que duram até 7 dias com perda de sangue aproximadamente de 20 a 80\nml. Assinale a afirmativa CORRETA:","options":{"A":"Hipermenorreia é o sangramento de mais de 80 ml em intervalos regulares.","B":"Menometrorragia é o sangramento irregular intenso.","C":"Hipermenorragia é a associação de hipermenorreia e polimenorreia.","D":"Polimenorreia é o sangramento por mais de 7 dias."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-107883","number":"107883","sourceNumber":"107883","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"Menorragia são episódios regulares de sangramento excessivo em quantidade (maior que 80ml)\ne duração de fluxo (mais que 5 dias).","B":"Oligomenorreia são sangramentos em períodos regulares e quantidade diminuída.","C":"Polimenorreia é o sangramento que ocorre entre ciclos menstruais normais.","D":"Metrorragia são episódios frequentes, mas regulares que ocorrem em intervalos de 21 dias ou\nmenos."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-107907","number":"107907","sourceNumber":"107907","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Assinale a afirmativa CORRETA:","options":{"A":"Deve-se suspeitar de endometriose em mulheres com subfertilidade, dismenorreia, dispareunia\nou dor pélvica crônica. Entretanto, a\nendometriose pode ser assintomática.","B":"O exame de sangue que é patognomonico e fecha o diagnóstico de endometriose é o Ca 125.","C":"A endometriose pode ser tratada com anticoncepção cíclica.","D":"A progesterona estimula o crescimento da endometriose então devemos dar estrogenioterapia\npara as pacientes para suprimir a síntese de\nprogesterona."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-107898","number":"107898","sourceNumber":"107898","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Cristiana 48 anos, GIV P II Abl, obesa, assintomática foi realizar ultrassonografia de\nrotina que evidenciou volume uterino de 183cm3 e dois nódulos sólidos hipoecóicos de contornos\nregulares e limites bem definidos em parede anterior, intramurais compatíveis com leiomiomas\nmedindo 4,5 cm de diâmetro. A conduta mais adequada é:","options":{"A":"Miomectomia.","B":"tratar com análogos do GnRh.","C":"Histerectomia.","D":"Orientação e controle ultrassonográfico."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-103865","number":"103865","sourceNumber":"103865","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre o sangramento uterino anormal, marque a alternativa CORRETA:","options":{"A":"A histeroscopia é um exame importante no diagnóstico de alterações da cavidade uterina, uma\nvez que permite a visualização direta e, se\nnecessário, biópsia da área mais representativa a ser\nestudada.","B":"Na perimenopausa, o sangramento uterino anormal é um problema pouco frequente visto que o\neixo hipotálamo-hipófise-ovário funciona adequadamente nesse período da vida da mulher.","C":"A camada basal do endométrio sofre alterações durante o ciclo menstrual e desprende-se\ndurante a menstruação.","D":"O ultrassom transvaginal é um exame que tem pouco uso atualmente em virtude do advento de\nexames mais precisos."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-103810","number":"103810","sourceNumber":"103810","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre a infertilidade, marque a alternativa CORRETA:","options":{"A":"A inspeção direta é a avaliação mais precisa da patologia pélvica, e a laparoscopia é o\npadrão-ouro.","B":"O citrato de clomifeno, tratamento inicial para mulheres anovulatórias, é usado por via\nendovenosa a partir do meio do ciclo.","C":"Na síndrome da hiperestimulação ovariana a dor abdominal é proeminente e causada por\nacúmulo de fluido peritonial, bem como pelo aumento do volume uterino.","D":"A análise do sêmen é essencial para estudar o fator masculino. Para realizar esse exame o\nhomem deve ficar em abstinência por quinze dias."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-103818","number":"103818","sourceNumber":"103818","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O miomas são tumores benignos muito frequentes na população feminina. Sobre esses\ntumores, marque a alternativa INCORRETA:","options":{"A":"São neoplasias benignas derivadas do músculo liso, que com frequência, originam-se do\nmiométrio.","B":"Os miomas são tumores sensíveis aos esteroides sexuais como o estrogênio e a progesterona.","C":"A maioria das mulheres com miomas é sintomática, sendo o sangramento o sintoma mais\ncomum.","D":"A obesidade confere risco aumentado para a ocorrência de miomas devido ao aumento da\nconversão de androgênios em estrogênios."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-103828","number":"103828","sourceNumber":"103828","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A endometriose foi primeiro descrita no século XIX por Von Rokitansky, sendo uma\npatologia ginecológica muito encontrada na prática clínica. Assinale a alternativa CORRETA:","options":{"A":"Não há evidências de um padrão hereditário familiar para a endometriose.","B":"Uma das teorias a respeito da endometriose propõe a menstruação retrógrada através das\ntrompas de Fálopio para a cavidade peritoneal.","C":"A endometriose pode se desenvolver apenas em alguns sítios da pelve, não podendo ocorrer\nem outras superfícies peritoniais\nextrapélvicas.","D":"A dispareunia associada à endometriose está mais associada ao envolvimento ovariano e\nmenos associada ao acometimento do septo retovaginal e do ligamento uterossacro."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-87444","number":"87444","sourceNumber":"87444","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Aurora, 28 anos, compareceu ao ambulatório com queixa de dor pélvica, dispareunia,\ndor a evacuar durante o período menstrual,\ncom início ha 18 meses. Ao exame, apresenta útero\ncom pouca mobilidade, dor a palpação e nodulação em região de fundo de saco posterior,\nretrocervical. Assinale a alternativa que corresponde a principal hipótese diagnóstica e o exame\ncomplementar que deve ser solicitado:","options":{"A":"Abscesso Tubo e Ovariano e PCR.","B":"Diverticulite e tomografia.","C":"Cisto ovariano torcido e ultrassonografia.","D":"Endometriose e CA-125.","E":"CA de colo e Histerossalpingografia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-81947","number":"81947","sourceNumber":"81947","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 35 anos, soropositiva, em uso de antirretrovirais, apresentou, na\ncolpocitologia, células escamosas com atipias\nde significado indeterminado, não se podendo excluir\nlesão intraepitelial de alto grau (ASCH). Qual a conduta mais adequada?","options":{"A":"Conização","B":"Captura híbrida","C":"Colposcopia","D":"Colpocitologia em 6 meses","E":"Colpocitologia em 3 meses"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-81999","number":"81999","sourceNumber":"81999","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual o melhor método diagnóstico para lesões peritoneais de endometriose?","options":{"A":"Ca 125","B":"Laparotomia","C":"Ultrassonografia transvaginal","D":"RNM de pelve","E":"Videolaparoscopia"},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-81037","number":"81037","sourceNumber":"81037","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 35 anos procurou o ambulatório de infertilidade da Universidade Federal do\nAmazonas. Refere nunca ter gestado e estar tentando engravidar há 3 anos. Foi solicitada a\npropedêutica do ambulatório e a única alteração foi a presença de um nódulo sólido miometrial\nintramural com componente submucoso. Foi solicitada uma histeroscopia diagnóstica, que\nobservou a lesão abaulada na cavidade endometrial. Qual a melhor conduta a ser tomada:","options":{"A":"Aguardar a gestação espontânea por mais 6 meses","B":"Miomotectomia","C":"Curetagem uterina","D":"Histerossalpingografia com biopsia para avaliar malignidade do nódulo","E":"Embolização seletiva da artéria ilíaca externa"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-60815","number":"60815","sourceNumber":"60815","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente menopausada há 6 anos queixa de sangramento vaginal discreto, porém nos\núltimos dois meses frequentes. Apresenta episódios frequentes de fogachos e labilidade emocional.\nTem antecedentes de miomatose uterina e cauterização de colo uterino, teve três cesarianas e\nrealizou laqueadura tubária. Tem um IMC de 25 e usa antihipertensivo. No exame ginecológico,\ndetectou-se a presença de útero aumentado, irregular, com mobilidade normal e ovários não\npalpáveis. Qual a conduta mais indicada?","options":{"A":"Realizar biópsia endometrial","B":"Realizar conização cervical","C":"Histerectomia total abdominal","D":"Inserir DIU contendo progesterona","E":"Prescrever combinação hormonal de estrogênio e progesterona"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-60820","number":"60820","sourceNumber":"60820","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 18 anos apresenta dismenorreia progressiva acompanhada de náuseas e\ncefaleia desde a menacme, que a impossibilitam de realizar suas atividades normais. Não tem vida\nsexual ativa e o exame ginecológico é normal. Com a suspeita diagnóstica de dismenorreia\nprimária, qual a melhor opção para o tratamento?","options":{"A":"Análogo do GnRH","B":"Drogas ocitócicas","C":"Inibidores da prolactina","D":"Inibidores de prostaglandinas","E":"Antiespasmódicos de ação central"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-60823","number":"60823","sourceNumber":"60823","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São contraindicações das gonadotropinas para o tratamento da infertilidade, EXCETO:","options":{"A":"disfunção tireoidiana e suprarrenal não controlada","B":"insuficiência ovariana primária com níveis elevados de hormônio folículo estimulante","C":"hemorragia uterina anormal não diagnosticada","D":"aumento ovariano causado pela síndrome dos ovários policísticos","E":"tumor de ovário dependente de hormônio sexual"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-61514","number":"61514","sourceNumber":"61514","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"Menometrorragia é o sangramento menstrual excessivo, prolongado em intervalos regulares.","B":"Oligomenorreia é o ciclo menstrual irregular com períodos de intervalo maiores que 15 dias.","C":"Polimenorreia são ciclos frequentes, regulares, com intervalos maiores que 21 dias.","D":"Metrorragia é o sangramento menstrual irregular.","E":"Hipomenorreia são ciclos irregulares com sangramento reduzido."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-61533","number":"61533","sourceNumber":"61533","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 22 anos procurou o ginecologista com história de sangramento vaginal\nintermenstrual irregular. Nega cirurgias ou quaisquer patologias prévias. Ao exame físico e\nespecular não foi observado nenhuma anormalidade. Qual a melhor conduta que o ginecologista\ndeve adotar?","options":{"A":"Solicitar ultrassonografia.","B":"Prescrever um creme vaginal.","C":"Prescrever anticoncepcional injetável.","D":"Realizar curetagem uterina para cessar o sangramento.","E":"Realizar AMIU (Aspiração Manual Intrauterina) ambulatorialmente para retirar possíveis coágulos\nque estejam na cavidade endometrial."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-60836","number":"60836","sourceNumber":"60836","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"NÃO é substância utilizada no manejo da endometriose:","options":{"A":"Progestogênios de depósito.","B":"Antagonistas do GnRH.","C":"Danazol.","D":"Gestrinona.","E":"Etinilestradiol."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-46643","number":"46643","sourceNumber":"46643","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Escolar é trazida ao Ambulatório por sua mãe. É portadora de retardo mental e\napresenta sangramento vaginal de pequena monta,\nsecreção fétida e amarelada abundante. No\nexame da genitália, não apresenta qualquer anormalidade na coloração da mucosa; o hímen está\níntegro. Provável diagnóstico:","options":{"A":"Vulvovaginite por cândida.","B":"Corpo estranho vaginal.","C":"Tricomoníase vaginal.","D":"Mucosa precoce.","E":"Abuso sexual."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-34156","number":"34156","sourceNumber":"34156","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Dos termos abaixo, qual caracteriza a clinica de intervalo menstrual regular, duração do\nfluxo prolongado e quantidade excessiva?","options":{"A":"Menorragia","B":"Hipermenorreia","C":"Metrorragia","D":"Hiperpolimenorreia","E":"Menometrorragia"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-26502","number":"26502","sourceNumber":"26502","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A vascularização deficiente na região central do nódulo miomatoso proporciona o\naparecimento de alterações secundárias conhecidas como degenerações, sendo a mais comum na\nsenectude:","options":{"A":"carnosa.","B":"cística.","C":"calcificação.","D":"hialina.","E":"gordurosa."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-26509","number":"26509","sourceNumber":"26509","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Dentre as substâncias a seguir, qual não deve ser indicada para o tratamento dos\nsintomas relacionados à endometriose?","options":{"A":"Estrógenos isolados","B":"Progestágenos isolados","C":"Inibidores da aromatosase","D":"Análogos hiperativos da GnRh","E":"Estrógenos e progestágenos combinados"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-26485","number":"26485","sourceNumber":"26485","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Assinale a alternativa correta:","options":{"A":"A síndrome do ovário policístico é a segunda causa mais comum de anovulação e infertilidade\nfeminina.","B":"O volume de espermatozoide considerado normal é acima de 1,0ml, com mais de 20% de\nformas normais.","C":"A melhor técnica para o diagnóstico da doença tubária e peritoneal é a hisberossalpingografia.","D":"O baixo índice de massa corporal também pode causar anovulação e infertilidade em mulheres\npossivelmente por perturbação hipolsária.","E":"Os distúrbios da ovulação são responsáveis por 30 a 40% dos casos de infertilidade feminina."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13243","number":"13243","sourceNumber":"13243","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A Endometriose está associada a todos os processos/situações abaixo. Das citadas\nqual a que tem pouca ou nenhuma correlação com a endometriose?","options":{"A":"Dismenorreia.","B":"Abortos recorrentes.","C":"Dispaurenia.","D":"Infertilidade.","E":"Dor pélvica crônica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-354418","number":"354418","sourceNumber":"354418","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Adolescente, 15 anos de idade, vai em ginecologista referindo irregularidade menstrual.\nMenarca: 14 anos de idade. Nunca teve relações sexuais. Refere fluxo menstrual normal e nega\ndismenorreia. Trouxe anotações com os ciclos dos últimos meses e seus intervalos entre as\nmenstruações: Considerando que essa é a primeira consulta ginecológica da paciente, o médico\ndeve, também, orientar a paciente quanto à fisiologia do ciclo reprodutivo feminino. Indique a\nmelhor conduta preconizada para o caso:","options":{"A":"Tranquilizar a paciente, informando que existe ainda imaturidade do eixo\nhipotálamo-hipófise-ovariano","B":"Confirmar irregularidade menstrual e solicitar ultrassom pélvico para afastar a presença de\nlesões ovarianas.","C":"Confirmar irregularidade menstrual e prescrever contraceptivo hormonal combinado para\ncontrole dos intervalos menstruais.","D":"Confirmar irregularidade menstrual e solicitar FSH, LH, Prolactina, progesterona e TSH."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":["question_bank/media/medcurso/medcurso-gineco-gin-2/354418.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-284604","number":"284604","sourceNumber":"284604","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher branca, 60 anos de idade, desde os 45 anos de idade entrou na menopausa. A\nprimeira menstruação ocorreu aos 9 anos. Teve 3 gestações e todas evoluíram para parto normal.\nRefere hipertensão bem controlada com medicação. IMC: 30Kg/m². Vem ao pronto atendimento\npois apresentou sangramento vaginal, de pouca quantidade, há 3 dias, com melhora espontânea\napós 2 dias do início do evento. Hoje apresenta sangramento tipo borra de café. Nega cólica ou\noutros sintomas associados. Nega uso de medicações no momento ou histórico de reposição\nhormonal. Ao exame físico: corada e hidratada. Abdome flácido, indolor à palpação e sem\nvisceromegalias. Exame especular: presença de sangramento não ativo de pouca quantidade\ncoletado em fundo vaginal. TV: ausência de dor à mobilização do colo uterino. Ultrassonografia\nTransvaginal realizada evidencia útero em retroversoflexão com dimensões, morfologia e contornos\npreservados. Medida total: 40cm³, miométrio com ecotextura homogênea, eco endometrial centrado\nhomogêneo de 6mm. Ovários não visualizados. Ausência de líquido livre na cavidade. Identifique a\ncausa mais frequente de sangramento pós menopausa:","options":{"A":"Pólipo endometrial.","B":"Mioma submucoso.","C":"Câncer de endométrio.","D":"Atrofia endometrial."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-62845","number":"62845","sourceNumber":"62845","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, multípara, sem queixas, comparece ao consultório ginecológico com achado\necográfico de mioma uterino, de localização subserosa, em fundo uterino, medindo 1 cm. O exame\nginecológico confirma o útero intrapélvico de pequeno volume. O procedimento é:","options":{"A":"Indicar histerectomia por via abdominal.","B":"Indicar histerectomia por via vaginal.","C":"Manter conduta expectante.","D":"Indicar miomectomia por via laparotômica.","E":"Indicar miomectomia por via laparoscópica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-49287","number":"49287","sourceNumber":"49287","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 29 anos de idade, nuligesta com desejo de gestar, apresenta quadro de\nsangramento uterino anormal secundário à\nmioma uterino submucoso, nível 0 na classificação pela\nSociedade Europeia de Ginecologia Endoscópica, ESGE. A melhor conduta para essa paciente é:","options":{"A":"indicar anticoncepcional combinado oral contínuo.","B":"indicar anticoncepcional apenas com progesterona.","C":"realizar miomectomia histeroscópica.","D":"realizar histerectomia.","E":"realizar miomectomia laparoscópica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-34961","number":"34961","sourceNumber":"34961","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 55 anos de idade, menopausada e assintomática, vai ao ginecologista com\nresultado de ultrassom demonstrando volume uterino de 50 cm³, mioma uterino intramural em\nparede anterior medindo 2,5 cm x 3,5 cm, endométrio medindo 3 mm. Ovários não visibilizados. A\nmelhor conduta é:","options":{"A":"realizar histerectomia abdominal.","B":"expectante, não indicando cirurgia no momento.","C":"indicar terapia hormonal da menopausa.","D":"realizar histerectomia vaginal.","E":"realizar histerectomia com anexectomia bilateral."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-27474","number":"27474","sourceNumber":"27474","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 27 anos de idade, com história de DIP prévia sem tratamento, vai ao\nginecologista para investigação de\ninfertilidade, com duração de 2 anos. Refere ciclos menstruais\nregulares, a cada 28 dias. O parceiro tem 40 anos, apresenta 2 espermogramas normais, com\nintervalo de 30 dias. Em relação à propedêutica mínima da infertilidade, o exame mais adequado\npara avaliação do fator tuboperitoneal é:","options":{"A":"videolaparoscopia com cromotubagem.","B":"USG transvaginal.","C":"histeroscopia.","D":"ressonância magnética da pelve.","E":"histerossalpingografia."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13356","number":"13356","sourceNumber":"13356","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 35 anos de idade, negra, nuligesta, obesa, diabética e tabagista, vem ao\nconsultório médico para avaliação de rotina.\nNega fluxo patológico genital. Refere fluxo menstrual\nde 28 a 30 dias/3 a 5d/++. Ao exame físico, TA: 120 x 70 mmHg, PR: rítmico e cheio, com 65 bpm.\nAbdome plano flácido e não doloroso à palpação. Trouxe preventivo normal. USG: útero\naumentado de volume à custa de 2 nódulos miomatosos, um subseroso e outro intramural, medindo\no maior 2,0 cm x 1,8 cm. Volume uterino de 126 cm³. Ovários de volume e ecotextura habituais.\n\nDeseja engravidar futuramente. Em relação aos dados epidemiológicos, dos apresentados pela\npaciente não se correlaciona com aumento na incidência do mioma:","options":{"A":"raça","B":"nuliparidade","C":"obesidade","D":"diabetes","E":"tabagismo"},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13359","number":"13359","sourceNumber":"13359","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 35 anos de idade, negra, nuligesta, obesa, diabética e tabagista, vem ao\nconsultório médico para avaliação de rotina.\nNega fluxo patológico genital. Refere fluxo menstrual\nde 28 a 30 dias/3 a 5d/++. Ao exame físico, TA: 120 X 70 mmHg, PR: rítmico e cheio, com 65 bpm.\nAbdome plano flácido e não doloroso à palpação. Trouxe preventivo normal. USG: útero\naumentado de volume à custa de 2 nódulos miomatosos, um subseroso e outro intramural, medindo\no maior 2,0 cm x 1,8 cm. Volume uterino de 126 cm³. Ovários de volume e ecotextura habituais.\n\nDeseja engravidar futuramente. A melhor abordagem dos miomas no caso em questão é:","options":{"A":"histerectomia total abdominal","B":"miomectomia laparoscópica","C":"conduta expectante com acompanhamento ultrassonográfico","D":"miomectomia laparotômica","E":"embolização uterina"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13361","number":"13361","sourceNumber":"13361","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 35 anos de idade, negra, nuligesta, obesa, diabética e tabagista, vem ao\nconsultório médico para avaliação de rotina.\nNega fluxo patológico genital. Refere fluxo menstrual\nde 28 a 30 dias/3 a 5d/++. Ao exame físico, TA: 120 X 70 mmHg, PR: rítmico e cheio, com 65 bpm.\nAbdome plano flácido e não doloroso à palpação. Trouxe preventivo normal. USG: útero\naumentado de volume à custa de 2 nódulos miomatosos, um subseroso e outro intramural, medindo\no maior 2,0 cm x 1,8 cm. Volume uterino de 126 cm³. Ovários de volume e ecotextura habituais.\n\nDeseja engravidar futuramente. Na embolização uterina para tratamento de miomas, o exame que\nmelhor avalia a sua celularidade e vascularização é:","options":{"A":"tomografia computadorizada","B":"ultrassonografia transvaginal","C":"ressonância magnética","D":"ultrassonografia transvaginal com Doppler colorido","E":"histerossalpingografia"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-11161","number":"11161","sourceNumber":"11161","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente no décimo dia pós-operatório de histerectomia total abdominal refere perda de\nlíquido, de forma contínua, pela vagina e relata que está tendo micções normais.\n\nO exame subsidiário a ser solicitado, é:","options":{"A":"tomografia computadorizada do abdome.","B":"ressonância magnética de abdome e pelve.","C":"urografia excretora.","D":"cistoscopia.","E":"ultrassonografia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-11147","number":"11147","sourceNumber":"11147","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 34 anos de idade e companheiro de 38 anos de idade, com infertilidade\nconjugal há 5 anos. Propedêutica feminina\nnormal, e espermograma em 2 amostras com\noligoastenozoospermia e com 8.000.000 de espermatozoides recuperados após capacitação. O\ntratamento desse casal é:","options":{"A":"Fertilização in vitro.","B":"Injeção intracitoplasmática de gametas.","C":"Inseminação com sêmen do marido.","D":"Clínico com antibióticos.","E":"Clínico com testosterona."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-11151","number":"11151","sourceNumber":"11151","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Decorridos 10 dias de uma histerectomia total abdominal, a paciente passou a\napresentar corrimento vaginal aquoso. A\nintrodução transuretral de azul metileno, observou-se a\ngaze molhada com líquido incolor apenas 20 minutos depois. A suspeita do diagnóstico é de:","options":{"A":"fístula vesicovaginal.","B":"fístula uretrovaginal.","C":"fístula ureterovaginal.","D":"granuloma da cúpula vaginal.","E":"fístula uterovaginal."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-15795","number":"15795","sourceNumber":"15795","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 29 anos de idade, G2P0A2, abortamentos espontâneos com 9 e 8 semanas\nde gestação, sendo o último há dois anos e meio,\nvem procurar auxílio para uma próxima gestação.\nFoi investigada em uma clínica de infertilidade e tem histerossalpingografia com verticalização das\ntrompas, que se mostram permeáveis, histeroscopia normal, espermograma do marido normal. Os\nciclos menstruais são de 28 dias, com duração de 4 dias e dismenorreia. Nesse caso, a etiologia\nmais provável é fator:","options":{"A":"tubário.","B":"ovulatório.","C":"peritoneal.","D":"cervical.","E":"masculino."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-15797","number":"15797","sourceNumber":"15797","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 29 anos de idade, G2P0A2, abortamentos espontâneos com 9 e 8 semanas\nde gestação, sendo o último há dois anos e meio,\nvem procurar auxílio para uma próxima gestação.\nFoi investigada em uma clínica de infertilidade e tem histerossalpingografia com verticalização das\ntrompas, que se mostram permeáveis, histeroscopia normal, espermograma do marido normal. Os\nciclos menstruais são de 28 dias, com duração de 4 dias e dismenorreia.\n\nO próximo passo a ser dado é realizar:","options":{"A":"inseminação artificial.","B":"fertlização in vitro.","C":"estimulação da ovulação.","D":"videolaporoscopia.","E":"teste pós-coital."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343366","number":"343366","sourceNumber":"343366","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação à miomatose uterina, assinale a alternativa falsa.","options":{"A":"Os análogos do GnRH são aprovados par utilização por curtos períodos, de aproximadamente 4\na 6 meses.","B":"Os análogos de GnRH somente são utilizados de forma isolada, quando não é factível a cirurgia.","C":"Os análogos de GnRH tem a desvantagem de causar fogachos e aumentar o risco de\nosteoporose.","D":"Miomas assintomáticos não requerem tratamento cirúrgico."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-281895","number":"281895","sourceNumber":"281895","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Para uma mulher de 46 anos com queixa de ciclos longos e hipermenorreicos, a melhor\nopção no momento é:","options":{"A":"Terapia hormonal com estrogênio e progesterona contínuo.","B":"Terapia hormonal com estrogênio e progesterona cíclicos.","C":"Progesterona na segunda fase do ciclo.","D":"Estrogênio na primeira fase do ciclo."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-181178","number":"181178","sourceNumber":"181178","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Das drogas listadas, aquela que não é boa opção no tratamento de endometriose é:","options":{"A":"Estrógenos conjugados.","B":"Progesterona micronizada.","C":"Análogos do GnRH.","D":"Noretisterona."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-157578","number":"157578","sourceNumber":"157578","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 45 anos, Gesta 3 Para 3 (3 cesáreas), com queixa de dismenorreia progressiva\nhá 3 anos. Frente a esse quadro, indique a\nMAIS provável etiologia.","options":{"A":"Estenose cervical.","B":"Doença inflamatória pélvica aguda.","C":"Doença inflamatória pélvica crônica.","D":"Endometriose."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-162507","number":"162507","sourceNumber":"162507","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Maria Aparecida, 61 anos, vem à consulta na Unidade de Saúde da Família (USF)\ntrazer a Ultrassonografia (USG)\ntransvaginal que o médico havia solicitado por conta de um\nsangramento uterino. Ela entrou na menopausa há 10 anos e não faz reposição hormonal e a USG\nevidencia, apenas, endométrio com espessura de 6mm. Quanto a esse caso, é correto afirmar que","options":{"A":"o diagnóstico é miomatose uterina.","B":"o diagnóstico é neoplasia de endométrio.","C":"o encaminhamento para um ginecologista é necessário.","D":"esse caso pode ser acompanhado apenas na Atenção Básica.","E":"a mulher deve ser encaminhada ao ginecologista quando a espessura do endométrio estiver\nmaior que 7mm."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-139742","number":"139742","sourceNumber":"139742","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual é a conduta IMEDIATA diante de uma suspeita de mioma uterino com\nhipermenorreia?","options":{"A":"A Curetagem.","B":"A Histerectomia.","C":"A Miomectomia por Histeroscopia.","D":"A Colposcopia."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134738","number":"134738","sourceNumber":"134738","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, G2P0A2C0, ambos abortos espontâneos no 1º trimestre de\ngestação, sem curetagem, vem para consulta de rotina, nega morbidades e medicações, refere\nciclos regulares de 28 dias, porém com fluxo aumentado e coágulos, com duração de 10 dias.\nDiante de tal caso, podemos suspeitar de qual patologia?","options":{"A":"Pólipo endometrial.","B":"Mioma subseroso.","C":"Endometriose pélvica.","D":"Cisto de ovário roto."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134698","number":"134698","sourceNumber":"134698","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, nuligesta, desejosa de engravidar, casada com parceiro\nvasectomizado há 5 anos. Nesse caso, qual é a conduta adequada?","options":{"A":"Encaminhar caso para fertilização in vitro.","B":"Encaminhar caso para inseminação intrauterina.","C":"Encaminhar caso para barriga de aluguel.","D":"Encaminhar caso para indução de ovulação e coito programado."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134735","number":"134735","sourceNumber":"134735","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação à drenagem venosa ovariana esquerda, ou seja, vascularização venosa do\novário esquerdo, ocorre para a:","options":{"A":"Veia cava inferior.","B":"Veia renal.","C":"Veia ilíaca.","D":"Veia hipogástrica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-134747","number":"134747","sourceNumber":"134747","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, G0P0, desejando gravidez há 3 anos sem sucesso, com vida\nsexual ativa, ciclos regulares, sem queixas clínicas e uso de medicações, e parceiro saudável.\nComo devemos proceder diante de tal caso de infertilidade?","options":{"A":"Induzir ovulação ambulatorialmente com citrato de clomifeno por 6 meses.","B":"Investigar o casal com todos os exames de infertilidade possíveis.","C":"Investigar primeiro a parceira e após, se tudo estiver normal, investigar o parceiro.","D":"Encaminhar para ?Fertilização in vitro? o mais rápido possível."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-111821","number":"111821","sourceNumber":"111821","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Adolescente de 17 anos, com vida sexual ativa, utilizando preservativo, apresenta\nirregularidade menstrual, ciclos a cada 45/60 dias\ncom duração de 6 dias e sangramento\naumentado, procura o pronto-socorro com história de sangramento vaginal intenso há 8 dias, com\ncoágulos. Exame ginecológico normal e teste plasmático de gravidez negativo. A MELHOR conduta\ninicial, para esse caso, é:","options":{"A":"biópsia de endométrio para orientar tratamento.","B":"progestagenio oral, após 8 dias.","C":"tratamento com anticoncepcional oral combinado.","D":"curetagem uterina."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-111884","number":"111884","sourceNumber":"111884","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação à drenagem venosa ovariana esquerda, ou seja, vascularização venosa do\novário esquerdo, esta ocorre para a veia:","options":{"A":"cava inferior.","B":"renal.","C":"ilíaca.","D":"hipogástrica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-350834","number":"350834","sourceNumber":"350834","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 48 anos, G2P1CA1, vem ao ambulatório com queixas de sangramento\ntransvaginal irregular, intermitente, de pouca\nmonta, há 5 meses. Em uso de desogestrel contínuo\nhá um ano e meio para contracepção e amitriptilina 25 mg para tratamento de transtorno depressivo\nmaior, há 7 meses. Ao exame ginecológico, colo uterino sem lesões. Trouxe ultrassonografia\ntransvaginal, que apresenta imagem nodular em fundo uterino, intramural com maior componente\nsubseroso, medindo 4,0 x 3,0 x 3,0 cm, sugestiva de leiomioma. Sobre a paciente acima,\nconsiderando a propedêutica do sangramento uterino anormal (SUA) e a Classificação\n\nPALM-COEIN da FIGO (2011), assinale a alternativa correta.","options":{"A":"Sangramento uterino anormal de causa não estrutural iatrogênica constitui uma importante\nhipótese diagnóstica a ser considerada neste caso.","B":"O exame especular deve ser evitado na vigência do sangramento, dado o desconforto do\nmesmo e possibilidade de induzir a piora do\nquadro.","C":"A ultrassonografia transvaginal é o principal exame complementar indicado, sendo a primeira\nlinha propedêutica para identificação de anomalias\nestruturais e não estruturais.","D":"Sangramento de causa estrutural constitui a principal hipótese, uma vez que a idade da paciente\najuda a direcionar o raciocínio clínico para a etiologia mais prevalente nesta faixa etária, que\nsão os\nleiomiomas uterinos."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-350832","number":"350832","sourceNumber":"350832","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 32 anos, casada, nuligesta, refere cólica menstrual desde a menarca com piora\nnos últimos anos, associada à dispareunia de profundidade. Refere que seus ciclos menstruais são\nregulares com intervalo de 28 dias e duração de 5 dias, com fluxo normal. Há 2 anos sem uso de\ncontracepção e com relações sexuais regulares, porém não consegue engravidar. Traz\nespermograma do esposo normal. Qual principal hipótese diagnóstica?","options":{"A":"Adenomiose.","B":"Endometriose.","C":"Mioma uterino.","D":"Doença inflamatória pélvica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-350830","number":"350830","sourceNumber":"350830","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 42 anos, casada, G2P2, com laqueadura tubária bilateral, procura\natendimento médico por achar que algo está\nerrado com seus hormônios há cerca de 6 meses.\nSeus ciclos menstruais ocorrem a cada 38-42 dias (antes disso, era de 27 dias), com fluxo\naumentado durando 7 a 9 dias (era de 4 dias), precedidos de mastalgia e edema transitórios. Nos\núltimos 6 meses, vem queixando-se de adinamia. Refere menarca aos 13 anos. Relata que o\nsangramento vem atrapalhando suas atividades, inclusive o sexo. Nega comorbidades. Fuma cerca\nde 5 cigarros ao dia há mais de 10 anos. Apresenta exame físico geral e ginecológico sem\nanormalidades. IMC = 26 kg/m². Traz exames complementares: FSH 4,1 mUI/mL e TSH 2,9 mU/L.\nUSG transvaginal não revelou alterações estruturais no útero. Considerando o quadro acima, qual a\nmelhor recomendação para essa mulher?","options":{"A":"Iniciar progestínico para proteção endometrial e melhora do sangramento anormal.","B":"Repor testosterona pela via transdérmica para melhora do sangramento e da queixa de\nadinamia.","C":"Orientar reposição de estrógeno e progesterona para melhora da adinamia e do padrão de\nsangramento.","D":"Recomendar monitoração dos ciclos menstruais, tranquilizando a paciente sobre sua\nproximidade do climatério."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-321376","number":"321376","sourceNumber":"321376","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paula, 33 anos, G0P0, hipertensa, com queixa de dismenorreia e fluxo menstrual\nvolumoso com coágulos. USG transvaginal\nrevelando útero com discreto aumento de volume,\nespessamento miometrial assimétrico em parede posterior com áreas de sombras acústicas e\npequenas áreas anecoicas subendometriais. Considerando o principal diagnóstico, qual conduta\nmais indicada?","options":{"A":"SIU de levonorgestrel.","B":"Adesivo contraceptivo.","C":"Análogo do GnRH por 3 anos.","D":"Histerectomia total laparoscópica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-292883","number":"292883","sourceNumber":"292883","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 26 anos, nuligesta, refere ciclos menstruais regulares com dismenorreia, dor\npélvica crônica progressiva desde menarca, além de dispareunia. Deseja engravidar mas está há\ndois anos sem métodos contraceptivos e não consegue. Realizou espermograma do companheiro\nque foi normal, Ao exame físico, encontra-se dor e espessamento bilateral em ligamentos\núterossacrais e nodularidade dolorosa em fundo de saco vaginal. Fez ultrassonografia pélvica\ntransvaginal compatível com ovários aumentados de volume bilaterais, imóveis, centralizados e\nposteriorizados. Qual a principal hipótese diagnóstica mais provável para o fator causal dessa\ninfertilidade primária.","options":{"A":"Endometriose profunda.","B":"Falência ovaríana prematura.","C":"Sequela de Doença Inflamatória pélvica.","D":"Anovulação crônica por Síndrome de Ovários Policísticos."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-292884","number":"292884","sourceNumber":"292884","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 35 anos, G3P2A0, três cesáreas prévias, com história de sangramento uterino\nde 9 dias de duração, com intervalo cíclico\nmensal regular e de grande volume que extravasa do\nabsorvente, desde última cesárea ha 8 anos. Associado quadro de cólicas incapacitantes em baixo\nventre, progressiva, que intensifica nos primeiros 3 dias de fluxo necessitando de AINEs. Refere\nanemia crônica e fraqueza. Realizou ultrassonografia pélvica transvaginal que excluiu a\npossibilidade de leiomiomas e mostrou um útero aparentemente normal. Assinale a assertiva\ncorreta que corresponde à causa mais provável do sangramento uterino anormal.","options":{"A":"Endometrite.","B":"Adenomiose.","C":"Coagulopatia.","D":"Anovulação crônica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-292885","number":"292885","sourceNumber":"292885","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, multípara de 65 anos, com menopausa aos 50 anos, assintomática desde\nentão. Sem comorbidades. Realiza exames\nginecológicos regulares sem alterações. Apresenta\nsangramento uterino anormal há 3 dias em pequena quantidade de aspecto descrito como em\nborra de café. Nega dores abdominais ou quaisquer outras queixas. Assinale a assertiva correta\nquanto ao diagnóstico mais provável para este caso de sangramento uterino anormal.","options":{"A":"Neoplasia intraepitelial endometrial.","B":"Neoplasia intraepitelial cervical.","C":"Adenocarcinoma de endométrio.","D":"Atrofia endometrial."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-259769","number":"259769","sourceNumber":"259769","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 44 anos, G1P1A0, com história prévia de trombose venosa profunda na\ngestação, procura atendimento médico com\nquadro de sangramento vaginal intenso, com presença\nde coágulos, há 4 dias, após atraso menstrual de cerca de 2 meses. Apresenta-se hipocorada e\nsudoreica, com pressão arterial de 80x60mmHg e pulso de 110ppm, após hidratação venosa. Ao\nexame especular, visualiza-se grande quantidade de sangue fluindo por orifício cervical externo,\ncolo e vagina sem lesões. Ao toque vaginal, útero de consistência, contorno e volume normais, colo\nmóvel e impérvio. Teste imunológico de gravidez negativo. Qual a conduta adequada para o caso?","options":{"A":"Realizar curetagem uterina.","B":"Aguardar resultado de ultrassonografia transvaginal.","C":"Inserir sistema intrauterino liberador de levonorgestrel.","D":"Administrar acetato de medroxiprogesterona 150mg intramuscular."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234098","number":"234098","sourceNumber":"234098","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 21 anos, assintomática, procura atendimento médico por apresentar alteração\nem exame de imagem. Relata que foi solicitada\nultrassonografia abdominal de rotina que mostrou\nhidronefrose à direita leve. Em seguida, foi solicitada ressonância abdominal e pélvica que mostrou\nlesão intestinal de 3 cm sugestiva de endometriose, hidronefrose em ureter direito no terço distal\nsem cálculos, lesão vesical de 2 cm também sugestiva de endometriose. Qual conduta deve ser\nrealizada?","options":{"A":"Indicar Dispositivo intrauterino de levonogestrel.","B":"Iniciar imediatamente dienogest 2mg uso contínuo.","C":"Indicar cirurgia de exérese de endometriose profunda.","D":"Passar duplo J e manter até resolução espontânea da hidronefrose."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234099","number":"234099","sourceNumber":"234099","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 35 anos, com desejo de engravidar, comparece preocupada com ultrassom\ntransvaginal com útero de 200cm³ com presença de nódulo hipoecogênico de 4 cm, tipo 7 pela\nclassificação da FIGO. Ela refere ciclos regulares com fluxo de 4 dias sem coágulos. Nega dor.\nQual a melhor conduta?","options":{"A":"Expectante.","B":"Análogo do GnrH.","C":"Miomectomia laparoscópica.","D":"Miomectomia histeroscópica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234100","number":"234100","sourceNumber":"234100","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 25 anos, nuligesta, uso de condom como contraceptivo, nega comorbidades ou\nuso de medicações, procura atendimento com\nsangramento transvaginal intenso há mais de 15\ndias. Apresenta nos antecedentes ginecológicos ciclos regulares com sangramento de fluxo\nprogressivamente aumentado por 10 dias. Exame físico ginecológico sem alterações. Realizou\n\nB-HCG sanguíneo, cujo resultado foi negativo. Qual é a investigação inicial mais adequada para\niniciar a propedêutica complementar da hemorragia uterina anormal?","options":{"A":"Solicitar hemograma completo, coagulograma e ultrassom transvaginal.","B":"Solicitar perfil hormonal completo para avaliar anovulação crônica.","C":"Orientar sobre a imaturidade do eixo hipotálamo-hipófise-ovário.","D":"Solicitar exames para diagnosticar as principais trombofilias."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234103","number":"234103","sourceNumber":"234103","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 55 anos, menopausa aos 50, vem ao ambulatório com queixa de sangramento\ngenital em pequena quantidade, por dois\ndias, há uma semana. Nega terapia de reposição\nhormonal e traz ultrassom transvaginal que mostra útero medindo 100cm³, endométrio de 3mm e\novários não identificados. Diante desse caso clínico, qual a conduta mais adequada a seguir?","options":{"A":"Solicitar histeroscopia para afastar espessamento endometrial.","B":"Indicar biópsia endometrial para afastar câncer de endométrio.","C":"Realizar exame especular e toque vaginal para afastar lesões de colo e vagina.","D":"Inserir Sistema Intrauterino liberador de Levonorgestrel (SIU-LNG) para controlar sangramento."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-199724","number":"199724","sourceNumber":"199724","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 34 anos, G0P0, com desejo de gestar há 4 meses, apresenta quadro de\naumento do número de dias de sangramento\nmenstrual e aumento do fluxo há 1 ano. Ao exame\nfísico, apresenta útero aumentado de volume 3 cm acima da sínfise púbica. Solicitado hemograma\ncom Hb = 9.5 g/dl e Ht = 36%; plaquetas = 200.000; coagulograma normal. A ultrassonografia\ntransvaginal mostrou um útero de 140 cm³ com mioma submucoso de 4 cm e outro subseroso de 3\ncm em parede posterior. À histeroscopia diagnóstica, notou-se um mioma submucoso pontuação 5\nna classificação de Lasmar (grupo II). Qual a melhor conduta nesse caso?","options":{"A":"Seguimento clínico devido ao desejo de gestar nesse momento.","B":"Anticoncepcional oral combinado de média dosagem por 2 a 3 meses.","C":"Análogo do GnRH por 3 a 6 meses seguido de miomectomia histeroscópica.","D":"Miomectomia laparoscópica devido à impossibilidade de miomectomia histeroscópica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-199736","number":"199736","sourceNumber":"199736","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal homoafetivo masculino, de 26 e 32 anos, procura atendimento por desejo de\ngravidez. Sugeriram a irmã de um dos parceiros para doação de oócitos e cessão temporária de\nútero. Que opção deve ser indicada, em acordo com a resolução do Conselho Federal de Medicina\nvigente?","options":{"A":"Doação de até quatro oócitos pela irmã de um dos parceiros e cessão temporária de útero pela\nmesma.","B":"Doação anônima de oócitos, com transferência de até quatro embriões para a irmã de um dos\nparceiros.","C":"Doação de oócitos pela irmã de um dos parceiros e cessão de útero com ressarcimento\nfinanceiro\n\ncombinado previamente.","D":"Doação anônima de oócitos, com transferência de até cinco embriões para útero de mulher sem\nparentesco com os parceiros."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-173006","number":"173006","sourceNumber":"173006","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 30 anos, refere dismenorreia primária com escala visual da dor (EVA) de 6/10\nevoluindo para dor pélvica crônica acíclica com EVA de 8/10 há 3 anos. Além disso, apresenta\ndispareunia de profundidade e também superficial, dor ao enchimento vesical e aumento da\nfrequência urinária com urgência. Queixa-se de fezes endurecidas, com dificuldade de evacuar,\nevacuações duas vezes por semana e tenesmo não relacionado à menstruação há 2 anos. Ao\nexame físico, abdome plano, flácido pouco doloroso à palpação, toque vaginal: dor à palpação em\nmúsculo obturador esquerdo com ponto de gatilho, útero móvel pouco doloroso à palpação. Quanto\nà investigação das causas de dor, quais principais diagnósticos diferenciais?","options":{"A":"Síndrome do intestino irritável, endometrioma ovariano e vaginismo.","B":"Constipação crônica, síndrome da bexiga dolorosa e dor miofascial.","C":"Endometriose profunda em fórnice vaginal e síndrome da bexiga hiperativa.","D":"Fibromialgia, doença inflamatória intestinal e infecção do trato urinário inferior."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-173039","number":"173039","sourceNumber":"173039","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 60 anos iniciou quadro de sangramento transvaginal vermelho vivo, de\nmoderada intensidade, há cerca de 15 dias. Menopausa aos 50 anos. Exame físico especular e\ntoque vaginal sem anormalidades. Citologia oncótica recente negativa para malignidades.\n\nUltrassom transvaginal: útero com volume de 65 cm³ em AVF, textura miometrial homogênea, com\nendométrio heterogêneo medindo 10 mm. Ovários de pequeno volume. Realizou histeroscopia\ndiagnóstica: cavidade uterina de tamanho normal, com pólipo séssil de cerca de 1,5 cm.\n\nEndométrio de aspecto fino. Biópsia de endométrio com cureta de Novak: hiperplasia endometrial\nsem atipias na amostra. Qual a melhor conduta a\nseguir?","options":{"A":"Progestínico oral por 6 meses seguido de nova amostragem endometrial.","B":"Amostragem ampla endometrial por meio de curetagem semiótica.","C":"Histerectomia total com avaliação intraoperatória de anexos.","D":"Histeroscopia cirúrgica com polipectomia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-150890","number":"150890","sourceNumber":"150890","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 27 anos, obesa e hipertensa, chega ao pronto-atendimento com sangramento\nmenstrual de grande intensidade com\ncoágulos. Refere ciclos menstruais irregulares. Ao exame\nfísico, apresenta-se hipocorada, PA: 110 x 70 mmHg, FC: 84 bpm, abdome flácido, indolor, sem\nmassas. Teste Beta-hcg: negativo e Hb: 8,5 g/dL e Ht: 25,5%. Qual tratamento inicial mais\nadequado?","options":{"A":"Realizar curetagem semiótica e encaminhar material para histopatológico, associando uso do\nanálogo do GNRH 10,8 mg dose única.","B":"Etinilestradiol 30Mcg associado a Levonogestrel 0,15 mg de 8/8h até que o sangramento tenha\ncessado por 24h, reduzindo dose gradualmente.","C":"Ácido tranexâmico 250 mg 12/12h associado a Ibuprofeno 300 mg 8/8h até cessar sangramento,\nassociado a medroxiprogesterona 150 mg\ndose única.","D":"Estrogênio equino conjugado 2,5 mg via endovenosa associado a ácido tranexâmico 250 mg de\n8/8h por 7 dias, após isso iniciar anticoncepcional oral combinado."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-150791","number":"150791","sourceNumber":"150791","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente feminina, 65 anos, menopausa aos 52 anos, diabética e obesa, realizou\nultrassonografia transvaginal de rotina que mostrou:\nútero de volume normal, endométrio de 10 mm,\novários atróficos. Teve episódio de sangramento vaginal há alguns meses. Sem outras queixas.\n\nQual a melhor conduta?","options":{"A":"Repetir ultrassonografia transvaginal em 6 meses.","B":"Encaminhar para histerectomia total com biópsia de congelação.","C":"Realizar vídeo-histeroscopia com biópsia endometrial dirigida.","D":"Indicar ablação endometrial diagnóstica e possivelmente terapêutica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-150794","number":"150794","sourceNumber":"150794","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 30 anos refere dispareunia de profundidade há 2 anos. Durante a anamnese,\nrelatou dismenorreia primária progressiva\nassociada à disquezia e diarreia, além de dor pélvica\nquase diária de forte intensidade. Para melhor investigação da causa do quadro clínico é\nnecessário:","options":{"A":"solicitar exame ultrassonográfico transvaginal, leucograma e PCR, pois deve tratar-se de quadro\nde doença inflamatória pélvica aguda.","B":"realizar teste terapêutico com infusão de Lidocaína vaginal para tratamento da dispareunia após\navaliação do exame vaginal bigital do assoalho pélvico.","C":"avaliar, ao exame ginecológico bimanual, a presença de nodulações em fundo de saco posterior\ne de dor à mobilização uterina, pois sua\nausência afasta endometriose.","D":"verificar, ao exame ginecológico bimanual, o achado de útero com pouca mobilidade, dor à sua\nmanipulação e solicitar ultrassom transvaginal com preparo intestinal."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-150807","number":"150807","sourceNumber":"150807","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal infértil por falência ovariana, mulher com 45 anos e homem com 51 anos, decide\nrealizar fertilização in vitro após consulta com o ginecologista. Quanto ao aconselhamento, de\nacordo com a Resolução do CFM 2.121/2015, deve-se:","options":{"A":"relatar que a doadora de óvulos não pode ter mais de 35 anos para garantir que o óvulo seja\nsaudável e que a gestação seja mais segura.","B":"permitir que o casal pague a uma vizinha de 30 anos, que tem prole completa, para doar seus\nóvulos para que eles realizem a fertilização in vitro.","C":"escolher, no banco de gametas da clínica, óvulos compatíveis com as características fenotípicas\ndo casal para a realização da fertilização in\nvitro.","D":"informar que a idade máxima, tanto para a mulher quanto para o homem, para técnicas de\nreprodução assistida é 50 anos, impossibilitando o casal em questão."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-126946","number":"126946","sourceNumber":"126946","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 35 anos, comparece à Unidade de Saúde com queixa de dor pélvica há 5 anos\ne dispareunia profunda, com piora progressiva da\nintensidade. Ao exame físico, durante o toque\nvaginal, o médico observa que a paciente apresenta o útero em retroversoflexão fixa. Assinale a\nassertiva correta que corresponde ao procedimento adequado para encontrar a retroversoflexão\nfixa.","options":{"A":"Os dedos médio e indicador enluvados são inseridos juntos na vagina até que o colo uterino seja\nalcançado, mobilizando-o lateralmente, na altura do orifício externo, percebendo-se os fundos de\nsaco vaginais laterais, abaulados.","B":"Os dedos médio e indicador enluvados percorrem a extensão posterior do colo uterino, o istmo\nuterino é percebido em trajeto descendente e ao se percorrer a extensão anterior do colo a bexiga\nserá sentida no trajeto ascendente.","C":"Os dedos médio e indicador enluvados embaixo do colo uterino elevam o útero na direção da\nparede anterior do abdome. A mão posicionada sobre o abdome, próximo à sínfise púbica,\ndetecta a pressão exercida pelo fundo uterino com facilidade e mobilidade.","D":"Os dedos médio e indicador enluvados são inseridos juntos na vagina até que o colo uterino seja\nalcançado, a posição uterina é avaliada pelo toque do dedo indicador ao longo da\n\nextensão anterior do colo uterino, sendo o istmo uterino aí tocado, em trajeto ascendente."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-126976","number":"126976","sourceNumber":"126976","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 30 anos, G0P0A0, sem comorbidades. Comparece ao consultório com\nsangramento menstrual aumentado em volume e duração de 8 dias, associado à dismenorreia de\nleve a moderada intensidade. Exame ginecológico sem alterações. Realizou ultrassonografia\npélvica com achados normais à exceção de imagem hipoecogênica sugestiva de leiomioma\nsubmucoso, no fundo do endométrio, de 3 cm no maior diâmetro. Sobre o tratamento mais\nadequado desse caso, assinale a opção correta.","options":{"A":"Histerectomia vaginal.","B":"Miomectomia laparoscópica.","C":"Miomectomia histeroscópica.","D":"Dispositivo intra-uterino de levonogestrel."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-102142","number":"102142","sourceNumber":"102142","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 45 anos de idade com queixa de sangramento transvaginal volumoso\nassociado a cólicas uterinas há 10 dias.\nInforma ciclos menstruais regulares. Nega atraso\nmenstrual. Exame especular mostra colo e vagina sem anormalidades. Toque vaginal revela\ndiscreto aumento do volume uterino, consistência fibro-elástica e superfície regular. Trouxe ß-HCG\nnegativo. Diante desse quadro clínico, qual a melhor conduta a seguir?","options":{"A":"Solicitar TSH, FSH e Prolactina.","B":"Solicitar ultrassonografia transvaginal.","C":"Realizar uma histeroscopia com biópsia.","D":"Realizar uma curetagem uterina semiótica."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-102146","number":"102146","sourceNumber":"102146","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O Conselho Federal de Medicina, em abril de 2013, publicou uma nova resolução\n(2013/13) que adota as normas éticas para a\nutilização das técnicas de Reprodução Assistida no\nBrasil. De acordo com essa nova resolução, assinale a opção certa sobre reprodução assistida no\nBrasil.","options":{"A":"A idade máxima das candidatas à gestação é de 52 anos.","B":"O número máximo de embriões a serem transferidos varia de 2 a 4 de acordo com a idade da\nreceptora.","C":"Em caso de gravidez múltipla, é permitida a redução embrionária, quando exceder o número\nmáximo de embriões permitidos.","D":"As doadoras temporárias do útero devem pertencer à família de um dos parceiros num\nparentesco consanguíneo até o terceiro grau."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-102162","number":"102162","sourceNumber":"102162","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 22 anos de idade procura o serviço de infertilidade após dois anos de\nexposição sexual sem contracepção. Refere\nmenstruações regulares sem dismenorreia. Seu\nparceiro tem um filho e fez espermograma recentemente, dentro da normalidade. Foi submetida a\numa drenagem de abscesso de Bartholin há 3 anos. Exame físico normal. Qual dos exames abaixo\ndeve ser solicitado para investigar o fator de infertilidade mais provável?","options":{"A":"Dosagem de FSH.","B":"Histerossalpingografia.","C":"Biópsia do endométrio.","D":"Ultrassonografia transvaginal."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-81269","number":"81269","sourceNumber":"81269","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mariana, 24 anos de idade, vem a um serviço de emergência com quadro agudo de dor\nforte e contínua no baixo-ventre, náuseas e vômitos após uma relação sexual. Ao exame físico, o\nabdome inferior é bastante doloroso, com descompressão súbita dolorosa. Palpa-se massa anexial\nà direita. Tensão arterial normal, pulso de 100 bpm e temperatura de 37,5°C. Tem vida sexual ativa\ne não usa qualquer método contraceptivo. Dentre os diagnósticos diferenciais abaixo, qual a causa\nmais provável?","options":{"A":"Apendicite.","B":"Gravidez ectópica rota.","C":"Torção de Cisto Ovariano.","D":"Doença Inflamatória Pélvica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-81317","number":"81317","sourceNumber":"81317","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 32 anos de idade, casada há 8 anos, deseja gravidez. G1P0A1. Refere ciclos\nmenstruais de duração normal, que se acompanham de aumento no volume menstrual há 3 anos e\nse associam à dismenorreia progressiva. No último ano, foi a um pronto atendimento, em duas\noportunidades, por dor intensa no baixo ventre, que piorava no período menstrual. Qual a causa da\ninfertilidade mais diretamente relacionada à história da paciente?","options":{"A":"Doença inflamatória pélvica levando à obstrução tubária e consequente hidrossalpinge.","B":"Endometriose peritoneal ou ovariana, distorcendo as relações anatômicas dos órgãos\nreprodutivos.","C":"Síndrome dos ovários policísticos, com hiperestímulo ovariano, com eventuais roturas dos cistos\ne irritação peritoneal.","D":"Adenomiose, comumente associada à miomatose uterina. A primeira causando as cólicas\nuterinas; a segunda, o sangramento."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-65688","number":"65688","sourceNumber":"65688","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Adolescente de 14 anos, virgem, menarca aos 12 anos, vem ao ambulatório com\nqueixa de irregularidade menstrual. Refere\nsangramento por mais de 10 dias durante os períodos,\nàs vezes volumoso e com intervalos de 20 a 40 dias, há cerca de seis meses. Ao exame físico,\nobservou-se hímen íntegro e ausência de sangramento ativo. O ß-HCG deu negativo, a\nhemoglobina foi de 9 mg/dl e a ultrassonografia pélvica normal. Qual a prescrição mais adequada?","options":{"A":"Sulfato ferroso.","B":"Ácido tranexâmico.","C":"Contraceptivo oral combinado.","D":"Anti-inflamatórios não esteroidais.","E":"Anti-inflamatórios não esteroidais e ácido tranexâmico."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-65684","number":"65684","sourceNumber":"65684","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 27 anos de idade, G2P0A2, realizou histerossalpingografia e ultrassonografia\ntridimensional para avaliação de dois abortamentos espontâneos no 1º trimestre, com os achados\nnas figuras abaixo. Qual cirurgia deve ser indicada? (VER IMAGEM)","options":{"A":"Metroplastia por via vaginal.","B":"Metroplastia por via laparoscópica.","C":"Metroplastia abdominal de Strassman.","D":"Ressecção por laparotomia exploradora.","E":"Ressecção histeroscópica com laparoscopia."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":["question_bank/media/medcurso/medcurso-gineco-gin-2/65684.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-65682","number":"65682","sourceNumber":"65682","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 16 anos de idade, virgem, com menarca há dois anos, procura atendimento\npor menorragia há cerca de quatro meses, com piora\nnos últimos 15 dias. Nega comorbidades ou\nuso de medicações. O tratamento inicial para controle imediato do sangramento deverá ser feito\ncom:","options":{"A":"anti-inflamatórios por dois meses.","B":"progestínicos orais cíclicos por 10 dias.","C":"agentes fibrinolíticos no período menstrual.","D":"sistema intrauterino contendo levonorgestrel.","E":"contraceptivos hormonais orais de baixa dosagem."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-65678","number":"65678","sourceNumber":"65678","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 24 anos de idade vem com queixa de que não engravida há oito meses.\nApresenta ciclos menstruais regulares desde a menarca aos 12 anos. Nega cirurgias pélvicas e\nabdominais e refere nunca ter sido acometida de doenças sexualmente transmissíveis. O marido\ntem um filho de oito anos, de relacionamento anterior. O exame de sêmen foi normal, assim como\nas dosagens hormonais: FSH basal e progesterona no 22º dia do ciclo. Baseado na história e nos\nachados dos exames, incluindo o mostrado na histerossalpingografia abaixo, defina qual a melhor\nconduta para o casal. (VER IMAGEM)","options":{"A":"Indicar a indução da ovulação com citrato de clomifeno e coito programado por quatro meses.","B":"Aguardar seis meses para completar a confirmação da infertilidade.","C":"Indicar a fertilização in vitro e transferência de embrião.","D":"Indicar a inseminação artificial homóloga.","E":"Indicar a inseminação artificial heteróloga."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":["question_bank/media/medcurso/medcurso-gineco-gin-2/65678.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-65677","number":"65677","sourceNumber":"65677","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 40 anos de idade apresenta dismenorreia intensa há 4 anos,\nacompanhada de menorragia com aumento do\nfluxo e do número de dias, chegando até 10 dias. O\nciclo era regular de 30 a 32 dias. Fez ultrassonografia que revelava útero de 250 cm³, diâmetros\nanteroposterior de 6 cm e transverso de 5,8 cm. Eco endometrial de 9 mm e miométrio heterogêneo\ncom várias imagens hipoecoicas. Foi submetida a histerectomia como tratamento. A histopatologia\nda peça mais provavelmente revelava:","options":{"A":"alteração pré-maligna do miométrio.","B":"alteração pré-maligna do endométrio.","C":"miomatose uterina com alto índice mitótico.","D":"glândulas endometriais e estroma na intimidade do músculo uterino.","E":"modificação metaplásica do epitélio glandular em fibras musculares no útero."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-51112","number":"51112","sourceNumber":"51112","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 55 anos foi atendida por apresentar sangramento irregular 4 anos após\na menopausa, aos 51 anos. Ela nunca teve filhos\ne tem sobrepeso. Não faz uso de terapia\nhormonal. Faz exame preventivo do colo uterino anualmente e os resultados eram normais, exceto\npelo último, que mostrou anomalias glandulares. Foi encaminhada a realizar ultrassonografia\ntransvaginal que evidenciou laudo de útero levemente aumentado de volume (100 cc), miométrio\nheterogêneo e espessura endometrial de 7 mm. O ultrassonografista chama atenção para um cisto\novariano de aspecto benigno. Qual a opção que expressa um raciocínio acertado do ginecologista?","options":{"A":"A ultrassonografia transvaginal é um método viável para a previsão de hiperplasia endometrial.\n\nEm mulheres pós-menopáusicas com espessura endometrial de 5 mm ou menos, estudos têm\ndemonstrado que o sangramento pode ser atribuído à atrofia do endométrio e dispensa a biópsia.","B":"Naquelas com espessura de endométrio maiores que 4 mm, deve-se realizar a biópsia\nambulatorial com cureta de Novak inicialmente,\ne alternativamente, a dilatação e curetagem. A\nhiperplasia de endométrio pode ser identificada visual e precisamente com a histeroscopia.","C":"Tomografia computadorizada ou ressonância magnética não são necessárias. No entanto, a\ntomografia pode ajudar a distinguir um câncer endometrial do cervical. Nestes casos, o\nconhecimento prévio de doença intra-abdominal pode ser útil na orientação do tratamento.","D":"Ocasionalmente, uma massa anexial pode ser encontrada no exame. Embora este\nprovavelmente é um cisto de ovário benigno,\nquaisquer tumores sólidos à ultrassonografia\ntransvaginal deve levantar a possibilidade de um tumor de células da granulosa, que pode resultar\nem um risco elevado para hiperplasia ou carcinoma endometrial."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-51111","number":"51111","sourceNumber":"51111","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 34 anos procura o ginecologista por infertilidade. Vem apresentando cólicas\nuterinas fortes desde os 27 anos e, nos últimos 12 meses, tem piorado bastante. Procurou por duas\noportunidades um pronto atendimento médico onde utilizou analgésicos injetáveis e realizou uma\nultrassonografia transvaginal que revelou uma massa anexial mista de cerca de 6 cm de maior\ndiâmetro. Qual a análise correta do caso?","options":{"A":"O diagnóstico é de endometriose ovariana e isso nos autoriza um tratamento clínico.","B":"O diagnóstico mais provável é de endometriose peritoneal e necessitamos de uma biópsia\nendometrial para confirmá-lo.","C":"Para o diagnóstico do seu problema básico, faz-se necessária uma histerossalpingografia e o\nmarido deve realizar um espermograma.","D":"Após solicitarmos uma nova ultrassonografia e uma dosagem sérica do CA-125, a conduta deve\nser cirúrgica, pois confirma o diagnóstico e\ntrata a lesão ovariana."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-51282","number":"51282","sourceNumber":"51282","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 36 anos apresenta sangramento uterino anormal, inicialmente menorrágico, e\nhá 7 meses, metrorrágico, acompanhado de\ncólica uterina. Com relação à investigação diagnóstica\ncomplementar desse caso, qual a alternativa correta?","options":{"A":"Além de inspeção da cavidade, a histeroscopia permite uma biópsia dirigida do endométrio com\ndiagnóstico histológico de áreas anormais. É um meio seguro e preciso para identificar hiperplasias\ne cânceres de origem endometrial.","B":"A ultrassonografia transvaginal, em vez de biópsia endometrial, é exame de primeira linha para\navaliar o sangramento anormal, pois oferece informações em relação ao endométrio que não é\noferecido por histeroscopia ou biópsia.","C":"A ultrassonografia transvaginal com Color Doppler tem sido utilizada na identificação e\ndiferenciação entre miomas submucosos e pólipos endometriais no contexto de sangramento\nuterino anormal. É padrão-ouro para investigação de hiperplasias e cânceres do endométrio.","D":"Não há uma sequência clara para uso de biópsia endometrial, ultrassonografia transvaginal e\nhisteroscopia na avaliação de sangramento uterino anormal. Nenhuma dessas irá distinguir todas\nas lesões anatômicas com alta sensibilidade e especificidade."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-51297","number":"51297","sourceNumber":"51297","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 28 anos procura médico por dispareunia há 6 meses. Traz relatório cirúrgico\nde que foi operada há 8 anos de apendicite. Na\noportunidade, o cirurgião verificou, no fundo de\nsaco de Douglas, algumas lesões avermelhadas, bolhosas e outras enegrecidas que foram\nbiopsiadas. O resultado da biópsia mostrou estroma endometrial e hemossiderófagos. O exame\nfísico foi normal assim como o exame ultrassonográfico. Qual o tratamento mais indicado para o\ncaso?","options":{"A":"Uso de análogos de GnRH.","B":"O uso de dispositivo intrauterino (DIU, Cobre-380).","C":"Uso de anticoncepcionais orais combinados de forma cíclica.","D":"Uso de anticoncepcionais orais combinados ou por progestagenios, de forma contínua."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-51300","number":"51300","sourceNumber":"51300","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 40 anos de idade vem apresentando sangramento vaginal irregular e\nabundante há 8 meses. Ao toque vaginal, evidenciou-se útero de volume aumentado e de\nsuperfície irregular. A análise histológica do útero, após histerectomia, revelou a presença de\ncélulas musculares lisas alongadas, agregadas em feixes, de baixa atividade mitótica e sem\norganização vascular intrínseca. Qual o diagnóstico histológico da paciente?","options":{"A":"Adenocarcinoma endometrial.","B":"Leiomiomatose uterina.","C":"Leiomiossarcoma.","D":"Adenomiose."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-141616","number":"141616","sourceNumber":"141616","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente nuligesta, 29 anos, há 6 meses com aumento do fluxo menstrual e do número\nde dias de menstruação, que chega a durar\ncerca de 30 dias. Realizou USTV que evidenciou dois\nnódulos com características de miomas submucosos, medindo cerca de 3 cm e 2 cm, causando\ndistorção da cavidade uterina e útero medindo 150cm3. Qual a melhor conduta nesse caso?","options":{"A":"Miomectomia laparoscópica.","B":"DIU de levonogestrel.","C":"Miomectomia Histeroscópica.","D":"Histerectomia Abdominal."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-45365","number":"45365","sourceNumber":"45365","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A melhor definição para irregularidades menstruais em que o sangramento ocorre em\nperíodos regulares e de quantidade diminuída é:","options":{"A":"oligomenorreia.","B":"menorragia.","C":"menometrorragia.","D":"hipomenorreia.","E":"metrorragia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-45355","number":"45355","sourceNumber":"45355","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A confirmação histológica de endometriose é baseada na presença de:","options":{"A":"macrófagos com hemossiderina.","B":"camadas de tecido compacto.","C":"células cilíndricas.","D":"células cuboides.","E":"tecido muscular liso."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-37001","number":"37001","sourceNumber":"37001","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 28 anos de idade tem ciclos regulares, com discreta dismenorreia\ndesde a menarca. Vem ao ginecologista para\ntentar engravidar e traz consigo uma\nhisterossalpingografia que mostrava hidrossalpinge bilateral. Que opção\n\nterapêutica oferece melhor taxa de sucesso em relação à gravidez?","options":{"A":"Fertilização in vitro.","B":"Neosalpingostomia por microcirurgia\nlaparotômica.","C":"Neosalpingostomia por laparoscopia.","D":"Salpingectomia seguida de fertilização in\nvitro."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-25293","number":"25293","sourceNumber":"25293","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Ovogônias alcançam o número máximo em qual das seguintes fases do\ndesenvolvimento humano?","options":{"A":"início da idade adulta (21 a 26 anos).","B":"puberdade (12 a 14 anos).","C":"5 meses de vida fetal.","D":"adolescência (12 a 18 anos).","E":"nascimento."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-25297","number":"25297","sourceNumber":"25297","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente procurou o ambulatório de obstetrícia da MEAC, depois de diversas consultas\nem outros nosocômios. O objetivo das consultas\nera engravidar. Após ter sido orientada\ncorretamente sobre o melhor momento do ciclo ovulatório, e a melhor posição que favorece a\nconcepção durante a relação sexual, a paciente engravidou. A fertilização normalmente acontece\nno (a):","options":{"A":"infundíbulo da tuba uterina.","B":"útero.","C":"ovário","D":"ampola da tuba uterina.","E":"escavação retro uterina."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-22932","number":"22932","sourceNumber":"22932","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Na perimenopausa, a causa mais frequente de sangramento vaginal, entre as causas\nabaixo, é:","options":{"A":"cisto funcional","B":"tumor ovariano","C":"pólipo endometrial","D":"gravidez","E":"endometriose"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-22936","number":"22936","sourceNumber":"22936","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A histerectomia é mais comumente usada como tratamento de qual patologia benigna?","options":{"A":"leiomiomas","B":"endometriose","C":"adenomiose","D":"infecção crônica","E":"massa anexial"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-27722","number":"27722","sourceNumber":"27722","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 55 anos, há 5 anos sem menstruação e sem hormonioterapia, apresenta\nsangramento transvaginal durante 1 semana. Qual dos procedimentos abaixo é considerado\ndispensável para o diagnóstico etiológico?","options":{"A":"Ultrassonografia transvaginal","B":"Biópsia de endométrio","C":"Tomografia computadorizada de pelve","D":"Colpocitologia oncótica","E":"Exame físico ginecológico"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-27751","number":"27751","sourceNumber":"27751","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos, nuligesta, chega ao consultório com relato de dor pélvica crônica\ndesde os 25 anos. Refere ciclos menstruais de 25 dias de duração com 8 dias de sangramento de\nmoderada intensidade. Dismenorreia, náuseas e vômitos são frequentes durante a menstruação.\nExiste melhora dos sintomas com contraceptivos orais, mas a paciente relata parada do uso há 2\nanos. O exame físico da paciente é normal. O diagnóstico mais provável é:","options":{"A":"Adenomiose.","B":"Endometriose","C":"Varizes pélvicas","D":"DIP crônica","E":"Síndrome do intestino irritável"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-6918","number":"6918","sourceNumber":"6918","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Adolescente de 14 anos apresenta ciclo menstrual com intervalos regulares de 28 dias,\nporém com duração e fluxo excessivos. Qual o conceito deste quadro?","options":{"A":"Hipermenorreia.","B":"Polimenorreia.","C":"Menorragia.","D":"Metrorragia.","E":"Proiomenorreia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-6923","number":"6923","sourceNumber":"6923","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A histeroscopia está CONTRAINDICADA em qual das situações?","options":{"A":"Sangramento uterino.","B":"Hiperplasia endometrial.","C":"Restos ovulares.","D":"Doença inflamatória pélvica.","E":"Dispositivo intrauterino."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-6924","number":"6924","sourceNumber":"6924","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"MAM, 35 anos, apresenta discreta menorragia associada à dismenorreia. Realizou\nultrassom transvaginal que mostrou imagem\nhipoecogênica de contornos regulares no útero. Qual\nopção abaixo NÃO faz parte do arsenal terapêutico para esta patologia?","options":{"A":"Mifepristone.","B":"Histerectomia.","C":"Embolização Uterina.","D":"Exérese laparoscópica.","E":"17ß estradiol."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-9112","number":"9112","sourceNumber":"9112","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Lúcia (37 anos, G0P0A0) e Renato (36 anos) são casados há 10 anos e desde então\nvêm tentando ter um filho. O casal revela ter um desejo enorme em ter uma criança e grande\nfrustração pelas várias tentativas sem sucesso. Lúcia nega outras patologias e cirurgias prévias.\nCom relação à abordagem do casal infértil pelo médico de família, é INCORRETO afirmar que:","options":{"A":"Todos os casais inférteis devem se submeter a uma triagem inicial para doenças infecciosas,\nque inclui os seguintes exames: VDRL, anti-HCV,\nclamídia no soro e anti-HIV.","B":"A avaliação específica para infertilidade deve englobar causas femininas e/ou masculinas, sendo\nque a avaliação feminina engloba causas\nanatômicas e hormonais.","C":"A laparoscopia é considerada padrão ouro na avaliação do fator tubo-peritoneal.","D":"A investigação do fator hormonal inicia-se com a solicitação do TSH."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-6931","number":"6931","sourceNumber":"6931","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"ABS, 30 anos, apresentando dismenorreia progressiva, dispareunia profunda e\nalterações intestinais cíclicas. Ao toque vaginal,\nidentifica-se útero retrovertido e dor a mobilização\ndo útero. Ultrassom transvaginal sem alterações. Qual das opções terapêuticas NÃO deve ser\nutilizada?","options":{"A":"Anticoncepcionais orais combinados.","B":"Piroxicam.","C":"Acetato de goserelina.","D":"DIU com levornogestrel.","E":"Etinilestradiol."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13455","number":"13455","sourceNumber":"13455","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Na indicação da via vaginal para histerectomia deve-se considerar, EXCETO:","options":{"A":"Mobilidade uterina.","B":"História menstrual.","C":"Patologia anexial.","D":"História de endometriose.","E":"Cirurgia pélvica prévia."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13464","number":"13464","sourceNumber":"13464","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 40 anos com dismenorreia secundária há 6 meses, cesáreas prévias e\nprole definida, ciclos hipermenorrágicos, com\nexame clínico e ultras-sonográfico revelando aumento\nuterino difuso. A melhor conduta é:","options":{"A":"Ablação endometrial.","B":"Análogos de Gn-RH.","C":"Contraceptivo combinado injetável.","D":"Histerectomia.","E":"Contraceptivo oral combinado."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13468","number":"13468","sourceNumber":"13468","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente com 32 anos queixa--se de dismenorreia progressiva e infertilidade há 5 anos.\nVem com laudo de ultra-ssonografia que mostra massa anexial com ecos finos no seu interior. Qual\nsua suspeita clínica?","options":{"A":"Cisto simples de ovário.","B":"Hidrossalpinge.","C":"Cisto dermoide.","D":"Endometrioma.","E":"Corpo lúteo hemorrágico."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-7263","number":"7263","sourceNumber":"7263","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Marque o item correto com relação aos leiomiomas uterinos.","options":{"A":"É mais comum nas mulheres brancas.","B":"São assintomáticos em 90% dos casos.","C":"Ocorrem degenerações em dois terços.","D":"Na maioria dos casos são isolados.","E":"Não guardam relação com infertilidade."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-13469","number":"13469","sourceNumber":"13469","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em paciente com antecedente de um aborto de segundo trimestre, constata-se útero\nbicorno. Qual a melhor conduta a ser adotada?","options":{"A":"Metroplastia via abdominal.","B":"Correção histeroscópica.","C":"Tentar nova gravidez.","D":"Uso de progesterona durante nova gravidez.","E":"Histerosalpingografia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-9143","number":"9143","sourceNumber":"9143","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual destes marcadores é o melhor indicador da endometriose avançada?","options":{"A":"IgM anticardiolipina","B":"Ca 125","C":"Antígeno cárcino-embriônico","D":"Proteína amiloide-A"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-8903","number":"8903","sourceNumber":"8903","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A dosagem de FSH sérico, no 3º dia do ciclo menstrual, avalia a reserva:","options":{"A":"hipotalâmica","B":"hipofisária","C":"suprarrenal","D":"folicular ovariana","E":"eixo hipotálamo-hipofisário"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-8907","number":"8907","sourceNumber":"8907","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos apresenta menstruações irregulares e infertilidade. A biópsia do\nendométrio mostra hiperplasia complexa com atipia citológica mínima. O tratamento mais adequado\npara esta paciente é:","options":{"A":"observação","B":"indução da ovulação com GnRH","C":"tratamento cíclico com estrogênio","D":"tratamento contínuo com progestogênio","E":"histerectomia"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-8915","number":"8915","sourceNumber":"8915","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A histologia da adenomiose revela:","options":{"A":"modificação metaplásica do epitélio glandular em fibras musculares no útero","B":"o mesmo padrão e localização da endometriose","C":"a presença de glândulas endometriais e estroma na intimidade do músculo uterino","D":"uma alteração pré-maligna do endométrio","E":"uma alteração pré-maligna do músculo uterino"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-17880","number":"17880","sourceNumber":"17880","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A confirmação anatomopatológica de um diagnóstico de endometriose é feita através\nda identificação de implantes extragenitais\nmostrando:","options":{"A":"fibrose","B":"estroma decidualizado","C":"hipertrofia muscular","D":"glândulas endometriais e estroma","E":"hemorragia"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-16026","number":"16026","sourceNumber":"16026","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma menina de 13 anos apresenta-se com quadro de sangramento vaginal intenso,\ncom o início de seu primeiro período\nmenstrual (menarca). Dos diagnósticos abaixo relacionados, o\nMENOS provável é:","options":{"A":"sangramento disfuncional anovulatório.","B":"coagulopatia.","C":"gravidez.","D":"distúrbio da tireoide.","E":"pólipos endometriais."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-365569","number":"365569","sourceNumber":"365569","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 12 anos de idade, sem sexarca, com menarca há três meses,\napresenta sangramento volumoso, com saída de\ncoágulos e duração de 15 dias, sem repercussão\nhemodinâmica associada. Em relação ao sangramento uterino anormal, assinale a alternativa\ncorreta.","options":{"A":"A causa mais comum de sangramento uterino anormal na paciente jovem, logo após a menarca,\né a coagulopatia.","B":"A paciente precisa ser manejada com ultrassonografia transvaginal para investigação de causas\nanatômicas de sangramento uterino anormal.","C":"O uso de contraceptivos orais combinados deve ser a primeira opção para o caso descrito.","D":"O diagnóstico de síndrome dos ovários micropolicísticos pode ser realizado caso a paciente\napresente ciclos encurtados, com hipoandrogenismo associado."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-349721","number":"349721","sourceNumber":"349721","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 55 anos já não menstruava havia dois anos, entretanto, há cerca de um mês,\nvem apresentando sangramentos esporádicos de moderada intensidade, associados a cólicas.\n\nComo comorbidades, apresenta diabetes e hipertensão. Nega terapia hormonal. Ao exame\nginecológico, não apresenta alterações,\nexceto discreta atrofia da mucosa vaginal. No ultrassom\ntransvaginal observava-se endométrio de 9 mm. Diante desse caso, assinale a alternativa que\napresenta a melhor conduta.","options":{"A":"Prescrever lubrificante à base de água, visto que o sangramento é devido à atrofia.","B":"Realizar investigação com histeroscopia e biópsia dirigida.","C":"A provável causa do sangramento é um mioma submucoso. Indicar miomectomia.","D":"Indicar histerectomia total abdominal por hiperplasia endometrial com atipia.","E":"Prescrever noretisterona 0,35 mg por 12 meses e reavaliar em 1 ano."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-322190","number":"322190","sourceNumber":"322190","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 55 anos, com antecedente de menopausa aos 50 anos, refere que\nnunca usou terapia hormonal e faz tratamento\nde hipertensão e diabetes. Relata que, há cerca de\num mês, apresentou sangramento vaginal em dois momentos diferentes, durando\naproximadamente 2 dias cada episódio. Apresenta citopatológico com atrofia acentuada. Ultrassom\ntransvaginal evidencia a presença de dois miomas intramurais de 0,7 e 1,3 cm respectivamente;\nvolume uterino de 35 cm³; e endométrio de 11 mm. Ovários não foram visualizados. Diante desse\ncaso, qual é a melhor conduta?","options":{"A":"Histerectomia total abdominal mais anexectomia.","B":"Acetato de medroxiprogesterona trimestral.","C":"Iniciar estriol creme vaginal.","D":"Histeroscopia diagnóstica.","E":"Miomectomia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-305334","number":"305334","sourceNumber":"305334","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Referente ao Sangramento Uterino Anormal (SUA), analise as assertivas e assinale a\nalternativa correta. I. Segundo a FIGO (Federação Internacional de Ginecologia e Obstetrícia), o\nSUA pode ser classificado em causas estruturais. II. As causas não estruturais incluem:\nmalignidade, coagulopatias, ovulatória, endometrial e iatrogênicas. III. O sucesso do tratamento do\nSUA depende do diagnóstico etiológico. IV. Pequenos pólipos (< 0,5 cm) podem ser removidos\nambulatoriamente usando instrumentos mecânicos de 5-Fr (tesoura afiada e/ou pinças de agarrar).\nPólipos maiores (>0,5 cm) podem ser removidos em bloco (pela ressecção da base da lesão de\nimplantação com eletrodo monopolar ou bipolar) ou, alternativamente, seccionados em fragmentos.","options":{"A":"Nenhuma das assertivas são corretas.","B":"Todas as assertivas são corretas.","C":"Apenas a assertiva I é correta.","D":"Apenas três assertivas são corretas.","E":"Apenas as assertivas I, III e IV são corretas."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298911","number":"298911","sourceNumber":"298911","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos de idade, nuligesta, parou de usar anticoncepcional hormonal\nhá sete meses para tentar engravidar. Relata\naumento da dismenorreia no período, intensidade 8\nem 10, que inicia um dia antes e dura os cinco dias da menstruação, aliviada parcialmente com\nanalgésicos comuns, associada a dispareunia. Ao exame físico, tem dor à mobilização do colo\nuterino, com mobilidade do útero reduzida e espessamento bilateral de ligamentos uterossacros.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nEssa paciente é portadora de dor pélvica crônica,\nde provável causa ginecológica, e o diagnóstico\nmais previsível é de endometriose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298912","number":"298912","sourceNumber":"298912","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos de idade, nuligesta, parou de usar anticoncepcional hormonal\nhá sete meses para tentar engravidar. Relata\naumento da dismenorreia no período, intensidade 8\nem 10, que inicia um dia antes e dura os cinco dias da menstruação, aliviada parcialmente com\nanalgésicos comuns, associada a dispareunia. Ao exame físico, tem dor à mobilização do colo\nuterino, com mobilidade do útero reduzida e espessamento bilateral de ligamentos uterossacros.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. A\nendometriose é uma doença inflamatória benigna, crônica, progesteronadependente, que acomete\nmulheres em idade reprodutiva.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-305344","number":"305344","sourceNumber":"305344","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"M.R.F., feminino, 27 anos, apresenta queixa de sangramento menstrual volumoso,\ndurante período menstrual, e dismenorreia. Ao\nexame físico, apresenta útero aumentado\ndifusamente e doloroso à palpação. Foi realizada uma ultrassonografia transvaginal, que\nevidenciou um miométrio heterogêneo e ecoendometrial mal definido. Com base nos achados\nclínicos e ultrassonográficos, assinale a principal hipótese diagnóstica.","options":{"A":"Endometriose.","B":"Câncer de endométrio.","C":"Leiomioma.","D":"Adenomiose.","E":"Pólipo endometrial."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298913","number":"298913","sourceNumber":"298913","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos de idade, nuligesta, parou de usar anticoncepcional hormonal\nhá sete meses para tentar engravidar. Relata\naumento da dismenorreia no período, intensidade 8\nem 10, que inicia um dia antes e dura os cinco dias da menstruação, aliviada parcialmente com\nanalgésicos comuns, associada a dispareunia. Ao exame físico, tem dor à mobilização do colo\nuterino, com mobilidade do útero reduzida e espessamento bilateral de ligamentos uterossacros.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. Os\nprincipais sintomas da endometriose são dismenorreia, dispareunia e dor pélvica crônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298914","number":"298914","sourceNumber":"298914","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos de idade, nuligesta, parou de usar anticoncepcional hormonal\nhá sete meses para tentar engravidar. Relata\naumento da dismenorreia no período, intensidade 8\nem 10, que inicia um dia antes e dura os cinco dias da menstruação, aliviada parcialmente com\nanalgésicos comuns, associada a dispareunia. Ao exame físico, tem dor à mobilização do colo\nuterino, com mobilidade do útero reduzida e espessamento bilateral de ligamentos uterossacros.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O\nexame de escolha para o diagnóstico adequado é a tomografia computadorizada com contraste\nendovenoso, que guiará o tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298915","number":"298915","sourceNumber":"298915","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos de idade, nuligesta, parou de usar anticoncepcional hormonal\nhá sete meses para tentar engravidar. Relata\naumento da dismenorreia no período, intensidade 8\nem 10, que inicia um dia antes e dura os cinco dias da menstruação, aliviada parcialmente com\nanalgésicos comuns, associada a dispareunia. Ao exame físico, tem dor à mobilização do colo\nuterino, com mobilidade do útero reduzida e espessamento bilateral de ligamentos uterossacros.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. Os\nsítios anatômicos em que a endometriose pode se desenvolver restringem-se à pelve.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298916","number":"298916","sourceNumber":"298916","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos de idade, nuligesta, parou de usar anticoncepcional hormonal\nhá sete meses para tentar engravidar. Relata\naumento da dismenorreia no período, intensidade 8\nem 10, que inicia um dia antes e dura os cinco dias da menstruação, aliviada parcialmente com\nanalgésicos comuns, associada a dispareunia. Ao exame físico, tem dor à mobilização do colo\nuterino, com mobilidade do útero reduzida e espessamento bilateral de ligamentos uterossacros.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O\ntratamento medicamentoso é feito com uso de analgésicos e anti-inflamatórios para dor, bem como\ncom anticoncepcionais hormonais combinados ou de progesterona isolada para o controle do ciclo\nmenstrual.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-298917","number":"298917","sourceNumber":"298917","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos de idade, nuligesta, parou de usar anticoncepcional hormonal\nhá sete meses para tentar engravidar. Relata\naumento da dismenorreia no período, intensidade 8\nem 10, que inicia um dia antes e dura os cinco dias da menstruação, aliviada parcialmente com\nanalgésicos comuns, associada a dispareunia. Ao exame físico, tem dor à mobilização do colo\nuterino, com mobilidade do útero reduzida e espessamento bilateral de ligamentos uterossacros.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nComo a paciente está tentando gestar há\nmenos de um ano, não há indicação de prosseguir com a\ninvestigação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-274411","number":"274411","sourceNumber":"274411","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A endometriose frequentemente compromete a qualidade de vida da paciente. São\ncomuns os atrasos no diagnóstico devido a\ndiversas possibilidades de patologias com o mesmo\nsintoma. Em relação a essa patologia, assinale a alternativa correta.","options":{"A":"A ressonância magnética de pelve é considerada padrão-ouro de diagnóstico.","B":"Há correlação entre a quantidade de focos e a dor da paciente.","C":"O marcador CA-125 elevado indica a gravidade do caso.","D":"O tratamento pode ser realizado promovendo a amenorreia da paciente.","E":"É indicação absoluta para cirurgia a presença de endometrioma."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-274412","number":"274412","sourceNumber":"274412","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 33 anos, nuligesta, relata, durante a consulta de rotina ginecológica, ciclos\nmenstruais regulares, fluxo dentro do padrão normal, sem queixas álgicas. Apresenta um ultrassom\nendovaginal com mioma uterino subseroso de 1 cm. A proposta terapêutica nesse caso clínico é","options":{"A":"tratamento com progesterona isolada.","B":"tratamento com anticoncepcional hormonal combinado oral.","C":"indicação de miomectomia para estudo histopatológico.","D":"indicação de histerectomia devido ao risco de degeneração maligna.","E":"conduta expectante."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-261291","number":"261291","sourceNumber":"261291","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma adolescente de 12 anos de idade sofre uma queda ao andar de bicicleta, colidindo\na região genital contra o quadro central. A\npaciente é levada pela mãe a uma emergência pediátrica\npara avaliação, em razão de edema vulvar. Ao chegar, a paciente refere dor pélvica importante. É\navaliada por um cirurgião pediátrico que identifica hematoma em grandes lábios, estável desde o\nacidente, segundo a mãe, associado a edema de pequenos e grandes lábios. Quanto ao caso\nclínico apresentado e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir.\nLesões traumáticas da vulva e da vagina são comuns.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-261292","number":"261292","sourceNumber":"261292","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma adolescente de 12 anos de idade sofre uma queda ao andar de bicicleta, colidindo\na região genital contra o quadro central. A\npaciente é levada pela mãe a uma emergência pediátrica\npara avaliação, em razão de edema vulvar. Ao chegar, a paciente refere dor pélvica importante. É\navaliada por um cirurgião pediátrico que identifica hematoma em grandes lábios, estável desde o\nacidente, segundo a mãe, associado a edema de pequenos e grandes lábios. Quanto ao caso\nclínico apresentado e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir.\nA minoria dos hematomas vulvares é tratada de maneira conservadora, com compressas frias e\ncontrole da dor, pois, em razão da natureza arterial da maioria deles, é necessário abordagem\ncirúrgica para ligar os vasos sangrantes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-152111","number":"152111","sourceNumber":"152111","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 57 anos de idade, G1P1, menarca aos 14 anos, menopausa aos 52, viúva,\nnega coito. Apresenta sangramento vaginal, iniciado há três meses. Nega patologias prévias,\nalergias, tabagismo e uso de TRH. Considerando esse caso clínico, julgue o item a seguir. A causa\nmais frequente de sangramento na pós-menopausa é o câncer endometrial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-152121","number":"152121","sourceNumber":"152121","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 57 anos de idade, G1P1, menarca aos 14 anos, menopausa aos 52, viúva,\nnega coito. Apresenta sangramento vaginal, iniciado há três meses. Nega patologias prévias,\nalergias, tabagismo e uso de TRH. Considerando esse caso clínico, julgue o item a seguir. A causa\nmais frequente desse sangramento é a atrofia endometrial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-152141","number":"152141","sourceNumber":"152141","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 57 anos de idade, G1P1, menarca aos 14 anos, menopausa aos 52, viúva,\nnega coito. Apresenta sangramento vaginal, iniciado há três meses. Nega patologias prévias,\nalergias, tabagismo e uso de TRH. Considerando esse caso clínico, julgue o item a seguir. A\nhisterectomia total com anexectomia bilateral deve ser realizada, pois a paciente já está na\nmenopausa e a causa, provavelmente, é a etiologia maligna.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-152067","number":"152067","sourceNumber":"152067","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 40 anos de idade, G2C2, casada, ciclos menstruais regulares, MAC\nlaqueadura tubária em 2014. Aflita, consulta o\nmédico generalista, trazendo ecografia transvaginal,\nna qual se evidenciou imagem nodular de 2,3 cm x 2,5 cm, sugestiva de leiomioma subseroso.\n\nApresenta endométrio homogêneo de 0,5 cm e ovários sem particularidades. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir:\n\ndeve-se tranquilizar a paciente, pois a maioria dos leiomiomas são assintomáticos e tendem a\nregredir na pós-menopausa, visto que são estrógenos dependentes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-152071","number":"152071","sourceNumber":"152071","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 40 anos de idade, G2C2, casada, ciclos menstruais regulares, MAC\nlaqueadura tubária em 2014. Aflita, consulta o\nmédico generalista, trazendo ecografia transvaginal,\nna qual se evidenciou imagem nodular de 2,3 cm x 2,5 cm, sugestiva de leiomioma subseroso.\n\nApresenta endométrio homogêneo de 0,5 cm e ovários sem particularidades. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir: é\npreciso encaminhar a paciente, com urgência, ao ginecologista para realizar histerectomia, pois\ntrata-se de uma patologia com alto índice de malignidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-152079","number":"152079","sourceNumber":"152079","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 40 anos de idade, G2C2, casada, ciclos menstruais regulares, MAC\nlaqueadura tubária em 2014. Aflita, consulta o\nmédico generalista, trazendo ecografia transvaginal,\nna qual se evidenciou imagem nodular de 2,3 cm x 2,5 cm, sugestiva de leiomioma subseroso.\n\nApresenta endométrio homogêneo de 0,5 cm e ovários sem particularidades. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir.\n\nDeve-se orientar a paciente que o crescimento rápido, especialmente na pós-menopausa, tem\nindicação cirúrgica mesmo nos assintomáticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-152084","number":"152084","sourceNumber":"152084","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 40 anos de idade, G2C2, casada, ciclos menstruais regulares, MAC\nlaqueadura tubária em 2014. Aflita, consulta o\nmédico generalista, trazendo ecografia transvaginal,\nna qual se evidenciou imagem nodular de 2,3 cm x 2,5 cm, sugestiva de leiomioma subseroso.\n\nApresenta endométrio homogêneo de 0,5 cm e ovários sem particularidades. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir.\n\nDeve-se informar a paciente que ela pode apresentar menometrorragia em razão da localização do\nmioma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-105550","number":"105550","sourceNumber":"105550","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O conhecimento da anatomia da pelve feminina é de fundamental importância para\nabordagem cirúrgica em Ginecologia e\nObstetrícia. Acerca desse tema, sabe-se que a artéria\nuterina responsável pela maior parte da irrigação do útero corresponde ao terceiro ramo anterior da\nartéria","options":{"A":"ilíaca interna.","B":"ilíaca comum.","C":"aorta.","D":"ovariana.","E":"pudenda."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-108129","number":"108129","sourceNumber":"108129","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Julgue o item a seguir, relativo à bioética. Conforme resolução do Conselho Federal de\nMedicina, o casal tem autonomia para escolher o sexo da prole, desde que a decisão esteja\nregistrada em um termo de consentimento informado, com firma reconhecida em cartório.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-79654","number":"79654","sourceNumber":"79654","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Um casal, em planejamento familiar, apresenta um espermograma morfológico de\nKrüger com os seguintes resultados: Motilidade A+B inferior a 50%. Morfologia: 2%. No exame\ncitado, os critérios motilidade A e B significam:","options":{"A":"motilidade não progressiva e lenta.","B":"ausência de motilidade.","C":"motilidade progressiva linear baixa.","D":"motilidade progressiva linear rápida e lenta.","E":"motilidade progressiva lenta e imotilidade."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-79661","number":"79661","sourceNumber":"79661","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A.S.S., 18 anos, relaciona-se com múltiplos parceiros. Apresenta febre, dor e\ndesconforto pélvico, leucopenia e secreção purulenta. Essa situação condiz com doença\ninflamatória pélvica, devendo ser realizado diagnóstico diferencial de:","options":{"A":"endometriose.","B":"câncer ovariano.","C":"câncer de colo.","D":"cisto paratubário.","E":"leiomiomatose."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-27552","number":"27552","sourceNumber":"27552","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 60 anos, com queixa de sangramento vaginal. Não faz terapêutica de\nreposição hormonal. Como causa mais frequente deste quadro, podemos apontar:","options":{"A":"câncer de endométrio.","B":"pólipo endometrial.","C":"atrofia do endométrio.","D":"endométrio hiperplásico","E":"hiperplasia ovariana."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-334899","number":"334899","sourceNumber":"334899","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Os miomas são tumores benignos uterinos, considerados uma das patologias mais\nprevalentes em mulheres na idade fértil. No que tange aos miomas, assinale a alternativa correta.","options":{"A":"O mioma pode se degenerar, aumentando o risco de leiomiosarcoma, sendo quadro bastante\nfrequente, e deve ser tratado de forma cirúrgica na sua quase totalidade dos casos.","B":"O quadro clínico mais comum associado ao mioma é o sangramento uterino anormal, e a\nlocalização mais relacionada ao sangramento é a submucosa.","C":"Os miomas pediculados subserosos podem se apresentar como massas abdominais volumosas,\nfrequentemente levando à obstrução intestinal, e devem ser ressecados sempre que possível.","D":"A embolização dos miomas consiste em um tratamento minimamente invasivo, com boa\naplicação nas pacientes com múltiplos miomas e desejo de gravidez posterior.","E":"A histerectomia deve ser sempre encorajada nas pacientes com prole constituída, associada à\nmiomatose uterina, mesmo nas pacientes pós-menopausa pelo risco de transformação maligna nas\nidades mais avançadas."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-343449","number":"343449","sourceNumber":"343449","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A Endometriose é uma doença ginecológica caracterizada pelo desenvolvimento e\ncrescimento de estroma e glândulas endometriais fora da cavidade uterina, resultando em uma\nreação inflamatória crônica. Com relação à endometriose, é INCORRETO afirmar:","options":{"A":"A videolaparoscopia pode ser indicada para avaliação da paciente com suspeita de\nEndometriose.","B":"Sintomas intestinais, incluindo aceleração ou diminuição do trânsito, dor à evacuação, tenesmo\ne/ou sangramento nas fezes, assim como os\nurinários que incluem hematúria são acíclicos, na\nmaioria das vezes, contínuos.","C":"O uso dos progestagênios de forma contínua resulta em bloqueio ovulatório e inibição do\ncrescimento endometrial, com consequente atrofia das lesões.","D":"O tratamento medicamentoso hormonal para supressão ovariana em pacientes com infertilidade\ne endometriose para melhora da fertilidade não deve\nser prescrito, pois não existe evidencia\ncientífica de qualquer benefício."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-307117","number":"307117","sourceNumber":"307117","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Os leiomiomas são tumores benignos compostos por fibras musculares lisas do útero,\nassociados a estroma de tecido conjuntivo, constituindo causa estrutural frequente de sangramento\nuterino anormal (SUA). A respeito do tratamento dos leiomiomas, assinale a alternativa correta.\n\nAlternativas:","options":{"A":"Leiomiomas assintomáticos podem ser submetidos à conduta expectante.","B":"Crescimento acelerado de leiomioma uterino pode consistir em degeneração sarcomatosa,\ncondição que não é indicação de tratamento\ncirúrgico.","C":"Pacientes sintomáticas que desejam preservar o útero e que apresentem leiomiomas\npediculados, pequenos, múltiplos e com degeneração são\ncandidatas à embolização da artéria\nuterina.","D":"Histerectomia está indicada para pacientes com leiomiomas de tamanho pequeno na\nmenopausa ou perimenopausa, haja vista a\nausência de perspectiva reprodutiva nesse contexto.","E":"Pacientes com baixo risco cirúrgico são candidatas ao tratamento clínico dos leiomiomas\nuterinos."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-263347","number":"263347","sourceNumber":"263347","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma adolescente com 14 anos de idade, acompanhada de sua prima de 18 anos de\nidade, é atendida pelo médico de plantão no hospital, queixando-se de sangramento vaginal\nabundante há 5 dias. A paciente nega contato sexual prévio ou doenças pregressas e relata\nmenstruações mensais regulares desde os 10 anos de idade. O exame ginecológico revela rotura\nhimenal cicatrizada e pequeno sangramento vaginal no momento do exame. Nessa situação, para\ndiferenciar as causas de sangramento, o exame complementar inicial importante é","options":{"A":"FSH sérico.","B":"beta hCG sérico.","C":"progesterona sérica.","D":"fator de Von Willebrand."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-273325","number":"273325","sourceNumber":"273325","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 47 anos, sem desejo de gestar, com sangramento persistente (9 dias de\nduração), volumoso (troca de 6 absorventes\nnoturnos/dia), com saída de coágulos maiores que 2\ncm há 3 meses, com anemia (Hb : 6 g/dl), foi ao ginecologista devido quadro de sangramento onde\nrealizou uma ultrassonografia transvaginal que evidenciou múltiplos miomas, os maiores com 4 cm\nintramural (figo 4) e mioma submucoso de 2 cm (figo 1) e volume uterino estimado de 410 cm³ ,\ncomo tratamento proposto podemos citar:","options":{"A":"Histerectomia Total","B":"Histeroscopia Cirúrgica","C":"AINES + Antifibrinolitico","D":"SIU-LNG"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-291483","number":"291483","sourceNumber":"291483","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 51 anos, de menopausa há 3 anos, com queixa de sangramento uterino\nrecorrente, em pequena quantidade, há 3 meses.\nNa maioria das vezes, os episódios de\nsangramento iniciam durante ou após as relações sexuais. A paciente é diabética e faz uso de\ninsulina. Traz dois resultados normais de exames citopatológicos do colo uterino realizados nos\núltimos 2 anos, sendo o último há 9 meses. Exame físico: estado geral bom, hemodinamicamente\nestável, normocorada. Ao exame especular, visualiza-se lesão de aspecto polipoide de\naproximadamente 2 cm se exteriorizando pelo orifício externo do colo uterino, não sendo possível\nvisualizar a lesão em toda sua extensão. A conduta indicada é","options":{"A":"solicitar histeroscopia diagnóstica.","B":"realizar exérese imediata da lesão com pinça.","C":"realizar eletrocauterização da lesão.","D":"iniciar tratamento com solução de ácido tricloroacético."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-263368","number":"263368","sourceNumber":"263368","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma adolescente com 17 anos de idade comparece à consulta na Unidade Básica de\nSaúde com queixa de dor incapacitante\nrelacionada ao sangramento menstrual. Refere que o\nproblema se iniciou há 2 anos, tendo-se agravado os sintomas com o tempo. Relata que a menarca\nocorreu aos 11 anos, que é nulípara e que iniciou vida sexual há 1 ano. Ela apresenta dispareunia,\nestá sem comorbidades e deseja orientação quanto a método contraceptivo. Diante do quadro\nclínico apresentado, quais são, respectivamente, a hipótese diagnóstica, o exame complementar a\nser solicitado e o método contraceptivo indicado?","options":{"A":"Congestão pélvica; ultrassonografia transvaginal com Doppler; e DIU hormonal.","B":"Dismenorreia primária; nenhum exame complementar; e hormonal contínuo.","C":"Endometriose; ultrassonografia transvaginal; e hormonal contínuo.","D":"Endometrite; histeroscopia diagnóstica; e método de barreira."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-268920","number":"268920","sourceNumber":"268920","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 45 anos de idade, G2P2C2A0, DUM há 15 dias, no momento ainda\ncom sangramento, e história de HAS, em uso de\nlosartana 100 mg/dia, sem outras comorbidades\ndiagnosticadas, compareceu à consulta com ginecologista com queixa de sangramento uterino\nanormal, referindo período menstrual com fluxo intenso e duração aumentada, chegando a durar 10\ndias a 15 dias, bem como irregularidade do sangramento, apresentando períodos de até dois\nmeses sem menstruação, seguidos de meses com dois ou mais episódios de sangramento. Negou\nuso de contraceptivos ou qualquer medicação hormonal. Com base nesse caso clínico e nos temas\ncorrelatos, assinale a alternativa correta.","options":{"A":"Caso a paciente apresente a última colpocitologia oncótica sem alterações, o exame especular\npode ser dispensado na vigência de\nsangramento vaginal.","B":"São exames complementares importantes na avaliação inicial desse caso: hemograma\ncompleto, coagulograma e ultrassonografia transvaginal,\nsendo o beta-HCG desnecessário em\nvirtude da idade da paciente.","C":"A hipótese de sangramento uterino disfuncional da perimenopausa é diagnóstico de exclusão, e\nsomente poderá ser confirmada após descartadas demais causas estruturais e não estruturais de\nsangramento uterino anormal pela propedêutica complementar laboratorial e de imagem.","D":"São causas estruturais de sangramento uterino anormal: pólipos, adenomiose, coagulopatias,\nleiomiomas e neoplasias malignas.","E":"Na paciente desse caso clínico, imagem endometrial à ultrassonografia transvaginal com medida\n\n> 4,0 mm corresponde a espessamento endometrial e implica indicação de histeroscopia cirúrgica\ncom urgência pelo risco de carcinoma\nendometrial. Essa paciente não está menopausada, então\nnão há critério de espessamento endometrial nesse caso."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-291508","number":"291508","sourceNumber":"291508","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 28 anos de idade, com ciclos menstruais regulares, procura\natendimento na assistência básica por causa\nde infertilidade, pois está tentando engravidar há 2\nanos sem sucesso. Queixa-se de dismenorreia secundária de intensidade moderada, com início há\n3 anos, e piora progressiva nos últimos 6 meses. Gesta 1; para 0; Aborto 1 (provocado aos 15\nanos). Ao exame físico, o colo uterino tinha aspecto normal, o útero era doloroso à mobilização,\ncom um nódulo endurecido na região retrocervical e uma massa em região anexial direita de 5 cm.\nConsiderando o quadro clínico, antes de encaminhar a um serviço especializado, o(a) médico(a)\ndeve solicitar primeiramente","options":{"A":"histeroscopia.","B":"ultrassonografia transvaginal/pélvica.","C":"exames hormonais (FSH, LH, prolactina e TSH).","D":"histerossalpingografia."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-274653","number":"274653","sourceNumber":"274653","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Considerar infertilidade de mulher, 32 anos, com ovulação regular, e apresentando\nHSG normal, tendo sido submetida à crioterapia do\ncolo uterino; seu marido tem 36 anos e a\nanálise do sêmen dele é normal. Nesse caso deve ser considerado o fator:","options":{"A":"Ovulatório.","B":"Uterino.","C":"Cervical.","D":"Masculino."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-263415","number":"263415","sourceNumber":"263415","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher com 52 anos de idade apresenta queixa de sangramento uterino anormal\ncom aumento do fluxo e diminuição do intervalo entre os sangramentos há 3 meses. A paciente\npossui histórico de 2 partos e laqueadura tubária há 18 anos. Nega comorbidades. Seus exames\nclínicos e ginecológicos estão sem anormalidades. A ultrassonografia transvaginal visualizou\nespessamento focal endometrial com fluxo ao doppler. Nesse caso, a principal conduta médica a\nser realizada é","options":{"A":"solicitar histeroscopia com biópsia.","B":"indicar histerectomia total.","C":"fazer ecografias periódicas.","D":"prescrever progesterona."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-244488","number":"244488","sourceNumber":"244488","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 58 anos de idade, com história de menopausa aos 50 anos, procurou\natendimento com queixa de quatro episódios de sangramento vaginal nos últimos 12 meses. Foi\nsolicitada ecografia transvaginal que evidenciou endométrio de 14 mm. Nesse caso clínico, a\nconduta padrão-ouro é","options":{"A":"iniciar terapia de reposição hormonal com progesterona e aguardar descamação endometrial.","B":"repetir ecografia transvaginal em seis meses.","C":"fazer curetagem uterina.","D":"realizar histeroscopia com biópsia endometrial.","E":"proceder a colposcopia com biópsia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-227433","number":"227433","sourceNumber":"227433","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Com relação a patologias ginecológicas benignas, julgue o próximo item. Na maioria\ndas pacientes com endometriose, a lise de\naderências por via laparoscópica está associada à\nmelhora da dor pélvica crônica, pois reduz os focos de atividade inflamatória, com consequente\ndiminuição da liberação de prostaglandinas pelas lesões.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-227435","number":"227435","sourceNumber":"227435","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Com relação a patologias ginecológicas benignas, julgue o próximo item. Mulher\nmultípara que tenha sido submetida a curetagens uterinas pós-aborto apresenta maior risco de\nadenomiose em comparação a uma mulher nulípara da mesma idade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-206110","number":"206110","sourceNumber":"206110","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em adolescente de 13 anos com sangramento menstrual irregular, indique a alternativa\nINCORRETA:","options":{"A":"Não deve ser utilizado estrogênio, pelo risco de comprometer o crescimento.","B":"A causa mais frequente é anovulação.","C":"Não necessita tratamento na maioria das vezes.","D":"Pode ser utilizado anticoncepcional combinado oral."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-206109","number":"206109","sourceNumber":"206109","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação a um casal com três abortamentos consecutivos, assinale a alternativa\nINCORRETA:","options":{"A":"Histerossalpingografia pode ser utilizada para excluir alterações estruturais das trompas que\nprovocam o aborto.","B":"No primeiro trimestre as causa mais comuns são as cromossômicas.","C":"Existe forte relação entre fator anticoagulante lúpico e abortamento de repetição.","D":"As causa estruturais ou ambientais geralmente respondem pelas perdas no segundo trimestre."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-177268","number":"177268","sourceNumber":"177268","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos de idade, do sexo feminino, comparece a um consultório com\nqueixa de dismenorreia desde a\nadolescência, de caráter progressivo. Refere também dispareunia\nfrequente. Atualmente, ela necessita de analgesia venosa cerca de uma vez por mês, para o\ncontrole da dor. Nuligesta, a paciente está tentando engravidar há 2 anos. Ao exame especular, o\ncolo da paciente não apresenta lesões e a secreção possui aspecto fisiológico. O toque vaginal\nrevela nodulações dolorosas na região retrocervical. A respeito das possibilidades terapêuticas para\na paciente do mencionado caso clínico, assinale a alternativa correta.","options":{"A":"O tratammento clínico da endometriose envolve o controle dos sintomas por intermédio do\nbloqueio hormonal do ovário, pela supressão do\nestímulo hormonal sobre os focos endometrióticos.\nPortanto, para melhorar as chances de gravidez, é importante diminuir a atividade inflamatória da\nendometriose, mantendo a paciente em uso de anticoncepcional contínuo por 2 anos para que só\ndepois ela tente gestar espontaneamente.","B":"Caso a paciente seja submetida à laparoscopia e no procedimento seja evidenciado\nendometrioma ovariano, o objetivo terapêutico deve\nser ooferectomia, para evitar recidiva e\nprogressão da endometriose.","C":"Se houvesse associação com adenomiose, o tratamento de primeira escolha seria histerectomia,\nque é preconizada inclusive para pacientes\nnuligestas, por se tratar da forma mais efetiva de\ncontrole dos sintomas.","D":"Embora o objetivo cirúrgico seja a ressecção do máximo de focos endometrióticos,\nendometriomas devem ser retirados com cautela,\npara a preservação do tecido ovariano sadio, com\na finalidade de não prejudicar o potencial reprodutivo da paciente.","E":"O uso de análogos de GnRH, de anticoncepcionais orais de uso contínuo e de estrogênio\nisolado bioidêntico é uma possibilidade para o\ntratamento clínico"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-177274","number":"177274","sourceNumber":"177274","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 32 anos de idade, do sexo feminino, comparece a um consultório com\nqueixa de dismenorreia desde a\nadolescência, de caráter progressivo. Refere também dispareunia\nfrequente. Atualmente, ela necessita de analgesia venosa cerca de uma vez por mês, para o\ncontrole da dor. Nuligesta, a paciente está tentando engravidar há 2 anos. Ao exame especular, o\ncolo da paciente não apresenta lesões e a secreção possui aspecto fisiológico. O toque vaginal\nrevela nodulações dolorosas na região retrocervical. Em relação ao caso clínico mencionado,\nassinale a alternativa correta.","options":{"A":"O CA 125 deve ser solicitado, já que, por ser altamente específico para endometriose, faz parte\ndos critérios para diagnóstico dessa doença.","B":"Por se tratar de quadro de endometriose cursando com infertilidade, é mandatória a realização\nde videolaparoscopia para estadiamento da doença e\nexérese dos focos endometrióticos.","C":"As nodulações na região retrocervical levantam a hipótese de endometriose profunda. Os\nmétodos atualmente mais indicados para tal\navaliação são a ressonância magnética de pelve com\ncontraste e o ultrassom transvaginal com preparo intestinal.","D":"A ausência de sintomas intestinais na história clínica da mencionada paciente torna\ndesnecessária a investigação de endometriose profunda.","E":"O fato de que a paciente não apresenta alteração de hábito intestinal no período menstrual não\ndescarta a necessidade de realização de colonoscopia para avaliar-se a presença de focos\nintestinais de endometriose."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-175150","number":"175150","sourceNumber":"175150","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente com Mioma Uterino, candidata à Miomectomia Abdominal, não haveria\nindicação desta técnica cirúrgica no seguinte caso:","options":{"A":"Dor pélvica.","B":"Mioma parido.","C":"Sangramento uterino.","D":"Abortamentos recorrentes."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-175165","number":"175165","sourceNumber":"175165","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 56 anos, usuária de Terapia de Reposição Hormonal, portadora de\nmiomatose uterina assintomática, em\nultrassonografia de controle, observou aumento rápido de um\nmioma. Baseado nesse quadro deve-se pensar em degeneração do tipo:","options":{"A":"Sarcomatosa.","B":"Hialina.","C":"Cálcica.","D":"Necrótica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-175151","number":"175151","sourceNumber":"175151","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A droga que, quando utilizada isoladamente, pode piorar os sintomas de endometriose\né:","options":{"A":"Progesterona.","B":"Noretisterona.","C":"Estradiol.","D":"Nomegestrol."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-175157","number":"175157","sourceNumber":"175157","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Assinale a alternativa correta:","options":{"A":"Metrorragia é o sangramento vaginal irregular, não relacionado ao período menstrual habitual da\npaciente.","B":"Dismenorréia primária é aquela que acontece somente em mulheres que não iniciaram atividade\nsexual.","C":"A expressão dos mamilos no exame clínico ginecológico, quando demonstra presença de\nsecreções, não tem importância clínica.","D":"Retocele é o prolapso da parede retal sobre a parede vaginal anterior."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-175139","number":"175139","sourceNumber":"175139","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 45 anos, gesta 2 para 2 (cesáreas), submetida a laqueadura tubária no\nsegundo parto, apresentando dismenorreia\nsecundária e aumento do fluxo menstrual (menorragia).\nAo toque, observa-se útero difusamente aumentado, com boa mobilidade, sem dor à mobilização.\nAo ultrassom endovaginal evidencia-se útero aumentado (198 cm3) e 1 nódulo de 9x9 mm\nsubseroso, fúndico que pode corresponder a mioma. A mais provável causa dos sintomas referidos\né:","options":{"A":"Adenomiose","B":"O mioma referido no ultrassom.","C":"Endometriose.","D":"Pelviperitonite."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-154496","number":"154496","sourceNumber":"154496","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 33 anos procura pronto-socorro devido a sangramento transvaginal intenso.\nRefere-se ter feito Iaqueadura tubária e que a última menstruação veio há 17 dias. Ao exame físico:\npressão arterial de 97 x 62 mmHg, frequência cardíaca de 110 bpm, mucosas hipocoradas e\ntemperatura axilar de 36,5º. Ao exame especular: vários coágulos intravaginais, ausência de lesões\nem vagina e colo uterino. Toque vaginal e ultrassonografia transvaginal sem alterações. O\ndiagnóstico mais provável é:","options":{"A":"Câncer de endométrio.","B":"Gravidez ectópica.","C":"Adenomiose.","D":"Sangramento uterino disfuncional.","E":"Endometriose."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-154499","number":"154499","sourceNumber":"154499","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 27 anos, nulípara, hipertensa, relata aumento do sangramento menstrual e\ndiz tentar engravidar há 8 meses, sem sucesso. Em exame ecográfico endovaginal foi detectado\nleiomioma submucoso pediculado medindo 18 mm. A conduta mais adequada é:","options":{"A":"Miomectomia histeroscópica.","B":"Miomectomia laparotômica.","C":"Conduta expectante.","D":"Anticoncepcional combinado oral.","E":"Miomectomia videolaparoscópica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-168432","number":"168432","sourceNumber":"168432","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher com 58 anos de idade, menopausa há 5 anos, obesa e nuligesta, sem\nnunca ter feito uso de terapia hormonal,\ncomparece a consulta em Unidade Básica de Saúde\nqueixando-se de sangramento vaginal de pequena intensidade há 4 meses. Ao exame especular\nobserva-se: mucosa vaginal de aparência trófica e colo uterino sem lesões aparentes. Traz\nresultado de ultrassonografia transvaginal recente, demonstrando espessura endometrial de 10 mm\ne a presença de 3 miomas, sendo um intramural com 4 cm e dois subserosos com 1 e 2 cm,\nrespectivamente. O presente quadro clínico indica a necessidade de","options":{"A":"histerectomia com anexectomia.","B":"embolização de artérias uterinas.","C":"miomectomia por via laparoscópica.","D":"histeroscopia com biópsia endometrial."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-104743","number":"104743","sourceNumber":"104743","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O conhecimento de anatomia é de fundamental importância na realização de\nprocedimentos cirúrgicos, no planejamento de\ntécnicas e no manejo de complicações operatórias. A\nestrutura anatômica que cruza a artéria ilíaca comum anteriormente próxima ao local de sua\nbifurcação, para, então, descer paralela e mediamente à artéria ilíaca interna até seu terceiro ramo\n(artéria uterina), passando atrás desta, até seu local de inserção, é denominada:","options":{"A":"artéria ovariana.","B":"ligamento cardinal.","C":"ureter.","D":"veia uterina.","E":"nervo obturatório."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-111322","number":"111322","sourceNumber":"111322","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, nuligesta, sem métodos contraceptivos há cerca de três anos,\napresenta queixa de dismenorreia intensa e também dor pélvica cíclica intermenstrual. No exame\nvaginal foi observado nódulo violáceo em fundo de saco, doloroso à mobilização. O diagnóstico\nmais provável é:","options":{"A":"Adenomiose.","B":"Hiperplasia endometrial.","C":"Miomatose uterina.","D":"Endometriose.","E":"Carcinoma endometrial."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-97825","number":"97825","sourceNumber":"97825","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente com 52 anos de idade, cuja menopausa ocorreu aos 48 anos, procura\nUnidade Básica de Saúde com queixa de\nsangramento genital de pequena quantidade, esporádico\ne intermitente, nos últimos dois meses. Não faz uso de terapia hormonal. É obesa, sem outras\ncomorbidades. Ao exame apresenta: vagina e colo uterino atróficos, sem lesões visíveis. Foi\nsubmetida à mamografia e exame citopatológico do colo uterino há seis meses, com resultados\nsatisfatórios e normais. A conduta imediata indicada para essa paciente é:","options":{"A":"solicitar ultrassonografia transvaginal.","B":"repetir exame citopatológico do colo uterino.","C":"encaminhar para consulta com especialista.","D":"prescrever terapia hormonal com a associação estradiol-progestagênio."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-75462","number":"75462","sourceNumber":"75462","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal procura atendimento médico em Unidade Básica de Saúde com história de\ntentativas frustradas de engravidar há dois anos,\na despeito de manter relações sexuais frequentes\ne sem uso de métodos contraceptivos. Ela tem 25 anos de idade, apresenta ciclos menstruais\nregulares e nega dismenorreia, dispareunia, comorbidades ou antecedente de doenças\nsexualmente transmissíveis. Ele tem 30 anos de idade, sem antecedentes relevantes, com filho de\ncinco anos de idade de outro relacionamento. Considerando a propedêutica indicada na abordagem\ninicial do casal infértil, devem ser solicitados:","options":{"A":"Espermograma e histerossalpingografia.","B":"Ultrassonografia transvaginal e teste pós-coital.","C":"Teste pós-coital e ultrassonografia escrotal com\nDoppler.","D":"Dosagem de LH no 14.º dia do ciclo e\nhisterossalpingografia.","E":"Espermograma e dosagem de FSH no terceiro dia do ciclo para avaliar reserva ovariana."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-75487","number":"75487","sourceNumber":"75487","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente com 65 anos de idade, menopausa ocorrida há doze anos, comparece ao\nPronto-Socorro com história de sangramento vaginal esporádico e leve há sete meses, com piora\ndo sangramento há dois dias, acompanhado de fraqueza e mal-estar. Nega dor pélvica ou outros\nsintomas. Tem hipertensão arterial sistêmica controlada e obesidade (IMC = 38 kg/m²). Ao exame\nginecológico verifica-se saída de sangue pelo orifício externo do colo uterino. Traz resultado de\ncolpocitologia oncológica que está normal. Ultrassonografia transvaginal mostra útero de 30 cm³\ncom eco endometrial de 2 mm de espessura, ovários não visualizados. A causa mais provável para\no sangramento apresentado:\n\npela paciente é:","options":{"A":"adenomiose.","B":"pólipo endometrial.","C":"atrofia do endométrio.","D":"câncer de endométrio.","E":"hiperplasia endometrial."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-31014","number":"31014","sourceNumber":"31014","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No que tange aos aspectos éticos e jurídicos da obstetrícia, julgue o item a seguir: \"No\nBrasil, a gestação de substituição será permitida naqueles casos em que houver problema médico\nque impeça ou contraindique a gestação na doadora genética. Nessa situação, deve haver\nparentesco até o segundo grau entre a doadora genética e a paciente que fará a cessão temporária\ndo útero, e não pode haver caráter lucrativo ou comercial.\"","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-31015","number":"31015","sourceNumber":"31015","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No que tange aos aspectos éticos e jurídicos da obstetrícia, julgue o item a seguir:\n\"Nas gestações múltiplas, com mais de quatro\nembriões implantados, a resolução do Conselho\nFederal de Medicina permite a utilização da técnica de redução embrionária, desde que o casal\nassine o termo de consentimento.\"","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-22189","number":"22189","sourceNumber":"22189","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Julgue o item subsequente, relativo à anticoncepção e infertilidade conjugal. A\ninfertilidade primária é definida como a gestação que não evoluiu com um nascido vivo.","options":{"A":"certo","B":"errado"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-22193","number":"22193","sourceNumber":"22193","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Julgue o item seguinte, quanto à distúrbios benignos e malignos do corpo uterino. Os\npólipos endometriais são sensíveis aos estrogênios, e a resposta a esses hormônios é semelhante\nà do endométrio circundante.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-8667","number":"8667","sourceNumber":"8667","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O tumor benigno de músculo liso mais frequente no sexo feminino é o leiomioma\nuterino. A respeito dessa patologia, julgue o\nitem a seguir. Os leiomiomas são raros antes da\nmenarca, crescem durante a gravidez ou por ocasião de tratamento com esteroides sexuais e,\nhabitualmente, regridem na menopausa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-8670","number":"8670","sourceNumber":"8670","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Acerca do planejamento familiar e infertilidade conjugal, julgue o seguinte item:\nInfertilidade conjugal é a ausência de concepção\napós um ano de coitos regulares e desprotegidos,\ne denomina-se primária na ausência de gestação prévia e secundária quando há antecedentes de\ngestação, mesmo que esta não tenha evoluído até o termo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-368174","number":"368174","sourceNumber":"368174","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A endometriose é uma afecção clínica e recorrente caracterizada pela presença de\ntecido endometrial funcional fora da cavidade\nuterina e do miométrio. A apresentação clínica é\nmuito variável, e nenhum sintoma é específico para a endometriose, dificultando o seu diagnóstico.\nSobre a investigação diagnóstica na suspeita de endometriose, assinale a alternativa correta.","options":{"A":"A dosagem do marcador CA125 é necessária para a confirmação diagnóstica da endometriose.","B":"A cirurgia videolaparoscópica é o padrão-ouro para o diagnóstico de endometriose.","C":"A colonoscopia pode ser substituída pela tomografia computadorizada no diagnóstico da\nendometriose.","D":"A ultrassonografia endovaginal tem baixa sensibilidade e especificidade para o diagnóstico da\nendometriose."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-320424","number":"320424","sourceNumber":"320424","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O sangramento uterino anormal é uma queixa frequente nos consultórios de\nginecologia. A Federação Internacional de\nGinecologia e Obstetrícia (FIGO) classifica suas\netiologias com o sistema PALM-COEIN. As etiologias do PALM-COEIN são: Pólipo uterino (P),\nAdenomiose (A), Leiomiomia (L), lesões precursoras e Malignas do corpo uterino (M),\nCoagulopatias (C), distúrbios da Ovulação (O), disfunção Endometrial (E), Iatrogênicas (I) e Não\nclassificadas nos itens anteriores (N). Considere uma paciente de 54 anos, GV PIV AI, menopausa\nhá 7 anos, sem uso de terapia hormonal. Hipertensa e diabética, usando losartana e metformina,\ncom história familiar positiva para câncer de mama. Referenciada ao ambulatório de ginecologia\npela equipe da saúde da família do bairro onde mora com relato de episódios de sangramento\nvaginal esporádico nos últimos 6 meses, com resultado de colpocitologia oncótica do colo uterino =\nAlterações benignas e ultrassonografia endovaginal com útero 65cc, endométrio 25mm, ovários não\nvisualizados. Assinale a alternativa correta quanto a esse caso clínico:","options":{"A":"devemos suspeitar de lesões malignas e prosseguir a investigação com histopatológico do\nendométrio.","B":"devemos suspeitar de lesões malignas e prosseguir a investigação com colposcopia.","C":"devemos suspeitar causas iatrogênicas e modificar as medicações em uso para hipertensão e\ndiabetes.","D":"devemos suspeitar de distúrbios de ovulação e prescrever medicação hormonal.","E":"devemos suspeitar de atrofia endometrial e prescrever terapia hormonal."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-335077","number":"335077","sourceNumber":"335077","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Considere as afirmativas a seguir sobre a varicocele. I. Ocorre com maior frequência do\nlado direito. II. É a causa mais comum de infertilidade em homens. III. Está indicado o tratamento\nem adolescentes com varicocele grau 2 e atrofia testicular ipsilateral. IV. Em adultos, o tratamento\nestá indicado quando a varicocele é palpável sem manobra de Valsalva e com espermograma\nalterado. Estão corretas as afirmativas","options":{"A":"I, II e III, apenas.","B":"I, II e IV, apenas.","C":"I, III e IV, apenas.","D":"II, III e IV, apenas."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-291617","number":"291617","sourceNumber":"291617","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Comparece ao ambulatório de cirurgia ginecológica paciente de 63 anos, menopausa\naos 45 anos, sem uso de terapia hormonal no\nmomento. Informa 4 episódios de sangramento\nvaginal nos últimos 7 meses e traz ultrassonografia transvaginal realizada há 10 dias com\nendométrio de 18mm. Considerando essas informações , qual a conduta indicada a seguir?","options":{"A":"Observar sangramento e repetir ultrassonografia transvaginal em três meses.","B":"Histerectomia com retirada de trompas e ovários.","C":"Histeroscopia com biópsia de endométrio.","D":"Histerectomia sem retirada de trompas e ovários.","E":"Prescrever estrogênio e progesterona e repetir ultrassonografia transvaginal em três meses."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-313319","number":"313319","sourceNumber":"313319","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Considerando a temática da Reprodução Humana e sua fisiologia, é incorreta a\nafirmativa dada em:","options":{"A":"As espermatogônias, células primordiais que darão origem aos espermatozoides, permanecem\ndormentes nos túbulos seminíferos nos\ntestículos desde o período fetal tardio até antes da\npuberdade.","B":"Oôgenese é a sequência de eventos pelos quais as oogônias se diferenciam em oócitos.","C":"Em relação à constituição de cromossomos sexuais, existem dois tipos de espermatozoides\nnormais, 22 autossômicos mais um cromossomo\nsexual X (23, X) ou um cromossomo sexual Y (23,\nY).","D":"A gametogênese origina duas células: o espermatozoide e o oócito. São chamados de gametas\ne cada um contém metade do número típico de\ncromossomos. Esse número é reduzido pela\nmetade por meio de um tipo de divisão celular conhecida como mitose.","E":"Após a menarca (época do primeiro período menstrual), a mulher passa, mensalmente, por\nciclos reprodutivos regulados pelo hipotálamo, pela glândula hipófise e pelos ovários."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-306739","number":"306739","sourceNumber":"306739","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Adolescente de 15 anos, sem atividade sexual, relata sangramento vaginal há 15 dias.\nApresenta-se descorada 2+/4, com hemoglobina de 9,2 g/dL e hematócrito de 29%. Quanto ao\ndiagnóstico e tratamento, é correto afirmar que:","options":{"A":"A administração de estrogênios não deve ser realizada pelo risco de hiperplasia endometrial.","B":"Os ciclos anovulatórios são a etiologia mais habitual nessa fase da vida.","C":"As discrasias sanguíneas constituem a etiologia mais comum nessa fase da vida.","D":"Se deve realizar a curetagem uterina para controle imediato do sangramento."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-314067","number":"314067","sourceNumber":"314067","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher branca de 32 anos, nulípara, apresenta histórico de agravamento\nprogressivo da dor menstrual, que agora lhe\ncausa sofrimento na maior parte do mês. Ela perde 2 a\n3 dias de trabalho todos os meses. Ela não encontra alívio com o ibuprofeno e não consegue mais\ntolerar a cefaleia associada às pílulas contraceptivas. No momento, ela é sexualmente ativa, com\num parceiro de longa data. Seu relacionamento está sendo afetado pelo estresse e pela dor\nassociados à relação sexual. No exame vaginal, sua musculatura pélvica está moderadamente\nsensível, sem corrimentos vaginais. O útero tem tamanho normal e é pouco sensível. O exame\nretrovaginal revela nodularidade uterossacral e extrema sensibilidade. As fezes são moles, de cor\nmarrom e heme-negativas. Em relação ao caso exposto, assinalar a alternativa que apresenta o\ndiagnóstico clínico mais provável:","options":{"A":"Câncer de ovário.","B":"Miomatose uterina.","C":"Doença Inflamatória Pélvica","D":"Endometriose.","E":"Câncer cervical."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-314073","number":"314073","sourceNumber":"314073","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"De acordo com DUNCAN et al., a avaliação inicial da adolescente com queixa de\ndismenorreia deve consistir em anamnese detalhada e exame físico geral, com atenção especial\npara palpação do abdome, a fim de evidenciar anormalidades, como massas abdominais. Em\nrelação à dismenorreia na adolescência, analisar os itens abaixo: I. Em geral, a dismenorreia tem\ninício 6 a 18 meses após a menarca, quando iniciam os ciclos menstruais ovulatórios. II. Na grande\nmaioria das vezes, nenhuma condição patológica subjacente é diagnosticada; entretanto, a\ndismenorreia pode ser ocasionada por problemas pélvicos, como anormalidades anatômicas,\nendometriose, cistos ovarianos e doença inflamatória pélvica. III. Na dismenorreia primária, a dor\ncaracteriza-se por ser intermitente e em cólica, geralmente iniciando com o fluxo menstrual ou logo\napós. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-287346","number":"287346","sourceNumber":"287346","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Dentre as alternativas abaixo, qual é considerada uma causa de sangramento genital\nanormal?","options":{"A":"Mioma intramural.","B":"Pólipos endocervicais e endometriais.","C":"Endometriose em cavidade abdominal.","D":"Endométrio atrófico."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-283906","number":"283906","sourceNumber":"283906","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual a melhor propedêutica para o mapeamento das lesões pélvicas na endometriose\nprofunda?","options":{"A":"Tomografia computadorizada.","B":"Colonoscopia.","C":"Videolaparoscopia.","D":"Ultrassonografia transvaginal com preparo intestinal.","E":"Exame físico ginecológico."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-287885","number":"287885","sourceNumber":"287885","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Conforme ROUQUAYROL e GURGEL, o sistema reprodutivo caracteriza-se por\neventos hormonais que culminam com o\nsangramento mensal na ausência de gravidez - a\nmenstruação. Esse delicado processo que envolve o eixo hipotálamo-hipófise-ovário pode ser\nalterado e levar a sangramentos uterinos anormais. Em relação ao exposto, analisar os itens\nabaixo: I. A neoplasia uterina mais frequentemente associada ao sangramento uterino aumentado é\na miomatose uterina que, conforme sua localização, principalmente se submucosal e intramural,\ncausa sangramento aumentado. II. Condições sistêmicas podem influenciar o ciclo menstrual e\nlevar a distúrbios de sangramento anormal, como hipotireoidismo, hiperplasia da suprarrenal e\ncoagulopatias. III. Quadros infecciosos que levam à endometrite podem causar sangramento\nuterino acíclico. O agente infeccioso mais associado a essa situação é a Chlamydia trachomatis,\nmas outros agentes, menos comuns, também podem levar a esse quadro. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-287887","number":"287887","sourceNumber":"287887","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"De acordo com GUSSO E LOPES, em relação à infertilidade masculina, analisar a\nsentença abaixo: A pesquisa da infertilidade\nmasculina fundamenta-se basicamente na avaliação\ndo espermocitograma, o qual deve ser feito com 3 a 7 dias de abstinência sexual (1ª parte). Nos\ncasos em que o espermocitograma está alterado, buscam-se outras causas que possam interferir\nna produção espermática, solicitando-se: TSH, prolactina, FSH, testosterona, cariótipo e US\ntesticular com Doppler (2ª parte). Pela variabilidade da produção espermática, deve-se analisar um\nmínimo de duas amostras, com intervalo de 1 a 2 semanas entre as coletas (3ª parte). A sentença\nestá:","options":{"A":"Totalmente correta.","B":"Correta somente em sua 3ª parte.","C":"Correta somente em suas 1ª e 2ª partes.","D":"Correta somente em suas 2ª e 3ª partes.","E":"Totalmente incorreta."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-232116","number":"232116","sourceNumber":"232116","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 35 anos, GII PII A0, é atendida em ambulatório de ginecologia com relato\nde sangramento menstrual aumentado há 6 meses\n(menstruações a cada 25 dias, duração de 9\ndias e quantidade abundante, com coágulos). Os exames complementares realizados mostram\npresença de mioma submucoso pediculado no interior da cavidade uterina de 2,2 cm. A conduta\nideal para tratar esta paciente é:","options":{"A":"Miomectomia histeroscópica.","B":"Miomectomia laparoscópica.","C":"Miomectomia por laparotomia.","D":"Histerectomia total por via vaginal.","E":"Histerectomia total laparoscópica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-227260","number":"227260","sourceNumber":"227260","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Diante de um diagnóstico de leiomioma submucoso, medindo 1,5 cm no seu maior\ndiâmetro, em uma paciente nuligesta, a melhor conduta terapêutica para o caso é:","options":{"A":"Prescrição de análogo de gonadotrofinas.","B":"Miomectomia via laparotomia.","C":"Miomectomia via laparoscopia.","D":"Miomectomia via histeroscópica."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234421","number":"234421","sourceNumber":"234421","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação à reprodução assistida, é INCORRETO afirmar que:","options":{"A":"O hormônio liberador de gonadotrofina é único entre os hormônios liberadores porque regula\nsimultaneamente a secreção de dois hormônios: o hormônio estimulante do folículo ovariano e o\nhormônio luteizante.","B":"A fase folicular do ciclo menstrual é caracterizada por pulsos com pequena amplitude, porém\nfrequentes de secreção de hormônio liberador de gonadotrofina.","C":"O ciclo menstrual normal varia de 21 a 35 dias, com fluxo que dura de 2 a 7 dias, com perda\nsanguínea média de 60-90ml.","D":"Ao final da fase folicular do ciclo menstrual, receptores do hormônio luteizante, induzidos pelo\nhormônio estimulante do folículo ovariano estão presentes nas células granulosas e, com a\nestimulação do hormônio luteizante, modulam a secreção de progesterona."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-255637","number":"255637","sourceNumber":"255637","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre as causas etiológicas mais frequentes de sangramento uterino anormal na\nadolescência, MARQUE A CORRETA:","options":{"A":"Condilomatose vulvar","B":"Anovulação","C":"Leiomiomas","D":"Infecção por Gardnerella vaginalis"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-255642","number":"255642","sourceNumber":"255642","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Lívia, 32 anos, vai ao ginecologista, pois não está conseguindo engravidar. Durante a\ninvestigação ela relata que começou apresentar dores pélvicas durante a menstruação após os 25\nanos. Para aumentar o grau de suspeição para endometriose, o ginecologista deve, ainda,\nquestionar a paciente sobre qual outro sintoma? MARQUE A CORRETA:","options":{"A":"Alteração intestinal.","B":"História familiar de endometriose.","C":"Paridade.","D":"Uso de tabaco."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-246758","number":"246758","sourceNumber":"246758","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual dos seguintes tipos celulares sofre a primeira divisão meiótica para formar células\nhaploides?","options":{"A":"Espermatogonia.","B":"Espermatócito primário.","C":"Espermatócito secundário.","D":"Espermátide primária.","E":"Espermátide secundária."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-246770","number":"246770","sourceNumber":"246770","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 18 anos com 5 semanas de amenorreia deu entrada na maternidade referindo\naparecimento de sangramento transvaginal de pequena monta após coito vaginal. A conduta inicial\nadequada para o caso:","options":{"A":"Exame especular.","B":"Orientação verbal sobre a possibilidade de laceração em fúrcula vaginal.","C":"Avaliação ultrassonográfica por via vaginal","D":"Videocolposcopia.","E":"Uso de progesterona via vaginal."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-199495","number":"199495","sourceNumber":"199495","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação aos tumores benignos do útero, é INCORRETO afirmar que:","options":{"A":"O diagnóstico diferencial principal do mioma uterino é com o sarcoma, tumor raro com incidência\n3 a 7 por 100.000 mulheres, com mau\nprognóstico.","B":"Em caso de suspeita de leiomiossarcoma uterino, a técnica cirúrgica mais indicada é a de\nmorcelamento com o objetivo de assegurar sua completa ressecção.","C":"O principal tipo de sarcoma, que pode assemelhar-se a um leiomioma, é o leiomiossarcoma, que\nse apresenta como uma massa miometrial,\ngeralmente associada a sangramento uterino anormal.","D":"Para se obter bom tratamento cirúrgico de mioma uterino, deve-se levar em consideração outras\ncondições como a relação do tumor com os sinais e sintomas relatados e ainda, com os sinais e\nsintomas urinários."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-202770","number":"202770","sourceNumber":"202770","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Miomas uterinos representam importante problema da atenção à saúde, pois são\nindicação mais frequente de histerectomia.\nAvalie as afirmações abaixo sobre este tumor: I. Miomas\nuterinos são muito comuns, e a maioria deles é assintomática e pode ser tratado de maneira\nconservadora. II. Os miomas submucosos, às vezes associados ao aumento do sangramento\nmenstrual ou à infertilidade, frequentemente podem ser removidos por laparoscopia. III. A\ndegeneração sarcomatosa é rara e mais provável em mulheres após a menopausa com sintomas\nde dor e sangramento. IV. A ultrassonografia é a técnica de imagem de maior disponibilidade e\nmenor custo para diferenciar miomas de outras doenças pélvicas; porém, a ressonância nuclear\nmagnética possibilita a avaliação mais precisa do número, do tamanho e da posição dos miomas. É\ncorreto o que se afirma em:","options":{"A":"II e IV apenas.","B":"II, III e IV apenas.","C":"I, II, III e IV.","D":"I, III e IV apenas.","E":"I, II e IV apenas."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-199581","number":"199581","sourceNumber":"199581","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 70 anos de idade, GIP0AI, menopausa aos 50 anos, obesa, hipertensa,\napresenta sangramento vaginal que iniciou há 2\nmeses. Nega uso de terapia hormonal. Traz\nconsigo ultrassonografia transvaginal realizada há 1 mês que evidenciou um endométrio de 10 mm.\nO exame ginecológico não mostrou lesão em vagina e colo. A propedêutica mais eficaz para a\ninvestigação do sangramento é:","options":{"A":"Colpocitologia oncótica.","B":"Curetagem uterina.","C":"Histeroscopia.","D":"Não há necessidade de investigação do sangramento, pois a paciente já realizou a\nultrassonografia transvaginal."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-212987","number":"212987","sourceNumber":"212987","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual a causa mais frequente de sangramento genital na pós-menopausa, sem terapia\nhormonal?","options":{"A":"Atrofia de endométrio.","B":"Câncer de endométrio.","C":"Pólipo endometrial.","D":"Neoplasia ovariana.","E":"Mioma submucoso."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-174359","number":"174359","sourceNumber":"174359","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"R.L.P., 45 anos, GIV PIII AI. Comparece ao ambulatório de ginecologia com queixa de\ndores pélvicas em peso de início há 6 meses, associado a aumento do fluxo menstrual. Menstrua\nmensalmente com duração de 6 dias. Nega uso de medicação anticoncepcional, pois o marido\nrealizou vasectomia há 6 anos, após o nascimento do último filho. Nega patologias clínicas ou\ncirurgias prévias. O exame clínico da pelve evidenciou útero aumentado de volume, móvel,\nlevemente doloroso à manipulação, consistência fibroelástica e superfície bocelada. A\nultrassonografia pélvica evidenciou útero com volume de 365cc, apresentando múltiplos nódulos\nintramurais com tamanhos variando de 1,2 a 6,3 cm com característica sugestiva de miomas. O\nmelhor tratamento a ser oferecido para esta paciente é:","options":{"A":"Análogos de GnRH.","B":"Miomectomia laparoscópica.","C":"Miomectomia histeroscópica.","D":"Miomectomia por laparotomia.","E":"Histerectomia."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-172760","number":"172760","sourceNumber":"172760","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No sangramento uterino anormal, é considerado polimenorreia:","options":{"A":"Aumento do fluxo menstrual.","B":"Aumento da duração da menstruação.","C":"A diminuição do intervalo menstrual.","D":"Aumento do intervalo menstrual."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-172790","number":"172790","sourceNumber":"172790","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"É considerado padrão ouro para o diagnóstico de endometriose:","options":{"A":"Ressonância magnética de pelve.","B":"Dosagem do CA-125.","C":"Ultrassonografia transvaginal.","D":"Laparoscopia com exame histológico de lesões excisadas."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-155475","number":"155475","sourceNumber":"155475","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Podemos definir a endometriose como a ocorrência de tecido endometrial fora do útero.\nAcredita-se que sua prevalência chegue a 10%, afetando principalmente mulheres em idade\nreprodutiva. Sobre o diagnóstico da endometriose, é CORRETO afirmar que:","options":{"A":"As lesões endometrióticas causam irritação e inflamação peritoneal com consequente eliminação\nde CA-125. Portanto, o CA-125 tem alta\nsensibilidade para o diagnóstico de endometriose e está\nsempre elevado, mesmo nos casos de endometriose mínima ou leve.","B":"Embora inútil para o diagnóstico de endometriose peritoneal, a ultrassonografia tem alta\nsensibilidade e especificidade para o diagnóstico do endometrioma ovariano.","C":"A ressonância magnética não deve ser realizada para avaliação de endometriose, pois não traz\ninformações adicionais à ultrassonografia.","D":"A laparoscopia para avaliação de endometriose deve sempre ser realizada no período\nmenstrual.","E":"O exame físico ? especular e toque vaginal ? não traz nenhuma informação relevante para o\ndiagnóstico de endometriose."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-155480","number":"155480","sourceNumber":"155480","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Comparece no ambulatório de ginecologia geral casal com queixa de infertilidade.\nRelata ausência de uso de método contraceptivo\nhá 14 meses e frequência de coito de 3-4 vezes\npor semana. Ela tem 30 anos, é nulípara, apresenta sobrepeso e tem ciclos menstruais irregulares,\nchegando a ficar até 90 dias sem menstruar, nega outros sintomas anormais ou queixas. Ele tem\n34 anos, hígido e tem 2 filhos de outro relacionamento. Após realizar o exame físico da paciente, a\nconduta mais adequada é:","options":{"A":"Solicitar US seriada para confirmar a anovulação e encaminhar para clínica de reprodução.","B":"Solicitar US seriada para confirmar a anovulação e em seguida prescrever indutor de ovulação.","C":"Solicitar espermograma para ele e US seriada, histerossalpingografia , FSH, TSH, T4 Livre e\nProlactina para ela.","D":"Orientar coito diário e retornar em 10 meses para reavaliação.","E":"Prescrever indutor de ovulação pois está claro o diagnóstico."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-162578","number":"162578","sourceNumber":"162578","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A conduta mais coerente para uma mulher 37 anos que deseja engravidar, porém\napresenta no USG um mioma intramural/subseroso\ncom 2.1 cm x 2.0 cm x 1.9 cm. Assintomática e\ncom ciclos regulares:","options":{"A":"Miomectomia o quanto antes pela chance de aumento do volume do mioma durante a gestação\ne grande chance de parto prematuro.","B":"Embolização do mioma.","C":"Conduta expectante e preparo pré-gestacional imediato.","D":"Histeroscopia cirúrgica.","E":"Curetagem semiótica."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-148601","number":"148601","sourceNumber":"148601","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre o papel dos estrogênios na formação e crescimento dos leiomiomas, observe as\nafirmações: I- Os leiomiomas têm maior densidade de receptores estrogênicos que o miométrio\nnormal. II- Os leiomiomas convertem mais o estradiol em estrona. III- Os leiomiomas apresentam\nníveis mais baixos da aromatase citocromo P450 que os miócitos normais. É correto o que se\nafirma em:","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"II e III, apenas.","D":"I e III, apenas.","E":"I, II, III."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-148617","number":"148617","sourceNumber":"148617","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"APJ, 16 anos, feminina, com queixa de hipermenorreia, com anemia ferropriva.\nUltrassonografia endovaginal mostrou útero e anexos\nnormais. Ao exame especular, vagina e colo\nuterino normais, sendo classificado como sangramento disfuncional. Observe as afirmativas abaixo\ne assinale a incorreta.","options":{"A":"Sangramento disfuncional uterino é considerado quando observa-se um sangramento em\ngrande quantidade, e não usa-se este termo quando a\nfrequência e a duração são maiores que o\nconsiderado normal.","B":"Alterações endócrinas como obesidade, magreza excessiva ou síndrome de Cushing podem ser\ncausa de sangramento uterino disfuncional.","C":"Distúrbios de coagulação sanguínea podem ser causa de sangramento uterino disfuncional.","D":"Em adolescentes o sangramento uterino disfuncional pode ser limitado, sendo importante\nobservar antes de realizar intervenção\nmedicamentosa.","E":"Quando há sinal de hipovolemia em paciente jovem, o uso de estrogênio em altas doses está\nindicado."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-137838","number":"137838","sourceNumber":"137838","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Miomas são tumores benignos das células musculares lisas do miométrio muito\ncomuns. Apresentam sintomas e repercussão clínica\nvariada e podem ser classificados de acordo\ncom a camada da parede uterina que ocupam. Assinale a alternativa que contém afirmações\nverdadeiras sobre os miomas representados na figura abaixo .","options":{"A":"A figura representa apenas miomas submucosos. É esperado que ocorram alterações\nmenstruais (p.ex. metrorragia , menorragia,\nhipermenorreia). Há impacto reprodutivo negativo com\ndiminuição das taxas de fertilidade.","B":"A figura representa apenas miomas submucosos. É esperado que ocorram alterações\nmenstruais (p.ex. metrorragia , menorragia,\nhipermenorreia). Não provocam alterações das taxas\nde fertilidade.","C":"A figura representa apenas miomas subserosos . É esperado que ocorram alterações\nmenstruais (p.ex. metrorragia , menorragia,\nhipermenorreia). Há impacto reprodutivo negativo com\ndiminuição das taxas de fertilidade.","D":"A figura representa miomas submucosos e intramurais. É esperado que ocorram alterações\nmenstruais (p.ex. metrorragia , menorragia,\nhipermenorreia). Há impacto reprodutivo negativo com\ndiminuição das taxas de fertilidade.","E":"A figura representa miomas submucosos e intramurais. É esperado que ocorram alterações\nmenstruais (p.ex. metrorragia , menorragia,\nhipermenorreia). Não provocam alterações das taxas\nde fertilidade."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":["question_bank/media/medcurso/medcurso-gineco-gin-2/137838.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-137847","number":"137847","sourceNumber":"137847","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A endometriose é definida como ocorrência de tecido endometrial fora do útero.\nPredomina em mulheres em idade reprodutiva e tem uma prevalência estimada de\naproximadamente 10%. Sobre a endometriose, não podemos afirmar:","options":{"A":"Mesmo pacientes com doença avançada podem ser assintomáticas.","B":"Devemos suspeitar do diagnóstico de endometriose em pacientes que apresentam infertilidade,\ndispareunia, dismenorreia ou dor pélvica crônica.","C":"Embora a ultrassonografia não identifique a endometriose peritoneal, ela se mostra importante\nna identificação de endometriose ovariana. O cisto\nendometriótico apresenta características de\n\n?vidro fosco? do liquido cístico e ausência de partes sólidas.","D":"A laparoscopia é o método padrão para inspeção visual da pelve e estabelecimento de\ndiagnóstico definitivo de endometriose.","E":"Entre as teorias para explicar sua histogênese, a teoria da metaplasia celômica baseia-se na\nsuposição de que a endometriose é causada por semeadura ou implantação de células\nendometriais por regurgitação transtubária durante a menstruação."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-127205","number":"127205","sourceNumber":"127205","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Dentre as propedêuticas ginecológicas abaixo, qual delas é considerada padrão ouro\npara o diagnóstico definitivo de\nendometriose?","options":{"A":"Ultrassonografia transvaginal com preparo intestinal.","B":"Ressonância Nuclear Magnética.","C":"Videolaparoscopia com biópsia.","D":"Dosagem sérica seriada de CA 125.","E":"Dosagem sérica de interleucina-6 (IL-6)."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-127218","number":"127218","sourceNumber":"127218","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre doenças miometriais, é correto afirmar que:","options":{"A":"Miomas subserosos, pelo risco de sangramento, devem ser extirpados por videolaparoscopia.","B":"A adenomiose é causada por sangramento uterino e é facilmente diagnosticada pelo aumento\ndo útero no toque vaginal.","C":"Os miomas são mais frequentes na pós-menopausa.","D":"O único tratamento da miomatose é a histerectomia.","E":"O mioma submucoso tem a ressecção histeroscópica como tratamento preferencial."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-100946","number":"100946","sourceNumber":"100946","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual dos achados ultrassonográficos abaixo não se correlaciona com a queixa de\nirregularidade menstrual?","options":{"A":"Adenomiose uterina.","B":"Miomatose uterina.","C":"Pólipo endometrial.","D":"Hidrossalpinge.","E":"Cisto ovariano."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-100999","number":"100999","sourceNumber":"100999","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 30 anos, submetida há 02 meses a uma histerectomia total abdominal por\nmiomatose uterina, refere perda involuntária de urina sem associação com esforços ou vontade de\nurinar. O exame físico está normal e o exame especular apresenta cúpula vaginal normal e excesso\nde umidade na vagina. A principal hipótese diagnóstica é:","options":{"A":"Incontinência urinária de esforço.","B":"Urgência miccional.","C":"Síndrome urinária.","D":"Fístula vesico-vaginal.","E":"Hipermobilidade do colo vesical."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-101021","number":"101021","sourceNumber":"101021","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"É patologia ginecológica mais comum na quarta década de vida, que acarreta útero\nglobalmente aumentado de volume, dismenorreia e hipermenorreia:","options":{"A":"Adenomiose.","B":"Endometriose.","C":"Miomatose uterina.","D":"Pólipo endometrial.","E":"Sarcoma uterino."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-102728","number":"102728","sourceNumber":"102728","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação aos tumores uterinos, assinale a alternativa INCORRETA.","options":{"A":"Os miomas uterinos podem ser classificados quanto à sua posição na musculatura em\nsubmucoso; subperitoneal e intraparietal.","B":"Em aproximadamente 90% dos casos, os miomas não crescem de maneira significativa durante\na gravidez.","C":"A compressão uretral é mais comum, em torno de 30-70% à esquerda, devido à sua mais\nfrequente dextroversão.","D":"São causas primárias pouco frequentes de infertilidade."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-88875","number":"88875","sourceNumber":"88875","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 23 anos, sexualmente ativa, com menorragia há 15 dias, refere ter hirsutismo\ne ciclos oligomenorreicos desde a menarca. Faz\nuso de camisinha como método contraceptivo.\n\nQual o principal diagnóstico nessa paciente com sangramento uterino anormal?","options":{"A":"Sangramento uterino disfuncional.","B":"Gravidez.","C":"Miomatose uterina.","D":"Síndrome dos ovários policísticos.","E":"Anovulação."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-88877","number":"88877","sourceNumber":"88877","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A relação endometriose-infertilidade pode ser explicada por: I. Distorção na anatomia\npélvica, com comprometimento tubário. II. Reação inflamatória peritoneal. III. Disfunção da fase\nlútea.Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III","D":"Apenas I e II.","E":"I, II e III."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-77339","number":"77339","sourceNumber":"77339","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre os sangramentos anormais:","options":{"A":"Na pré-menopausa, são apenas de etiologia hormonal.","B":"Sangramentos volumosos ou intermenstruais podem necessitar de investigação adicional\nmesmo em mulheres jovens.","C":"Dispositivos intrauterinos liberadores de hormônio só podem ser usados em mulheres com ciclos\nregulares.","D":"Mesmo em ciclos menstruais com volume de perda de sangue acima de 200 ml/ciclo é raro\nocorrer anemia.","E":"O tratamento de escolha inicial para os sangramentos disfuncionais em mulheres jovens deve\nser feito com pílulas apenas com estrogênio\nem doses maiores."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-59368","number":"59368","sourceNumber":"59368","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Acerca do aborto, marque a alternativa CORRETA:","options":{"A":"A síndrome do anticorpo antifosfolipídeo é causa comum de abortos de repetição.","B":"A incompetência do colo uterino é uma das principais causas de aborto.","C":"É toda perda fetal que ocorre antes de 30 semanas de gestação.","D":"É absolutamente contraindicado o uso de misoprostol.","E":"Todas as respostas estão incorretas."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-59423","number":"59423","sourceNumber":"59423","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre os sangramentos anormais:","options":{"A":"Na pré-menopausa são apenas de etiologia hormonal.","B":"Mesmo para sangramentos volumosos ou intermenstruais, em mulheres jovens nenhuma\ninvestigação adicional é necessária.","C":"Dispositivos intrauterinos liberadores de hormônio só podem ser usados em mulheres com ciclos\nregulares.","D":"Ciclos menstruais com volume de perda de sangue acima de 80 ml/ciclo, geralmente causam\nanemia.","E":"O tratamento de escolha inicial para os sangramentos disfuncionais em mulheres jovens deve\nser feito com pílulas apenas com estrogênio\nem doses maiores."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-59080","number":"59080","sourceNumber":"59080","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre o risco de aparecimento dos miomas uterinos é correto afirmar, exceto:","options":{"A":"O tabagismo reduz o risco de miomas uterinos.","B":"O uso de pílula anticoncepcional por longo tempo aumenta o risco de miomas uterinos.","C":"A obesidade aumenta o risco de miomas uterinos.","D":"Multíparas têm menor risco de miomas uterinos que nuligestas.","E":"A terapia hormonal do climatério aumenta o risco de reaparecimento dos miomas."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-59019","number":"59019","sourceNumber":"59019","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação à endometriose é incorreto afirmar:","options":{"A":"Afeta mais mulheres na terceira e quarta décadas de vida, em sua maioria sem gestação prévia.","B":"Fatores predisponentes: menarca precoce, malformações uterinas e estenose do óstio do colo\nuterino.","C":"Fatores protetores: gestação, lactação e uso prolongado de anticoncepcionais hormonais.","D":"A infertilidade ocorre somente com a doença avançada, levando à distorção da anatomia\npélvica.","E":"O tecido ectópico é semelhante ao endométrio e responde aos estímulos hormonais ovarianos."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-59062","number":"59062","sourceNumber":"59062","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Pode-se afirmar quanto à hemorragia uterina disfuncional:","options":{"A":"É mais comum nos miomas uterinos submucosos.","B":"A anovulação crônica é evento raro na sua fisiopatologia.","C":"É um sangramento uterino anormal, provocado por disfunção hormonal sem causa orgânica.","D":"A drosperinona é a causa mais comum desse evento.","E":"O uso de vitaminas, principalmente o ácido fólico, é de extrema importância para seu controle."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-43933","number":"43933","sourceNumber":"43933","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Para uma paciente com Síndrome de Mayer-Rokitanski-Küster-Hauser ter filhos com\nsua carga genética é necessário:","options":{"A":"Ingerir indutores de ovulação e ter relação sexual no período fértil.","B":"Ser submetida a construção de neovagina na idade adulta.","C":"Fazer correção cirúrgica de seu útero septado.","D":"Receber doação de óvulos fecundados para serem implantados em seu útero.","E":"Fazer doação de seus óvulos para serem fecundados e implantados em útero de outra pessoa."},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-32494","number":"32494","sourceNumber":"32494","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São causas de sangramento genital anormal na peri e pós-menopausa, exceto:","options":{"A":"Pólipos endocervicais e endometriais.","B":"Carcinoma do colo do útero.","C":"Carcinoma de endométrico.","D":"Endometriose.","E":"Endométrio atrófico."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-23116","number":"23116","sourceNumber":"23116","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação aos miomas uterinos, é correto afirmar, exceto:","options":{"A":"São os tumores mais comuns do trato genital, atingindo cerca de 30% a 40% das mulheres no\nmenacme","B":"A obesidade facilita o crescimento dos miomas","C":"São mais comuns nas multíparas","D":"Fumantes e usuárias de pílulas anticoncepcionais por longo tempo tem menor incidência","E":"Diminuem de volume e até podem desaparecer após a menopausa sem Terapia Hormonal"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-23117","number":"23117","sourceNumber":"23117","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Os exames complementares são importantes no diagnóstico dos miomas. Marque a\nalternativa incorreta:","options":{"A":"A ultra-sonografia é um exame subsidiário que mais utiliza o diagnóstico","B":"A técnica de ultrassom endovaginal tem maior capacidade de identificar miomas submucosos e\nintramurais","C":"Miomas subserosos com pedículos finos são melhores identificados pela técnica\nultrassonografia abdominal","D":"O ultrassom tem limitações em pacientes obesas e com útero retrovertido","E":"O ultrassom é capaz de diferenciar leiomioma e leiomiosarcoma"},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-23081","number":"23081","sourceNumber":"23081","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"São medicamentos usados no tratamento clínico de endometriose, exceto:","options":{"A":"Anticoncepcionais hormonais.","B":"Citrato de clomifeno.","C":"Progestagênios.","D":"Danazol.","E":"Análogos do GnRH."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-330071","number":"330071","sourceNumber":"330071","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre a infertilidade feminina, é CORRETO afirmar:","options":{"A":"A síndrome da hiperestimulação ovariana não ocorre quando há teste pré-implantacional nos\nembriões.","B":"A endometriose e a síndrome do ovário policístico não são fatores que aumentam as chances de\ninfertilidade feminina.","C":"A doença inflamatória pélvica é a maior causa de infertilidade feminina por fator tubário.","D":"A utilização de terapia hormonal por tempo prolongado pode aumentar as chances de\ninfertilidade feminina."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-346417","number":"346417","sourceNumber":"346417","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"As principais indicações de tratamento da endometriose são:","options":{"A":"Edema e dor abdominal;","B":"Hemorragia e dor abdominal;","C":"Dor abdominal e inchaço abdominal;","D":"Dor pélvica crônica e infertilidade."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-339803","number":"339803","sourceNumber":"339803","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 25 anos procura ambulatório de ginecologia com queixa de dores pélvicas\ntipo cólicas em período menstrual que vem\npiorando há dois anos. GOPO e informa que não usa\nmétodos contraceptivos. Paciente revela irregularidade menstrual coincidente com o início dos\nsintomas álgicos. Finaliza se queixando de desconforto durante o ato sexual. O exame físico\ndemonstra dor à palpação profunda do abdome e desconforto durante o toque ginecológico. De\nacordo com o provável diagnóstico, é CORRETO afirmar que o (a)","options":{"A":"aumento da integrina está associado às sinequias da cavidade uterina.","B":"dismenorreia, nesses casos, se inicia tipicamente 24h após a menstruação.","C":"dispareunia está mais associada ao comprometimento da anatomia ovariana.","D":"dor pode resultar da invasão neuronal dos implantes endometrióticos.","E":"apotose com incompetência oocitária é a melhor teoria para infertilidade."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-337437","number":"337437","sourceNumber":"337437","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 45 anos, tendo como método contraceptivo a esterilização definitiva, com\nquadro de Sangramento Uterino Anormal, é\nsubmetida à histeroscopia. O achado mais frequente\nneste caso é:","options":{"A":"pólipo.","B":"hiperplasia.","C":"atrofia.","D":"mioma submucoso."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-337445","number":"337445","sourceNumber":"337445","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 25 anos com queixa de infertilidade é submetida à\nhisterossalpingografia onde fica evidente\nlesão em ?contas de rosário? em uma das trompas. Esse\nachado sugere como causa:","options":{"A":"Tuberculose.","B":"Endometriose.","C":"Moléstia inflamatória pélvica.","D":"Malformação congênita."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-342656","number":"342656","sourceNumber":"342656","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 35 anos, G1 P0, relata que não conseguiu engravidar após 14 meses,\nmantendo relações sexuais regulares com o marido. O exame físico não detecta alterações\nsignificativas, e o índice de massa corpórea calculado é de 28kg/ m2. A paciente apresenta\nresultado de exame de sangue que demonstra elevação do nível sérico de progesterona na 2a fase\ndo ciclo menstrual. Diante desse quadro, a hipótese provável é a de que a paciente:","options":{"A":"possui reserva folicular ovariana adequada à concepção","B":"é portadora de síndrome dos ovários policísticos","C":"é fértil","D":"apresenta ciclo ovulatório"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-342657","number":"342657","sourceNumber":"342657","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre as doenças miometriais, é correto afirmar que:","options":{"A":"miomas subserosos, pelo risco de sangramento, devem ser extirpados por videolaparoscopia","B":"a adenomiose é causada por sangramento uterino e é facilmente diagnosticada pelo aumento do\nútero no toque vaginal","C":"os miomas são mais frequentes na pós-menopausa","D":"o mioma submucoso tem a ressecção histeroscópica como tratamento preferencial"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-334827","number":"334827","sourceNumber":"334827","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Leia o relato do caso a seguir. MSS, 33 anos de idade, raça negra e nuligesta, casada\nhá 3 anos e há 2 anos tentando engravidar,\ncomparece à consulta ginecológica. Após a anamnese\ne exame físico, foi solicitada ultrassonografia transvaginal que evidenciou nódulo uterino\nhipoecoido\nsubmucoso de 2,0 cm (tipo 0) de diâmetro, compatível com mioma. A paciente apresenta\nsangramento uterino anormal e deseja ter filhos num futuro próximo. De acordo com o caso\nrelatado, qual deve ser a conduta?","options":{"A":"Utilizar análogos de GnRH.","B":"Utilizar pílula anticoncepcional de baixa dosagem.","C":"Miomectomia por via abdominal (laparotomia).","D":"Miomectomia por ressecção endoscópica (histeroscopia)"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-334834","number":"334834","sourceNumber":"334834","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Os miomas são variáveis em número e tamanho e são classificados de acordo com a\nlocalização no útero. A classificação mais utilizada é a da Federação Internacional de Ginecologia e\nObstetrícia (FIGO). De acordo com esta classificação, qual tipo é totalmente subseroso e\npediculado?","options":{"A":"Tipo 0","B":"Tipo 1","C":"Tipo 4","D":"Tipo 7"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-321634","number":"321634","sourceNumber":"321634","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Adolescente de 17 anos, com dismenorreia primária, moderada a grave, sem alterações\ndo fluxo menstrual e sem sexarca tem como\nprimeira escolha o tratamento com os","options":{"A":"anticoncepcionais hormonais combinados em esquema estendido.","B":"anti-inflamatórios não hormonais durante a menstruação.","C":"antiespasmódicos associados aos analgésicos comuns, durante a menstruação.","D":"antiespasmódicos associados aos anti-inflamatórios não esteroidais, durante a menstruação."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-321635","number":"321635","sourceNumber":"321635","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O exame mais sensível para mapear miomas, antes da miomectomia, é","options":{"A":"a ultrassonografia pélvica.","B":"a ultrassonografia endovaginal.","C":"a tomografia computadorizada da pelve.","D":"a ressonância nuclear magnética da pelve."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-321636","number":"321636","sourceNumber":"321636","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A necrobiose asséptica, também conhecida como degeneração rubra ou vermelha,\ncorresponde ao infarto hemorrágico do leiomioma. Esse tipo de degeneração ocorre,\nprincipalmente, durante o uso de","options":{"A":"TH combinada do climatério.","B":"gestrinona.","C":"leuprorrelina.","D":"testosterona."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-308217","number":"308217","sourceNumber":"308217","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 70 anos de idade, GIPIN, menopausada há 14 anos, diabética, hipertensa,\nobesa, com quadro de metrorragia há 3 meses.\nAo exame físico geral e ginecológico não\napresentou qualquer anormalidade. Qual diagnóstico mais provável?","options":{"A":"Miomatose uterina.","B":"Atrofia genital.","C":"Câncer do colo uterino.","D":"Câncer de endométrio."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-308223","number":"308223","sourceNumber":"308223","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 17 anos, sem sexarca, com cólicas menstruais caracterizadas como\ndismenorreia primária, com intensidade que\ndificulta a realização de atividades diárias. Qual seria a\nmelhor conuta nesse caso?","options":{"A":"Uso de antiespasmódicos de ação central.","B":"Uso de anticoncepcionais orais.","C":"Uso de inibidores de prostaglandinas.","D":"Uso de antagonistas de hormônios liberadores de gonadotrofinas."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-300911","number":"300911","sourceNumber":"300911","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em paciente com sangramento uterino anormal, NÃO faz parte do diagnóstico\ndiferencial:","options":{"A":"prenhez ectópica.","B":"miomatose uterina.","C":"cisto de ovário.","D":"abortamento."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-302850","number":"302850","sourceNumber":"302850","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 72 anos de idade, 4G 4P, sem comorbidades, refere apresentar pequeno\nsangramento pela vagina, há uma semana. Ao\nexame físico, vagina, colo do útero e corpo uterino\nestão normais para a idade. O diagnóstico mais provável é de:","options":{"A":"Hiperplasia endometrial típica.","B":"Atrofia endometrial.","C":"Hiperplasia endometrial com atipia.","D":"Carcinoma endometrial.","E":"Pólipo endometrial."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-311927","number":"311927","sourceNumber":"311927","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal procura serviço ginecológico para tirar as dúvidas sobre infertilidade. A mulher\ntem 38 anos e o homem com 45 anos, estão\ntentando engravidar há oito meses com relações\nsexuais duas vezes por semana e sem uso de anticoncepcionais. Nenhum dos dois tem filhos. Qual\na orientação para o casal?","options":{"A":"Realizar mais quatro meses de tentativas para completar um ano.","B":"Solicitar os exames de infertilidade para ambos.","C":"Iniciar uma indução de ovulação para inseminação intrauterina.","D":"Orientar sobre o coito programado guiado pela ultrassonografia."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-311929","number":"311929","sourceNumber":"311929","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Nulípara de 22 anos, procura atendimento médico com queixa de dor durante as\nmenstruações, com piora do quadro há mais de\n6 meses. O médico solicita uma ultrassonografia\nendovaginal que apresenta endometrioma em ovário direito de 4,0 x 4,0 cm, presença de lesão\nsugestiva de endometriose profunda em ligamentos uterossacros, ausência de lesões em ureteres,\nsigmoide e bexiga. No momento, não deseja engravidar. Qual a melhor conduta para essa\nsituação?","options":{"A":"Realização de uma videolaparoscopia para retirada dos focos.","B":"Prescrever anti-inflamatórios somente nos períodos álgicos.","C":"Introdução de anticoncepcional para controle da dor e estabilizar as lesões.","D":"Indicar preservação da fertilidade e operar na sequência."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-316335","number":"316335","sourceNumber":"316335","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A histeroscopia, com ou sem biópsia, têm se mostrado como a técnica propedêutica\n''padrão ouro'' para investigação de afecções da\ncavidade uterina. Assim sendo, assinale abaixo a\nalternativa que não pode ser diagnosticada por essa técnica:","options":{"A":"Adenomiose.","B":"Pólipo endometrial.","C":"Sinéquias uterinas.","D":"Hiperplasia endometrial."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-311930","number":"311930","sourceNumber":"311930","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No pronto socorro de uma maternidade, o médico atende uma mulher de 45 anos com\nqueixa de sangramento vaginal aumentado há 20 dias. Durante a anamnese, ele percebe que ela\npossui esses sangramentos há 6 meses, mesmo tendo ciclos regulares. Exame especular: colo\nepitelizado, sem lesões e fechado, presença de coágulos em fundo de saco. Sinais vitais: PA de\n120/80mmHg, pulsos cheios, frequência cardíaca de 55bpm. Refere já ter feito laqueadura tubária.\nQual o próximo passo para esse caso?","options":{"A":"Solicitar histerossalpingografia para investigação de pólipos e miomas.","B":"Solicitar ultrassonografia endovaginal para investigação das causas uterinas e ovarianas.","C":"Solicitar histeroscopia para investigação da cavidade endometrial.","D":"Solicitar colposcopia para descartar as afecções do colo uterino."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-315821","number":"315821","sourceNumber":"315821","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 60 anos procura ginecologista com queixa de sangramento via vaginal\nhá 1 semana. Refere que a última\nmenstruação foi aos 49 anos e que utilizou terapia de reposição\nhormonal somente nos 3 primeiros anos da menopausa. A mais provável causa do sangramento,\nneste caso, é:","options":{"A":"Atrofia endometrial.","B":"Hiperplasia endometrial.","C":"Pólipo endometrial.","D":"Cervicite crônica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-313237","number":"313237","sourceNumber":"313237","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 35 anos, G0P0, vem referindo dor pélvica cíclica há 5 anos e retorna\nem consulta ginecológica para resultado de\nexame. Nunca fez uso de método contraceptivo.\n\nEcografia transvaginal e abdominal revela cisto ovariano de conteúdo espesso com 3cm e nódulo\nna região do ureter direito, com hidronefrose\nleve à direita. A conduta é:","options":{"A":"prescrever contraceptivo oral combinado contínuo por 3 meses e repetir ecografia","B":"prescrever acetato de medroxiprogesterona intramuscular e repetir ecografia em 3 meses","C":"realizar exérese cirúrgica do cisto e do nódulo","D":"prescrever progestogênio oral contínuo e repetir ecografia em 6 meses"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-294306","number":"294306","sourceNumber":"294306","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 40 anos com queixa de que, após a laqueadura tubária, há cerca de quatro\nanos, passou a apresentar sangramento genital\ncaracterizado por aumento da menstruação e\nperda da ciclicidade. Há cerca de quatro meses, vem apresentando piora do quadro, após iniciar o\nuso de anticoagulante oral, para tratar trombose venosa profunda. Tem antecedentes de três\ngestações com partos normais: Ao exame ginecológico e ultrassonográfico, verifica-se útero com\nvolume e aspecto normais. Diante deste quadro, a hipótese diagnóstica mais provável e o\ntratamento inicial são, respectivamente:","options":{"A":"sangramento uterino estrutural - ácido mefenâmico.","B":"sangramento uterino estrutural - anticoncepcional oral.","C":"sangramento uterino não estrutural - análogo do GnRH.","D":"sangramento uterino não estrutural - ácido tranexâmico."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-317980","number":"317980","sourceNumber":"317980","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 42 anos de idade com queixa de que, há cerca de dois anos, vem\napresentando sangramento uterino anormal,\ncaracterizado por aumento da duração e do volume\ndas menstruações, associado à dismenorreia secundária. Tem antecedentes de três gestações,\ntodos partos normais e laqueadura tubária. Apresenta resultado do exame de ultrassonografia\nendovaginal mostrado a seguir. Neste caso, a hipótese diagnóstica mais provável é de","options":{"A":"pólipo endometrial.","B":"mioma submucoso.","C":"hiperplasia endometrial.","D":"câncer de endométrio."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":["question_bank/media/medcurso/medcurso-gineco-gin-2/317980.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-294307","number":"294307","sourceNumber":"294307","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 35 anos, nuligesta, sem sexarca, com aumento do volume menstrual\nassociado a piora da dismenorreia, sem causa estrutural, deve iniciar o tratamento com","options":{"A":"ácido mefenâmico, durante a menstruação.","B":"ácido tranexâmico, durante a menstruação.","C":"anticoncepcional hormonal combinado, injetável.","D":"anticoncepcional hormonal combinado, oral."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-313240","number":"313240","sourceNumber":"313240","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 32 anos, com dispareunia de profundidade e dor pélvica crônica, foi\ndiagnosticada com retroversão uterina fixa. Dentre as afecções a seguir,aquelas que poderiam\nlevar a uma retroversão fixa são:","options":{"A":"mioma subseroso volumoso e prolapso uterino","B":"endometriose e sequela de Doença Inflamatória Pélvica Aguda (DIPA)","C":"adenomiose e hiperplasia endometrial","D":"teratomas ovarianos e retocolites"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-295397","number":"295397","sourceNumber":"295397","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O sangramento uterino anormal (SUA) também é definido como perda menstrual\nexcessiva com repercussões físicas,\nemocionais, sociais e materiais na qualidade de vida da\nmulher, que podem ocorrer isoladamente ou em combinação com outros sintomas. Representa um\nproblema individual e também um problema de saúde pública. Em relação à classificação PALM\nCOEIN do SUA da FIGO (2011), sabe-se que a letra","options":{"A":"P significa pélvica e é uma causa não estrutural.","B":"A significa anovulação e é uma causa orgânica.","C":"E significa endometrial ou fatores locais no endométrio.","D":"O significa causas de origem de coagulopatias."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-313255","number":"313255","sourceNumber":"313255","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente com 42 anos, G3P3A0 (3PN), submetida a laqueadura tubária há 5 anos,\napresenta aumento do fluxo e da duração da menstruação há 6 meses. Refere fraqueza e malestar\ngeral durante o sangramento. Ao exame clínico, apresenta útero aumentado de tamanho. USG TV\nrevela útero AVF, centrado e com volume de 425cm:, além de nódulo único, intramural e fúndico de\n8cm no maior diâmetro. Hb = 9,8 e Ht = 27%. Refere que, há 10 meses, vem tentando controlar o\nsangramento com medicações hormonais (desogestrel oral e medroxiprogesterona injetável), sem\nsucesso. A melhor conduta para essa paciente é: :","options":{"A":"histerectomia total vaginal","B":"miomectomia laparoscópica","C":"histerectomia total abdomina!","D":"miomectomia histeroscópica"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-274446","number":"274446","sourceNumber":"274446","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O local mais comum de endometriose extrapélvica é:","options":{"A":"Cardiovascular.","B":"Aparelho respiratório.","C":"Cérebro.","D":"Trato gastrintestinal."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-265844","number":"265844","sourceNumber":"265844","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em pacientes com sangramento uterino anormal, o uso do ácido tranexâmico\n(Transamin®) é CONTRAINDICADO caso a paciente tenha:","options":{"A":"doença tromboembólica ativa.","B":"doença de Von Willembrand.","C":"insuficiência renal.","D":"insuficiência cardíaca."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-285078","number":"285078","sourceNumber":"285078","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre o risco de aparecimento dos miomas uterinos é correto afirmar, exceto:","options":{"A":"O tabagismo reduz o risco de miomas uterinos.","B":"O uso de pílula anticoncepcional por longo tempo aumenta o risco de miomas uterinos.","C":"A obesidade aumenta o risco de miomas uterinos.","D":"Multíparas têm menor risco de miomas uterinos que nuligestas.","E":"A terapia hormonal do climatério aumenta o risco de reaparecimento dos miomas."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-274781","number":"274781","sourceNumber":"274781","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher, 35 anos, nulipara recebe o diagnóstico de câncer de mama, com mutação do\nBRCA1. O tratamento do câncer será com cirurgia, radio e quimioterapia. A paciente quer saber\nsobre a repercussão desse tratamento na sua vida reprodutiva, o que você pode informar:","options":{"A":"os ovários são resistentes à quimioterapia.","B":"é possível realizar a preservação da fertilidade com a coleta de ovários prévia.","C":"não há tempo de fazer a preservação devido a gravidade do câncer de mama.","D":"os ovários são resistentes à radioterapia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-277435","number":"277435","sourceNumber":"277435","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 27 anos, nuligesta, sem uso de método anticoncepcional há 2 anos,\nprocura assistência médica para tratamento de\ninfertilidade. Queixa-se de dor pélvica, dismenorréia\ne dispareunia crônicas. O exame ginecológico revela: desconforto ao exame especular, colo uterino\nde aspecto normal, nodulação dolorosa no fundo de saco posterior e espessamento dos ligamentos\nuterossacros. Diante deste quadro clínico, considerando a suspeita de endometriose, é correto\nafirmar que:","options":{"A":"o diagnóstico definitivo é obtido pela ressonância magnética pélvica, preferencialmente com\npreparo intestinal","B":"o marcador CA-125 é considerado de eleição para firmar o diagnóstico de endometriose,\nprincipalmente quando os valores são superiores há 95UI/ml","C":"os endometriomas ovarianos não respondem bem ao tratamento medicamentoso, sendo a\ncirurgia indicada nos casos de endometriomas sintomáticos ou grandes","D":"os locais mais comumente comprometidos pela endometriose pélvica são, respectivamente,\nligamentos uterossacros, fundo de saco posterior,\novários e fundo de saco anterior e folheto\nposterior do ligamento largo."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-274788","number":"274788","sourceNumber":"274788","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher obesa de 60 anos, sem uso de terapia hormonal, procura atendimento com\nqueixa de sangramento vaginal de pequeno volume há 7 dias. Tem Papanicolau colhido\nrecentemente normal. Qual o exame inicial para investigação desse sangramento?","options":{"A":"Dosagens hormonais.","B":"Histeroscopia.","C":"Histerossalpingografia.","D":"Ecografia transvaginal."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-274798","number":"274798","sourceNumber":"274798","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre a histerossalpingografia, podemos detectar as alterações nesse exame:","options":{"A":"mioma submucoso e malformações mullerianas.","B":"alterações tubárias e endometrioma.","C":"mioma subseroso e adenomiose.","D":"sinéquias uterinas e distopia genital."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-257771","number":"257771","sourceNumber":"257771","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 30 anos, com quadro clínico de sangramento uterino anormal rebelde ao\ntratamento clínico, mostra à ultrassonografia\num mioma com cerca de 50% de penetração no\nmiométrio, base de 1/2, ocupando a cavidade endometrial, no terço superior da parede lateral\nesquerda do útero e com cerca de 3 cm o maior diâmetro. Nesse caso, de acordo com a\nclassificação PALM-COEIN (Federação Internacional de Ginecologia e Obstetrícia), o tratamento de\nescolha, é a","options":{"A":"histerectomia por laparotomia.","B":"miomectomia por laparotomia.","C":"miomectomia por laparoscopia.","D":"miomectomia antecedida por análogo do GnRH."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-257772","number":"257772","sourceNumber":"257772","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O ácido tranexâmico tem sido utilizado no tratamento de sangramentos uterinos\nanormais. O seu mecanismo de ação consiste em","options":{"A":"aumentar o fibrinogênio.","B":"reduzir a fibrinólise.","C":"acelerar a degradação de fibrina.","D":"ativar o sistema fibrinolítico."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-257777","number":"257777","sourceNumber":"257777","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma adolescente de 14 anos começou a menstruar há um ano. Agora, tem\nsangramento uterino anormal, com ciclos\nmenstruais que duram entre dois e sete dias, com\nintervalos de duas a seis semanas. A quantidade de sangramento varia de um gotejamento mínimo\na um fluxo muito intenso. No exame físico, não há achados dignos de nota. A ultrassonografia\npélvica não aponta anormalidades. Nesse caso, a maior probabilidade de produzir tais achados é:","options":{"A":"pólipo endometrial.","B":"ciclos anovulatórios.","C":"gravidez ectópica.","D":"carcinoma endometrial."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252727","number":"252727","sourceNumber":"252727","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 45 anos, gesta 2 para 2, assintomática, com ciclos menstruais regulares e\neumenorreicos, foi submetida à ultrassonografia pélvica sob alegação de \"rotina ginecológica\". Este\nexame mostrou útero medindo cerca de 15% acima do esperado, às custas de dois nódulos de\nmioma subseroso, cada um medindo cerca de 2,5 cm de diâmetro. É correto afirmar que:","options":{"A":"O achado não surpreende, em vista da elevada prevalência dos miomas e pelo fato de a maioria\ndos casos ser assintomática.","B":"Se esta paciente necessitasse de anticoncepcional, os métodos hormonais estariam\ncontraindicados à custa do achado ultrassonográfico.","C":"Há clara indicação de histerectomia em função do tamanho uterino.","D":"Não há indicação de histerectomia, mas, sim, de miomectomia para estudo anatomopatológico\ndos nódulos."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252728","number":"252728","sourceNumber":"252728","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A causa mais frequente de sangramento uterino na pós-menopausa é:","options":{"A":"Pólipo endometrial.","B":"Endométrio atrófico.","C":"Hiperplasia de endométrio.","D":"Carcinoma de endométrio."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252729","number":"252729","sourceNumber":"252729","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Jovem de 19 anos, estudante universitária, nuligesta, procura atendimento ginecológico\nqueixando-se de cólicas menstruais, principalmente no primeiro dia, com moderada intensidade e\nque normalmente não a incapacitam. Nega surgimento da dor antes do fluxo menstrual. Informa\nque as cólicas se tornaram mais frequentes nos últimos anos, justamente quando os ciclos\nmenstruais passaram a ser mais regulares. Tomou antiespasmódicos comuns indicados por sua\nmãe, mas sem bons resultados. Refere atividade sexual esporádica, quando usa preservativo e\nnega dispareunia. Ao exame ginecológico, nada digno de nota.","options":{"A":"A produção endometrial aumentada de prostaglandinas encontra-se na base da fisiopatologia\ndesse distúrbio.","B":"Apesar da vida sexual, a pílula anticoncepcional deve ser evitada neste caso, pois é sabido que\npode piorar os sintomas.","C":"Antes de qualquer iniciativa de tratamento, é obrigatório realizar exame de ultrassonografia\npélvica.","D":"A laparoscopia se impõe para descartar endometriose em casos desse tipo."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-252730","number":"252730","sourceNumber":"252730","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 53 anos, na pós-menopausa, obesa, diabética, nulípara, refere sangramento\nvaginal há três dias. Exame ginecológico:\nvagina e colo uterino sem alterações; corpo uterino não\nidentificado ao toque. Ultrassonografia: corpo uterino aumentado e endométrio de 13 mm de\nespessura. A conduta é:","options":{"A":"Terapia hormonal combinada contínua.","B":"Histerectomia.","C":"Repetição do ultrassom em 6 meses.","D":"Histerectomia ou curetagem semiótica."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-231954","number":"231954","sourceNumber":"231954","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 30 anos, nuligesta, sem métodos contraceptivos há cerca de 3 anos,\napresenta queixa de dismenorreia intensa e dor pélvica cíclica intermenstrual. No exame vaginal foi\nobservado nódulo violáceo em fundo de saco, doloroso à mobilização. O diagnóstico mais provável\né:","options":{"A":"adenomiose","B":"endometriose","C":"miomatose uterina","D":"carcinoma ovariano com infiltração local","E":"carcinoma endometrial com infiltração local"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-231955","number":"231955","sourceNumber":"231955","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 47 anos, G3P3, da raça negra, refere menstruações prolongadas e em\nvolume abundante e realizou laqueadura tubária no último parto. Ao toque vaginal, útero de\ndimensões aumentadas. A ultrassonografia pélvica e transvaginal revelou volume uterino\naumentado (180cm3) e presença de 4 nódulos sólidos bem delimitados na espessura do miométrio,\ncom diâmetros médios de 3,5cm, 2,1cm, 1,1cm e 0,9cm, respectivamente. É correto afirmar que:","options":{"A":"certamente, o uso de progestogênio em baixa dose bloquearia o crescimento desses nódulos","B":"trata-se de neoplasia cujo crescimento é estimulado pelo estrogênio, e os análogos do GnRH\nestariam bem indicados para evitar a abordagem cirúrgica","C":"está contraindicado de forma absoluta o uso de pílula anticoncepcional hormonal do tipo\ncombinada","D":"em decorrência da prole já estar constituída, a histerectomia é considerada tratamento de 1º\nescolha","E":"alguns tipos de esteroides sexuais podem ser uma boa opção terapêutica para as manifestações\ndessa doença, embora não sejam curativos"},"answer":"E","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-247440","number":"247440","sourceNumber":"247440","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 37 anos e prole constituída apresenta hipermenorreia de longa duração. O\nexame de ultrassonografia transvaginal\nmostra imagem sugestiva de pólipo endometrial de 8 mm. A\nconduta preferencial para este caso é:","options":{"A":"histerectomia total.","B":"ablação endometrial.","C":"histeroscopia e biópsia.","D":"curetagem uterina."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-248951","number":"248951","sourceNumber":"248951","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 22 anos, nuligesta e sem desejo reprodutivo, com dismenorreia\nprogressiva desde a menacma, há 3 anos apresenta\nquadro de dor pélvica crônica e dispareunia\nacentuada. Foi indicada laparoscopia para tratamento cirúrgico por dificuldade no controle clínico\nda dor, sendo realizadas fulguração dos focos de endometriose superficial peritoneal e exérese de\nlesão profunda retrocervical de cerca de 2cm. Não há outras anormalidades identificadas na\nlaparoscopia. Qual é a alternativa correta no tratamento adjuvante?","options":{"A":"danazol contínuo","B":"desogestrel contínuo","C":"análogo de GnRH por 6 meses","D":"anti-inflamatório pré-menstrual"},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-248952","number":"248952","sourceNumber":"248952","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual é a causa mais comum de infertilidade por fator tuboperitoneal?","options":{"A":"malformação uterina","B":"endometriose","C":"doença inflamatória pélvica","D":"tuberculose genital"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234364","number":"234364","sourceNumber":"234364","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A dismenorreia é uma desordem que afeta a mulher na menacme, interferindo na\nqualidade de vida e nas atividades habituais. A dismenorreia, então:","options":{"A":"É uma desordem ginecológica rara que afeta menos de 5% das mulheres na menacme.","B":"Consiste em dor acíclica tipo cólica no hipogástrico, que surge fora do período menstrual.","C":"É classificada como primária, quando não há doença pélvica, e secundária, quando existe\ndoença de base.","D":"Apresenta contraindicação ao uso de contraceptivos hormonais no tratamento, quando primária."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234365","number":"234365","sourceNumber":"234365","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Algumas desordens ginecológicas, como a síndrome pré-menstrual, o mioma uterino e\no sangramento uterino anormal, afetam milhares de\nmulheres, ocasionando transtornos\nemocionais, sintomatologia dolorosa e anemia. Entre essas desordens:","options":{"A":"A síndrome pré-menstrual é definida como cefaleia que se inicia na fase folicular do ciclo\nmenstrual.","B":"O mioma uterino é o principal fator de Sangramento Uterino Sem Causa Aparente (SUSCA).","C":"O Sangramento Uterino Disfuncional (SUD) apresenta contraindicação de uso de\nanti-inflamatórios no tratamento.","D":"O Sangramento Uterino Disfuncional (SUD) é o sangramento uterino relacionado com disfunção\nendócrina (insuficiência lútea ou anovulação)."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234366","number":"234366","sourceNumber":"234366","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O mioma é um tumor da camada muscular do útero, que pode se localizar em várias\nregiões uterinas, ocasionando dor, sangramento, anemia e com baixo potencial de transformação\nsarcomatosa. O conhecimento de sua fisiopatologia é essencial para o tratamento correto. Dessa\nforma,","options":{"A":"O mioma uterino é um tumor benigno originário da fibra muscular lisa do útero.","B":"O estudo histológico do mioma mostra feixes musculares lisos entrelaçados em diversas\ndireções, com atipias, várias mitoses e muita necrose.","C":"O mioma subseroso ocorre quando a maior porção do tumor se encontra abaixo do endométrio,\ndentro da cavidade endometrial.","D":"O tratamento dos miomas está restrito à histerectomia."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234367","number":"234367","sourceNumber":"234367","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A adenomiose foi referida no passado como cystosarcoma adenoids uterinum. Na\nmaioria das mulheres, os primeiros sintomas podem surgir na adolescência e permanecer na\nmenacme. Em geral, o diagnóstico é feito por achados de histopatologia de peças cirúrgicas. A\nadenomiose caracteriza-se por:","options":{"A":"Ser uma condição maligna do útero.","B":"Apresentar estroma e glândulas endometriais situadas ectopicamente no miométrio.","C":"Ser mais comum em nulíparas do que em multíparas.","D":"Apresentar glândulas endometriais no colo uterino, nas tubas e nos ovários."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-234368","number":"234368","sourceNumber":"234368","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O conhecimento da embriologia sobre a formação gonadal e desenvolvimento do seio\nurogenital, e sua fisiologia, é fundamental para a compreensão das alterações genitais, desordens\nsexuais e do crescimento. Este conhecimento básico é o alicerce para o entendimento das teorias\nda endometriose e dos transtornos do climatério. Com base nesse conhecimento:","options":{"A":"A endometriose é uma doença geralmente benigna, caracterizada por implantes de tecido\nendometrial em regiões extrauterinas.","B":"A menopausa é definida como interrupção permanente da menstruação após seis meses de\namenorreia.","C":"A puberdade precoce consiste no aparecimento de caracteres sexuais secundários antes dos 10\nanos, em meninas.","D":"A formação gonadal inicia-se entre a 15ª e 16ª semanas de gestação, com desenvolvimento do\nseio urogenital a partir do ectoderma."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-249527","number":"249527","sourceNumber":"249527","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No acompanhamento de um casal infértil, com exame de espermograma normal e\ndosagem hormonal adequada, compatível com ovulação, o próximo passo na propedêutica é:","options":{"A":"teste pós-coito.","B":"histerossalpingografia.","C":"histeroscopia com biopsia de endométrio.","D":"ultrassom seriado."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-241755","number":"241755","sourceNumber":"241755","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente multípara, sem queixas, comparece ao consultório ginecológico com achado\necográfico e mioma uterino, de localização subserosa, em fundo uterino, medindo 1 cm. O exame\nginecológico confirma útero intrapélvico, de pequeno volume. Qual o procedimento mais\nadequado?","options":{"A":"Manter conduta expectante.","B":"Indicar histerectomia por via vaginal.","C":"Indicar histerectomia por via abdominal.","D":"Indicar miomectomia por via laparoscópica.","E":"Indicar miomectomia por via laparotômica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-241756","number":"241756","sourceNumber":"241756","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 55 anos de idade, com menopausa aos 50 anos, assintomática e não fez uso\nde terapia hormonal, apresenta sangramento\nuterino em pouca quantidade, com aspecto em borra\nde café. Assinale a causa mais frequente de sangramento uterino anormal na pós-menopausa.","options":{"A":"Câncer de endométrio.","B":"Hiperplasia endometrial.","C":"Atrofia endometrial.","D":"Pólipo endometrial.","E":"Sarcoma Uterino."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-241757","number":"241757","sourceNumber":"241757","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 39 anos, com infertilidade primária há 4 anos. Qual dos seguintes exames\nnão deve ser solicitado como investigação\nbásica inicial?","options":{"A":"Espermograma.","B":"Laparoscopia diagnóstica.","C":"Histerossalpingografia.","D":"Ultrassom endovaginal.","E":"FSH no terceiro dia do ciclo."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-241758","number":"241758","sourceNumber":"241758","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O mioma uterino é patologia frequente na população brasileira, acometendo de 30 a\n50% das mulheres. Em relação a essa enfermidade, assinale a alternativa correta.","options":{"A":"Todas as pacientes com mioma uterino, devido à elevada chance de desenvolvimento de tumor\nmaligno, devem realizar ressonância magnética e histeroscopia com biópsia.","B":"É a causa mais frequente de sangramento uterino em todas as faixas etárias.","C":"A miomectomia deve ser a primeira escolha nas pacientes nuligestas e a histerectomia nas\npacientes com prole completa, mesmo nos miomas assintomáticos.","D":"Os sintomas que geralmente indicam seu tratamento estão relacionados com a localização e o\ntamanho do mioma.","E":"É causa absoluta de sangramento vaginal."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-232278","number":"232278","sourceNumber":"232278","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A classificação PALM-COEIN, da Federação Internacional de Ginecologia e Obstetrícia\n(FIGO) para sangramentos uterinos, define\ncomo tratamento de primeira linha para, o sangramento\nuterino em mulheres de baixo risco para câncer de endométrio, com ultrassonografia normal,\nexcluídas as causas estruturais e comorbidades, os","options":{"A":"progestágenos ciolícos.","B":"anticoncepcionais orais combinados.","C":"antifibrinolíticos, em especial o ácido tranexâmico.","D":"anti-inflamatórios, principalmente o ácido mefenâmico."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-232279","number":"232279","sourceNumber":"232279","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 33 anos, nuligesta, apresenta sangramento\nuterino anormal caracterizado por aumento da\nquantidade e duração, associado a dismenorreia\nsecundária. A ultrassonografia mostra mioma em parede lateral direita do 1/3 inferior do útero, com\nmaior diâmetro de 2cm, com penetração de 20% no miométrio e base de 1/3 (Score=1,\nclassificação STEP=w). Diante deste quadro, a opção terapêutica é:","options":{"A":"uso de anticoncepcionais orais.","B":"ressecção histeroscópica.","C":"análogo do GnRH com posterior ressecção histeroscópica.","D":"miomectomia tradicional."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-229891","number":"229891","sourceNumber":"229891","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à miomatose uterina.","options":{"A":"Nos miomas subserosos, a histeroscopia constitui o tratamento de escolha.","B":"A progesterona é a droga mais eficaz no tratamento clínico de miomas.","C":"Em mulheres climatéricas, mesmo que assintomáticas, a conduta cirúrgica é imperativa.","D":"Mulheres nulíparas têm maior risco de desenvolvimento de miomas."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214172","number":"214172","sourceNumber":"214172","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Na rotina de avaliação inicial do casal infértil, dentre os exames relacionados abaixo,\npode-se considerar desnecessário","options":{"A":"as dosagens hormonais.","B":"o espermograma.","C":"a ultrassonografia transvaginal.","D":"a laparoscopia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214107","number":"214107","sourceNumber":"214107","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 19 anos, nulípara, assintomática, realizou ultrassonografia transvaginal, sendo\nidentificada imagem nodular localizada na espessura da parede uterina, medindo 2 cm,\nhipoecogênica, com sinal de sombra acústica posterior e sem comprometimento da cavidade\nendometrial. Neste caso a hipótese diagnóstica é","options":{"A":"pólipo endometrial.","B":"mioma submucoso.","C":"mioma intramural.","D":"adenomiose."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214114","number":"214114","sourceNumber":"214114","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 19 anos, nulípara, assintomática, realizou ultrassonografia transvaginal, sendo\nidentificada imagem nodular localizada na espessura da parede uterina, medindo 2 cm,\nhipoecogênica, com sinal de sombra acústica posterior e sem comprometimento da cavidade\nendometrial. Neste caso o tratamento mais adequado é","options":{"A":"observação clínica.","B":"miomectomia.","C":"prostagenio oral contínuo.","D":"histerectomia."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214127","number":"214127","sourceNumber":"214127","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 18 anos, G0 P0, histórico de ciclos menstruais regulares, sem cólicas, e com\nduração do fluxo de cinco dias, sendo mais intenso nos três primeiros dias do ciclo e em pequena\nquantidade nos últimos dois dias. Procurou a emergência, acompanhada pelo namorado. Refere\nque iniciou quadro de hemorragia genital intensa e súbita, há 3 horas, associado a palidez de\nmucosas, hipotensão arterial e astenia. Relatou estar no 8º dia do ciclo menstrual e que o\nsangramento iniciou logo após o coito, nega uso prévio de mediações e refere boa saúde. Utiliza\ncondon como método contraceptivo. Neste caso a hipótese diagnóstica é","options":{"A":"laceração de fundo de saco vaginal.","B":"abortamento em curso.","C":"sangramento uterino disfuncional.","D":"miomatose uterina."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214136","number":"214136","sourceNumber":"214136","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente 18 anos, G0 P0, histórico de ciclos menstruais regulares, sem cólicas, e com\nduração do fluxo de cinco dias, sendo mais intenso nos três primeiros dias do ciclo e em pequena\nquantidade nos últimos dois dias. Procurou a emergência, acompanhada pelo namorado. Refere\nque iniciou quadro de hemorragia genital intensa e súbita, há 3 horas, associado a palidez de\nmucosas, hipotensão arterial e astenia. Relatou estar no 8º dia do ciclo menstrual e que o\nsangramento iniciou logo após o coito, nega uso prévio de mediações e refere boa saúde. Utiliza\ncondon como método contraceptivo. Neste caso a conduta a ser tomada é","options":{"A":"exame especular.","B":"teste de Gravidez.","C":"ultrassonografia.","D":"exames hormonais (FSH, LH, Estradiol, Prolactina, TSH)."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-216623","number":"216623","sourceNumber":"216623","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Homem de 28 anos, chega ao consultório com queixa de infertilidade. Ao exame físico\nfoi diagnosticado uma varicocele de grau 3 e o\ntestículo esquerdo apresentava-se diminuído em\nrelação ao direito. A respeito da varicocele, tem-se o seguinte:","options":{"A":"É mais comum à direita, pela drenagem venosa ser direta para veia cava.","B":"Sempre é bilateral, por ser uma má formação vascular.","C":"É mais comum à esquerda, pela drenagem venosa ser direta na veia renal esquerda.","D":"É mais comum à esquerda, pela má formação venosa valvar."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214175","number":"214175","sourceNumber":"214175","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Segundo a Organização Mundial de Saúde (OMS), 15% da população mundial em\nidade fértil sofrem de problemas\nrelacionados à infertilidade. Dentre as causas da infertilidade não\npode ser considerada a causa comum desta patologia:","options":{"A":"Ovários policísticos.","B":"Hiperprolactinemia.","C":"Oligoastenozoospermia.","D":"Salpingectomia unilateral."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-216617","number":"216617","sourceNumber":"216617","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Adolescente, 13 anos, apresenta ciclo menstrual com intervalos irregulares, com\nduração e fluxos excessivos. A hipótese mais provável para as alterações menstruais na\nadolescente é:","options":{"A":"Presença de tumores ovarianos.","B":"Imaturidade do eixo hipotálamo-hipofisário.","C":"Ocorrência de coagulopatias.","D":"Uso de fármacos."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-216474","number":"216474","sourceNumber":"216474","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 49 anos, nuligesta, com Sangramento Uterino Anormal (SUA) há dois anos,\ncaracterizado por alterações dos intervalos, episódios hipermenorragia e dismenorreia ocasional,\nmostrando na ultrassonografia útero com volume de 190 cm³, com nódulos hipoecoicos subserosos\ne ovários normais, tem como principal hipótese diagnóstica para o SUA:","options":{"A":"Miomas uterinos.","B":"Endometriose.","C":"Adenomiose.","D":"Perimenopausa."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-201665","number":"201665","sourceNumber":"201665","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Leia o caso clínico a seguir. Uma paciente multípara, de 45 anos, apresentou\nsangramento uterino anormal há aproximadamente\noito meses. O exame ginecológico evidencia\nútero aumentado de volume e globoso. A paciente refere dismenorreia intensa associada. Nesse\ncaso, qual é o diagnóstico mais provável?","options":{"A":"Câncer de colo uterino.","B":"Adenomiose.","C":"Endometriose.","D":"Doença inflamatória pélvica aguda."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214917","number":"214917","sourceNumber":"214917","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 35 anos, G1 P0, relata que não conseguiu engravidar após 14 meses,\nmantendo relações sexuais regulares com o marido. O exame físico não detecta alterações\nsignificativas, e o índice de massa corpórea calculado é de 28kg/ m2. A paciente apresenta\nresultado de exame de sangue que demonstra elevação do nível sérico de progesterona na 2a fase\ndo ciclo menstrual. Diante desse quadro, a hipótese provável é a de que a paciente:","options":{"A":"possui reserva folicular ovariana adequada à concepção","B":"é portadora de síndrome dos ovários policísticos","C":"é fértil","D":"apresenta ciclo ovulatório"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-214923","number":"214923","sourceNumber":"214923","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre as doenças miometriais, é correto afirmar que:","options":{"A":"miomas subserosos, pelo risco de sangramento, devem ser extirpados por videolaparoscopia","B":"a adenomiose é causada por sangramento uterino e é facilmente diagnosticada pelo aumento do\nútero no toque vaginal","C":"os miomas são mais frequentes na pós-menopausa","D":"o mioma submucoso tem a ressecção histeroscópica como tratamento preferencial"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-215379","number":"215379","sourceNumber":"215379","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Na propedêutica do casal infértil, não faz parte do arsenal de investigação de\npermeabilidade tubária:","options":{"A":"Ultrassom pélvico.","B":"Imunofluorescência para Clamídia.","C":"Histerossalpingografia.","D":"Histerossonografia."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-175403","number":"175403","sourceNumber":"175403","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Qual dos achados ultrassonográficos a seguir não se correlaciona com a queixa de\nirregularidade menstrual?","options":{"A":"adenomiose uterina","B":"miomatose uterina","C":"pólipo endometrial","D":"hidrossalpinge","E":"cisto ovariano"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-175407","number":"175407","sourceNumber":"175407","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O uso de agonistas do GnRH (hormônios liberadores da gonadotrofinas) está indicado\npara:","options":{"A":"diminuir o sangramento menstrual a fim de melhorar a anemia antes da cirurgia","B":"facilitar a dissecção dos miomas uterinos ao tornar os planos cirúrgicos mais distritos","C":"preservar a fertilidade em mulheres com miomas uterinos intramurais de pequeno volume","D":"tratar mulheres na perimenopausa, permitindo realizar a cirurgia na pós-menopausa"},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-187701","number":"187701","sourceNumber":"187701","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A endometriose é uma importante causa de dor pélvica e é definida como a presença\nde:","options":{"A":"Células foliculares na cavidade endometrial.","B":"Células da junção escamocolunar (JEC) na cavidade endometrial.","C":"Tecido miometrial fora do útero.","D":"Tecido endometrial (glândulas e estroma) fora do útero."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-185136","number":"185136","sourceNumber":"185136","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Atualmente, os leiomiomas uterinos ocupam posição de destaque na saúde pública\ndevido à sua alta prevalência.Sobre a leiomiomatose, constata-se que:","options":{"A":"a exposição ao estrogênio eleva o risco de miomatose.","B":"a incidência é maior em paciente acima de 50 anos.","C":"a maioria dos leiomiomas são sintomáticos.","D":"os análogos de GNRH são uma nova opção de tratamento, diminuindo a intervenção cirúrgica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-182480","number":"182480","sourceNumber":"182480","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 36 anos, assintomática, está se preparando para engravidar e é\nportadora de 2 nódulos identificados como\nmiomas intramurais, sendo um com 3cm e outro com\n4cm, localizados na parede posterior do útero. Diante desse quadro, a conduta é:","options":{"A":"miometrectomia por videolaparoscopia","B":"miomectomia por laparotomia","C":"expectante","D":"agonistas do GnRH por curto período, até liberar para gestação"},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-173594","number":"173594","sourceNumber":"173594","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 42 anos procura a emergência de atendimento ginecológico por apresentar\nsangramento uterino intenso no período menstrual, dismenorreia intensa agravada no último ano e\ndispareunia, que torna a atividade sexual um grande sofrimento pela dor. O grupo em que essa\ndoença pode ser considerada pela classificação PALM-COEIM, de acordo com a FIGO, o\ndiagnóstico e a alteração uterina que pode ser encontrada no exame de toque vaginal são,\nrespectivamente:","options":{"A":"grupo de PALM, diagnóstico de leiomioma, útero de consistência amolecida.","B":"grupo de PALM, diagnóstico de adenomiose, útero doloroso e superfície lisa.","C":"grupo de COEIM, diagnóstico de endometriose, útero doloroso.","D":"grupo de COEIM, diagnóstico de câncer de endométrio avançado, útero de tamanho normal."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-173586","number":"173586","sourceNumber":"173586","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 39 anos, com prole definida, apresenta sangramento menstrual\naumentado, dismenorreia, anemia que não melhora\ncom medicação, foi submetida à\nultrassonografia, que mostrou presença de nódulo localizado parcialmente na cavidade uterina,\nmedindo 6 cm, com mais de 50% intramural, evidenciando também três nódulos regulares de baixa\necogenicidade e intramurais. O volume do útero mediu 198 cm³. O diagnóstico e a conduta\ndefinitiva são:","options":{"A":"polipo endometrial histerectomia vaginal.","B":"leiomiomas e histerectomia vaginal.","C":"adenomiose e histerectomia abdominal.","D":"leiomiomas e histerectomia abdominal."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-174123","number":"174123","sourceNumber":"174123","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sangramento uterino anormal no menacme, com perda da ciclicidade, associado a\nperíodos de amenorreia, com FSH, TSH e prolactina normais, sem prole definida, tem como\nprimeira opção terapêutica","options":{"A":"a ablação de endométrio.","B":"os anti-inflamatórios não hormonais.","C":"os antifibrinolíticos.","D":"os anticoncepcionais hormonais."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-174091","number":"174091","sourceNumber":"174091","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 30 anos, nuligesta, com sangramento menstrual aumentado em relação à\nquantidade e duração, associado a dismenorreia secundária, apresenta, à ultrassonografia\nendovaginal, imagem de mioma submucoso com maior diâmetro de 2 cm. A terapêutica adequada\né:","options":{"A":"anti-inflamatório não hormonal.","B":"anticoncepcional hormonal.","C":"embolização do mioma.","D":"ressecção histeroscópica."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-174429","number":"174429","sourceNumber":"174429","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A morfologia espermática anormal é chamada de:","options":{"A":"Astenospermia.","B":"Oligospermia.","C":"Teratozoospermia.","D":"Azoospermia."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-183249","number":"183249","sourceNumber":"183249","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O melhor dia do ciclo menstrual para realização de biópsia para avaliação de ovulação\né o:","options":{"A":"primeiro dia","B":"quinto dia","C":"oitavo dia","D":"vigésimo sexto dia"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-183306","number":"183306","sourceNumber":"183306","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 54 anos, menopausa há 5 anos, fazendo uso de Terapia de Reposição\nHormonal com Estrógeno+Progesterona.\nComparece ao consultório referindo sangramento via\nvaginal de pequena quantidade há 3 dias. Ao exame clínico, colo uterino regular, sangramento\ndiscreto, útero AVF de tamanho normal. Ultrassom endovaginal demonstrando endométrio regular\nde 9 mm. A melhor conduta a seguir é:","options":{"A":"Tranquilizar a paciente, explicando que é normal esse tipo de ocorrência em usuárias de TRH e\nrepetir o ultrassom em 1 ano.","B":"Solicitar histeroscopia.","C":"Complementar a ultrassonografia com Ressonância Magnética.","D":"Indicar curetagem uterina de imediato devido aos riscos de câncer de endométrio."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-156492","number":"156492","sourceNumber":"156492","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A principal classificação de endometriose é a da Sociedade Americana de Medicina\nReprodutiva (ASRM). Segundo esta classificação esta doença divide-se em:","options":{"A":"Três estágios: I - mínima, II - moderada e III - Severa","B":"Quatro estágios: I - mínima, II - leve, III - moderada e IV - severa","C":"Cinco estágios: I - mínima, II - leve, III - moderada, IV - severa e V - grave profunda).","D":"Seis estágios: I - mínima, II - leve, III - moderada, IV - severa, V - grave (profunda) e VI -\nCom\ncomprometimento de intestino e bexiga."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-156499","number":"156499","sourceNumber":"156499","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A Infertilidade é definida como:","options":{"A":"3 meses de coito desprotegido sem gravidez","B":"6 meses de coito desprotegido sem gravidez","C":"9 meses de coito desprotegido sem gravidez","D":"12 meses de coito desprotegido sem gravidez"},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-156431","number":"156431","sourceNumber":"156431","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação ao mioma temos que é:","options":{"A":"Tumor benigno, capsulado e monoclonal.","B":"Tumor benigno, pseudocapsulado e monoclonal.","C":"Tumorbenigno, não capsulado e policlonal.","D":"Tumor benigno, não capsulado e monoclonal."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-154611","number":"154611","sourceNumber":"154611","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Sobre a infertilidade, assinale a alternativa INCORRETA:","options":{"A":"Na astenozoospermia é impossível a realização de fertilização in vitro.","B":"A diminuição da fecundidade feminina começa logo após os 30 anos e acelera por volta dos 40\nanos.","C":"O sucesso no nascimento de bebês vivos depende da idade dos óvulos, não da idade materna.\n\nUma paciente de 40 anos, com óvulos doados de uma de 25 anos, tem as mesmas taxas de\nsucesso de uma paciente de 25 anos.","D":"O FSH é um importante marcador de reserva ovariana.","E":"Elevações dos níveis séricos de progesterona constituem evidência indireta de ovulação."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-156990","number":"156990","sourceNumber":"156990","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma adolescente, que começou a apresentar ciclos menstruais aos 13 anos, hoje os\napresenta menores que 21 dias e com período menstrual maior que 8 dias. Esses eventos são,\nrespectiva e corretamente, denominados:","options":{"A":"Espaniomenorreia e metrorragia.","B":"Polimenorragia e metrorreia.","C":"Polimenorreia e hipermenorreia.","D":"Menorragia e espaniomenorreia."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-156998","number":"156998","sourceNumber":"156998","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"É uma patologia ginecológica comum na quarta década de vida, que acarreta útero\nglobalmente aumentando de volume, dismenorreia e hipermenorreia:","options":{"A":"Adenomiose.","B":"Endometriose.","C":"Miomatose uterina.","D":"Pólipo endometrial."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-157003","number":"157003","sourceNumber":"157003","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em qual das situações a seguir se poderia selar o diagnóstico de endometriose?","options":{"A":"Paciente com queixa de dispaurenia, dismenorreia e esterilidade.","B":"Presença de CA-125 positivo no 32 dia de menstruação.","C":"Videolaparoscopia com biópsia positiva.","D":"Presença de endometrioma à ultrassonografia intravaginal."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-160503","number":"160503","sourceNumber":"160503","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A histologia da adenomiose revela:","options":{"A":"presença de glândulas endometriais e estroma na intimidade do músculo uterino.","B":"mesmo padrão e localização da endometriose.","C":"alterações pré-malignas do endométrio.","D":"alterações pré-malignas do músculo uterino."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-157272","number":"157272","sourceNumber":"157272","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 60 anos com quadro de sangramento vaginal pós-menopausa. Dentre as\nalternativas a seguir, qual não é uma possível causa?","options":{"A":"Atrofia endometrial.","B":"Pólipo endometrial.","C":"Mioma subseroso.","D":"Neoplasia cervical.","E":"Hipertrofia endometrial."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-157360","number":"157360","sourceNumber":"157360","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em relação aos leiomiomas uterinos, assinale a opção INCORRETA:","options":{"A":"A maioria das mulheres com leiomioma é assintomática.","B":"Sangramento e/ou dor são os sintomas mais comuns.","C":"Dor aguda pode sugerir torção do mioma.","D":"O leiomioma não é causa de infertilidade."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-157370","number":"157370","sourceNumber":"157370","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente, 65 anos, menopausada sem terapia de reposição hormonal, ocorrendo um\nsangramento via vaginal. Frente a esse caso, pode-se afirmar que a causa MAIS frequente é:","options":{"A":"Miomatose uterina.","B":"Pólipo endometrial.","C":"Câncer de endométrio.","D":"Atrofia endometrial."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-150709","number":"150709","sourceNumber":"150709","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma criança de dois anos com sangramento vaginal leve e corrimento fétido, com lesão\npolipoide e friável em fundo de saco vaginal, que à ultrassonografia se apresenta como tumoração\ncomplexa de 2cm em parede fúndica-lateral esquerda, tem como hipótese diagnóstica mais\nprovável:","options":{"A":"Corpo estranho.","B":"Tumor botrioide.","C":"Vaginite granulomatosa","D":"Sarcoma vaginal."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-150717","number":"150717","sourceNumber":"150717","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher de 49 anos, nuligesta, com Sangramento Uterino Anormal (SUA) há dois anos,\ncaracterizado por alterações dos intervalos, episódios de hipermenorragia e dismenorreia\nocasional, mostrando na ultrassonografia útero com volume de 190 cm³, com nódulos hipoecoicos\nsubserosos e ovários normais, tem como principal hipótese diagnóstica para o SUA:","options":{"A":"Miomas uterinos.","B":"Endometriose.","C":"Adenomiose.","D":"Perimenopausa."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-157403","number":"157403","sourceNumber":"157403","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Casal com queixa de infertilidade procura atendimento médico referindo ciclos\novulatórios, ultrassom endovaginal e espermograma normais. Sobre esse caso, indique a\nalternativa que apresenta o próximo passo na investigação:","options":{"A":"Histerossalpingografia.","B":"Biópsia endometrial.","C":"Teste pós-coito.","D":"Solicitar espermocultura."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-157407","number":"157407","sourceNumber":"157407","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Em caso de endometriose severa, com comprometimento das atividades diárias da\nmulher, uma alternativa terapêutica que provoca uma ?ooforectomia medicamentosa?, com\nsupressão de função ovariana, tem como droga mais eficaz o:","options":{"A":"Danazol.","B":"Anticoncepcional combinado oral contínuo.","C":"Anticoncepcional combinado oral com pausa de 7 dias.","D":"Agonista do GnRh."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-149188","number":"149188","sourceNumber":"149188","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 60 anos, menopausada há 8 anos, fez uso de TRH por 5 anos, refere há 3\nmeses sangramento vaginal em pequena quantidade, sem cólicas, nega relação sexual, nega\ncorrimento. Ao US, mostra endométrio de espessura 12 mm, sem outras patologias. Diante desse\ncaso, aponte a MELHOR conduta.","options":{"A":"Uso de ACO para parar o sangramento.","B":"Histerectomia abdominal.","C":"Seguimento com US anual.","D":"Histeroscopia."},"answer":"D","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-149193","number":"149193","sourceNumber":"149193","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente nuligesta, 25 anos, refere ciclos regulares, porém, ultimamente, o fluxo\nmenstrual está aumentado e com mais dias de\nduração, com cólicas nesse período. Fez US que\nmostrou mioma uterino de 3 cm, intramural/submucoso, desviando levemente o endométrio. Deseja\nengravidar ano que vem. Diante de tal caso, indique a MELHOR conduta.","options":{"A":"Tratamento com Análogo GnRh e, posteriormente, miomectomia por histeroscopia.","B":"Miomectomia por vídeo laparoscopia.","C":"Tratamento com ACO com progesterona.","D":"Histerectomia subtotal."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-138654","number":"138654","sourceNumber":"138654","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"No seguimento terapêutico de endometriose pélvica, o melhor período para dosar\nCA 125, em relação ao ciclo menstrual,\ncorresponde aos dias entre:","options":{"A":"7 a 9.","B":"1 a 3.","C":"11 a 14.","D":"17 a 19."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-138608","number":"138608","sourceNumber":"138608","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Mulher com 44 anos, G2 P2, apresenta ciclos menstruais regulares e eumenorreicos,\nassintomática, foi submetida à ultrassonografia pélvica de rotina ginecológica. O exame\nmostrou útero aumentado em 15% do esperado, às custas de dois miomas subserosos, cada um\nmedindo cerca de 2,5 cm de diâmetro. Sobre este caso, está correto afirmar que:","options":{"A":"O melhor tratamento é com progestagênios.","B":"Há indicação de miomectomia para estudo anatomopatológico.","C":"O achado não surpreende, em vista da elevada prevalência dos miomas e pelo fato da maioria\ndos casos ser assintomática.","D":"Anticoncepcionais hormonais são contraindicados neste caso."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-127096","number":"127096","sourceNumber":"127096","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma paciente de 20 anos, com menarca aos 11 anos e inicio da vida sexual aos 17, em\nuso de anticoncepcional hormonal, vem ao\nambulatório de Ginecologia do HUAP referindo\nsangramento uterino anormal. O último exame ginecológico ocorreu há 1 ano. Em vista do quadro,\na conduta a ser seguida é:","options":{"A":"Indicar ultrassonografia transvaginal para mioma subseroso.","B":"Solicitar HCG para afastar hipótese de gravidez.","C":"Fazer colpocitologia oncótica, assim que parar o sangramento, para afastar hipótese de HPV.","D":"Marcar histerectomia ambulatorial com biopsia dirigida para afastar hipótese de hiperplasia de\nendométrio.","E":"Prescrever Premarin® 20 mg IM para evitar anemia."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-127984","number":"127984","sourceNumber":"127984","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Uma mulher de 27 anos, nuligesta, sem uso de método anticoncepcional há 2 anos,\nprocura assistência médica para tratamento de\ninfertilidade. Queixa-se de dor pélvica, dismenorreia\ne dispareunia crônicas. O exame ginecológico revela: desconforto ao exame especular, colo uterino\nde aspecto normal, nodulação dolorosa no fundo de saco posterior e espessamento dos ligamentos\nuterossacros. Diante deste quadro clínico, considerando a suspeita de endometriose, é CORRETO\nafirmar que:","options":{"A":"O diagnóstico definitivo é obtido pela ressonância magnética pélvica, preferencialmente com\npreparo intestinal.","B":"O marcador CA-125 é considerado de eleição para firmar o diagnóstico de endometriose,\nprincipalmente quando os valores são superiores a 95 UI/ml.","C":"Os endometriomas ovarianos não respondem bem ao tratamento medicamentoso, sendo a\ncirurgia indicada nos casos de endometriomas sintomáticos ou grandes.","D":"Os locais mais comumente comprometidos pela endometriose pélvica são, respectivamente,\nligamentos uterossacros, fundo de saco posterior,\novários e fundo de saco anterior e folheto\nposterior do ligamento largo."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-128000","number":"128000","sourceNumber":"128000","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"O exame considerado padrão-ouro na investigação do fator tuboperitoneal como causa\nde infertilidade feminina é:","options":{"A":"Laparoscopia.","B":"Histerossalpingografia.","C":"Histeroscopia.","D":"Ecografia tubária."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-136654","number":"136654","sourceNumber":"136654","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 22 anos, com atraso menstrual de 40 dias, fez BHCG, que deu positivo,\nporém refere fortes dores em fossa ilíaca esquerda, sangramento vaginal escuro, palidez,\ntaquicardia e hipotensão. Qual é a HIPÓTESE diagnóstica para esse caso?","options":{"A":"Doença inflamatória pélvica.","B":"Apendicite.","C":"Gravidez ectópica.","D":"Aborto completo."},"answer":"C","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-129832","number":"129832","sourceNumber":"129832","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"A puberdade precoce verdadeira ou central decorre de ativação prematura do eixo\nhipotálamo-hipófise-ovário, antes dos oito anos de idade, levando à produção de gonadotrofinas e\nesteroides sexuais. A principal causa desse tipo de puberdade é:","options":{"A":"Iidiopática.","B":"Tumores do sistema nervoso central.","C":"Traumas no sistema nervoso central.","D":"Tumores da sela túrcica."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-2-127329","number":"127329","sourceNumber":"127329","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Paciente de 33 anos, nuligesta, tentando engravidar há 2 anos sem sucesso,\nvem para consulta de rotina, nega morbidades\ne medicações, refere ciclos regulares de 28 dias,\nporém refere dores intensas durante a menstruação e após término de menstruação por 5 dias.\n\nDiante de tal caso, podemos suspeitar de qual patologia?","options":{"A":"Pólipo endometrial.","B":"Síndrome dos ovários policísticos.","C":"Câncer de endométrio.","D":"Endometriose."},"answer":"A","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-2-103696","number":"103696","sourceNumber":"103696","collectionBlock":"medcurso:medcurso-gineco-gin-2","collectionLabel":"Medcurso · GIN 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 2","subtopic":"","stem":"Videocirurgia ginecológica engloba os seguintes procedimentos:","options":{"A":"Histeroscopia, laparoscopia ginecológica, sacropromonto fixação do reto, abordagem de\naderências pélvicas.","B":"Histeroscopia, laparoscopia ginecológica, videocirurgia das tubas uterinas, abordagem de\naderências pélvicas.","C":"Salpingectomia, laparoscopia ginecológica, proctopexia, abordagem de aderências pélvicas.","D":"Salpingectomia, cirurgias do útero, proctopexia, abordagem de aderências pélvicas."},"answer":"B","source":"Gineco/GIN 2/GIN 2.txt","sourceLabel":"Medcurso · GIN 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
